{index="20041",text="[以一等星為目標]愛慕織姬"},
{index="20042",text="[呼喊吧！模範式問候！]櫻花驀進王"},
{index="20043",text="[一天落幕之時]特別週"},
{index="20044",text="[溫暖♪心動回憶]真機伶"},
{index="20045",text="[挑戰極限!?賽馬娘♡偶像]醒目飛鷹"},
