{index="30241",text="[指引之光]體現傳說之人"},
{index="30242",text="[改變世界的眼神]杏目"},
{index="30243",text="[NEW TALES AWAIT]放聲歡呼"},
{index="30244",text="[春日今至]目白光明"},
{index="30245",text="[Ballroom Tempest]伏特加"},
{index="30246",text="[如夢似幻的誘惑]夢之旅"},
{index="30247",text="[Operation: Escort]克莉斯耶絲象徵"},
{index="30248",text="[純潔的白妙櫻]謀勇兼備"},
{index="30249",text="[聯繫吧！遊行節奏♪]創升"},
{index="30250",text="[Luz de ensueño]迷人景致"},
{index="30251",text="[約定的glitter]希望城市"},
{index="30252",text="[My Beloved Scenery]無聲鈴鹿"},
{index="30253",text="[Unveiled Dream]萊茵實力"},
{index="30254",text="[Blooming Buds]勇敢之心"},
{index="30255",text="[終將茂盛的新芽]空中彌賽亞"},
{index="30256",text="[宛如白色閃電]玉藻十字"},
{index="30257",text="[本能有在咆哮嗎！？]塔可拜茵"},
{index="30258",text="[眼燃鬥志胸懷對勝利的渴望]目白雷恩"},
{index="30259",text="[絕對☆天才傳說]房一潘朵拉"},
{index="30260",text="[灰調PARTY☆]目白麥昆"},
{index="30261",text="[水面的首席舞者]凱旋芭蕾"},
{index="30262",text="[Tranquillo]大鳴大放"},
{index="30263",text="[帶著最甜美的笑容出發～♪]比布魯斯"},
{index="30264",text="[隨心所欲的流星]黃金旅程"},
{index="30265",text="[冰晶的靜域]愛慕律動"},
{index="30266",text="[在前方的未來]時代創世"},
{index="30267",text="[浮岩光王是隻貓]浮岩光王"},
{index="30268",text="[今宵為了主君]杜蘭達爾"},
{index="30269",text="[因為今天非常開心，]緞通烈焰"},
{index="30270",text="[Inseparable]第一紅寶"}
}
p.text_data_88={
{index="10001",text="我叫做特別週！<br>夢想是成為日本第一賽馬娘！<br>為了讓兩個媽媽開心……我會加油唄！"},
{index="10002",text="我是無聲鈴鹿。喜歡跑步。<br>領先位置絕不會讓給任何人。<br>那個……我說完了。"},
{index="10003",text="呀吼～我是東海帝皇喔！<br>我會成為全勝的三冠賽馬娘，<br>絕～對不要錯過我的表現喔！"},
{index="10004",text="嗨～我是丸善斯基唷！<br>你也是來看異次元的奔馳對吧？<br>呵呵♪到時看得無法自拔……我可不管喔♪"},
{index="10005",text="我是小栗帽。<br>為了讓故鄉的大家開心，<br>我會盡全力加油。請多指教。"},
{index="10006",text="嘿，我是黃金船大人啦！<br>不管是要上刀山還是要下草皮，甚至要到宇宙盡頭也無所謂！<br>好玩的事情在哪裡，我就往哪裡走☆"},
{index="10007",text="嗨，我是伏特加！我的原則是<br>當個比誰都帥的賽馬娘！<br>看起來很遜的事我絕對不做。給我記住了！"},
{index="10008",text="Howdy！我是大樹快車！<br>我會用我充滿力量的奔跑，<br>讓大家都Happy喔～！"},
{index="10009",text="我叫做草上飛。<br>既然生為賽馬娘，我就會努力<br>在這條「道路」上達到極致。呵呵♪"},
{index="10010",text="我叫做目白麥昆。<br>目白家稱霸「天皇賞」的宿願──<br>我一定會靠自己的雙腳達成。"},
{index="10011",text="在賽道上奔馳的鮮紅怪鳥！<br>神鷹，登、場！<br>放眼世界狂飆起飛吧～！"},
{index="10012",text="哈～哈哈哈！我就是<br>最強、最美的「霸王」好歌劇！<br>來吧，讓我們開拓新的傳說！"},
{index="10013",text="我是魯道夫象徵。立志成為站在<br>所有賽馬娘的頂點，領導大家的「皇帝」。<br>懷抱相同志向的同志，與我一同勇往直前吧。"},
{index="10014",text="呀呼～我是青雲天空喔～<br>適度又隨便地悠閒過生活吧～<br>……要釣大魚的話，耐心等待也很重要對吧？"},
{index="10015",text="我……我叫米浴。聽、聽米浴說喔……？<br>米浴會害大家不幸……是個壞孩子。<br>可是……我、我會努力……做出改變的！"},
{index="10016",text="我我我！我的夢想是成為<br>打比賽馬娘！還有……啊──！！名字！！！<br>我是勝利獎券！請多指教喔──！"},
{index="10017",text="我是黃金城市……話說在前頭，<br>可不許把我當成洋娃娃。<br>別從外表，而是從實力來評斷我。"},
{index="10018",text="你好！我是櫻花驀進王！<br>如你所見，我還是個優秀的班長！<br>我要成為大家的典範，衝啊！驀進～！"},
{index="10019",text="呵呵呵，我是超級小溪唷～<br>為了讓大家都能充滿笑容，<br>我會盡全～力好好加油。包在我身上♪"},
{index="10020",text="我叫春烏菈菈！我最～喜歡胡蘿蔔<br>跟跑步了，因為跑起來很開心喔♪<br>目標是第一名，我會超級努力的喔～！"},
{index="10021",text="你好，我是特雷森學園的理事長祕書<br>駿川手綱。為了讓大家過上更好的<br>學園生活，我會支援大家♪"},
{index="10022",text="你好，我是桐生院葵，是特雷森學園的<br>新人訓練員。雖然還有許多不成熟之處，<br>但我會為了賽馬娘全力加油！"},
{index="10023",text="你好，我是大和赤驥！<br>我會盡全力好好……喔，是你啊。哼！<br>我的目標只有第一。其他結果我都不接受！"},
{index="10024",text="有很多表情很不錯的傢伙嘛……<br>嘿嘿，就由我菱亞姐姐<br>當妳們所有人的對手！來單挑吧！"},
{index="10025",text="我是氣槽。只要信念沒有動搖，<br>理想一定會萌芽。為了展現這點，<br>我作為「女帝」會指引眾人前進的。"},
{index="10026",text="辛苦了！我是小數！<br>我支持著許多閃閃發亮的賽馬娘喔！<br>每天都很幸福！生為阿宅真是太好了～♪"},
{index="10027",text="我是玉藻十字！我要在競賽中<br>一贏再贏、百戰百勝、名滿天下！<br>別因為個子小就小看我喔！"},
{index="10028",text="您好，我是美妙姿勢！<br>我希望能在這裡創造很多很棒的回憶。<br>首先我想知道好吃的拉麵店♪"},
{index="10029",text="我是琵琶晨光。我的目標是<br>建立一套完美的勝利方程式……<br>還有，我的頭大小很正常！"},
{index="10030",text="嘿嘿嘿，我是重重喔～☆<br>我最喜歡讓人雀躍的事～<br>還有刺激的事了♪請多指教～！"},
{index="10031",text="……我是曼哈頓咖啡。<br>我有個……想要追上的朋友……<br>是那個一直跑在我前面的女生……看，就在那邊……"},
{index="10032",text="我的名字是美浦波旁。<br>目標設定為三冠賽馬娘。<br>關於我的腳質等資訊，請參閱相關資料。"},
{index="10033",text="我叫目白雷恩！<br>鍛鍊身體充滿活力！培養肌肉，<br>身體健康！拿出幹勁加油吧！"},
{index="10034",text="我、我叫做雪之美人！<br>我的夢想是成為在散耀系列賽<br>大為活躍的都市女孩！呼……好好說出來了……"},
{index="10035",text="哈囉哈囉～！我是艾尼風神！<br>為了讓所～有家人都開心，<br>不管競賽還是打工，我都會盡全力加油喔～！"},
{index="10036",text="你有沒有興趣知道，賽馬娘究竟能<br>快到什麼地步？要是有的話……<br>就來當我愛麗速子的白老鼠吧。"},
{index="10037",text="我是空中神宮。不管是怎樣的比賽，<br>數據都能說明一切。模擬數值沒有任何問題。<br>所有人都會屈服在我的邏輯之下。"},
{index="10038",text="我叫榮進閃耀。<br>為了守護賽馬娘的傳統，我會持續奔跑下去。<br>無論是什麼競賽，一切都照預定進行。"},
{index="10039",text="我是醒目飛鷹～！叫我飛飛吧！<br>我的夢想是成為賽馬娘偶像！<br>隨時都歡迎大家來找我簽名喔☆"},
{index="10040",text="成田大進。就這樣。我只是想<br>一直贏下去，讓曾經瞧不起我的人<br>看到我的實力……不要管我。"},
{index="10041",text="你好，我是西野花。<br>我希望能成為受大家依賴<br>又完美的大姐姐賽馬娘……！"},
{index="10042",text="正義英雄，微光飛駒登場！<br>不管怎麼樣的強敵，我的奔馳都能<br>在一瞬間咻咻咻～地擊敗他們，讓大家露出笑容！厲害吧！"},
{index="10043",text="嗨嗨～我是美麗週日～！<br>要把美麗的心情送給全世界喔！<br>來，大家也一起美麗吧！"},
{index="10044",text="你好，我叫待兼福來！<br>我相信白興大人的神諭，<br>一直期待著哪天能掌握幸福……<br>同時每天也都很努力在占卜！"},
{index="10045",text="我、我是名將怒濤……！那、那個，<br>我想對自己更有自信，<br>所以盡我所能努綠……吃、吃螺絲了！"},
{index="10046",text="你好……那個，我是目白多伯。<br>我也是目白家的賽馬娘，而且<br>也打算……展現不會使家族蒙羞的奔馳。"},
{index="10047",text="啊……我是優秀素質～啊哈哈。<br>不過感覺還是沒辦法名符其實吧……<br>唉～總之就一點一點努力吧？"},
{index="10048",text="喔～呵呵！我的名字叫帝王光輝。<br>身為一流賽馬娘，一定會創下最棒的成果！<br>……畢竟要向世界展示我的才能嘛！"},
{index="10049",text="我是逗大家開心的漆黑表演者，<br>富士奇石！我一定會用<br>最棒的「奇蹟」讓你露出笑容！"},
{index="10050",text="東商變革是變身前的名字！<br>我是魔法少女Sweepy！<br>這就是魔法！看我的！！（碰）"},
{index="10051",text="我是雙渦輪──！<br>渦輪會拿到第一名，一定會拿到！<br>要上囉──渦輪全開────！！"},
{index="10052",text="喔耶──！我是大德太陽──！<br>我會在嗨翻天的競賽上猛衝，<br>麻煩給我最高亢的歡呼聲☆"},
{index="10053",text="我名叫生野狄杜斯。<br>管理方面還請交給我，<br>我會用鋼鐵意志進行徹底管理。"},
{index="10054",text="我是目白善信！今天過得好嗎～？<br>什麼事情都可以跟我說，<br>隨時都能找我聊聊喔♪"},
{index="10055",text="我是北部玄駒！<br>我的目標是跟大家在如同祭典般<br>熱鬧、最棒的競賽中，盡全力奔馳！"},
{index="10056",text="我叫里見光鑽。<br>沒有命運是一開始就決定好的，<br>未來會被我奔馳的光輝所照亮！"},
{index="10057",text="哈囉──我是待兼唐懷瑟。<br>為了別輸給大家，今天也要努力練習……<br>什麼，今天休息！？"},
{index="10058",text="我是八重無敵。身為<br>金剛八重垣流的門徒，我期望能跟強者競賽。<br>讓我們堂堂正正地一決勝負吧！！"},
{index="10059",text="我的名字叫荒漠英雄。那個……<br>別看我這樣，我很嚮往英雄傳說……<br>希望有一天，能在競賽中寫下屬於我的故事……"},
{index="10060",text="我是樫本理子。<br>照顧賽馬娘的健康是訓練員的職責。<br>工作時抱持緊張感是理所當然的。"},
{index="10061",text="呵呵呵呵！我叫採珠！<br>你知道嗎？這世界充滿了可能性。<br>我會證明這點給你看！"},
{index="10062",text="我、我是櫻花千代王！<br>想要跟崇拜的人一起站上夢想的舞台。<br>這個心願──我會讓它開花結果的！"},
{index="10063",text="哦──呵呵呵！我叫川上公主……<br>氣質高雅，是公主中的翹楚！<br>即使在競賽中，也會用動人的模樣奔馳！！"},
{index="10064",text="Buono～♪我是菱曙～☆<br>不論是料理還是跑步，都會注入滿～滿的<br>愛意獻給大家！請多指教囉～♪"},
{index="10065",text="大家好！我是青竹回憶！<br>我會賭上魔鬼糾察隊長的名號<br>拚命跑下去──！！"},
{index="10066",text="嘎吼～！我是新光風！<br>嚇到了嗎？趕快老實承認你害怕了～！<br>……欸！別不理人！我咬──！"},
{index="10067",text="我是中山慶典。<br>對於溫和的競賽感覺不到刺激。<br>欸……再讓我感受更多熱血激情吧……！"},
{index="10068",text="少囉嗦！我是稻荷一！<br>如你所見，我可是道地的江戶之子！<br>會成為比任何人都厲害的賽馬娘！"},
{index="10069",text="我叫目白阿爾丹。雖然這雙腳<br>很脆弱，但我還是想帶著自信奔馳……<br>哪怕只有瞬間也好，我想在競賽中閃耀。"},
{index="10070",text="我叫島川喬登。夢想是……<br>這種嚴肅的話題對我來說NG，多指教啦～☆<br>總之先看一下我的指甲吧？很炫吧？"},
{index="10071",text="我是天狼星象徵！對於競賽<br>沒有什麼想說的，你就默默看著吧。<br>我會征服世界證明自己是最強的。"},
{index="10072",text="……我是成田白仁。<br>沒有什麼特別需要說的。<br>反正跑下去，遙遙領先然後獲勝就對了。"},
{index="10073",text="Curren就是我，我叫真機伶！<br>想用「可愛」把全世界包起來☆<br>不可以看其他地方，只能看著我喔♪"},
{index="10074",text="我是高超竹針師（的徒弟）安心澤刺刺美。<br>只要被我扎過就會提升威力！<br>Wow，安心～☆"},
{index="10075",text="我是愛慕織姬。可以走了嗎……？<br>我要進行更多訓練，在更多競賽中拿下勝利，<br>因為我必須成為最明亮的一顆星。"},
{index="10076",text="……哎呀？現在要自我介紹嗎？<br>呵呵，我叫目白光明。<br>身為目白家的一份子，我會好好努力的～"},
{index="10077",text="大家好，我是成田路！<br>我會盡全力表現，來回應大家<br>對我的期待！"},
{index="10078",text="競賽中有著只在當下才會吹起的風。那是既柔和<br>又清新……自由自在的順風喔。<br>──我是千明代表，請多指教。"},
{index="10079",text="我叫第一紅寶。<br>展現極致的表現，正是我一族的職責所在。<br>我會貫徹己身應盡的責任，向前邁進。"},
{index="10080",text="……我是喜嘉奇蹟。<br>為了回報各位給我的生命……<br>我一定會，創造奇蹟。"},
{index="10081",text="鶴丸強志！目標是成為自己憧憬的<br>「三冠賽馬娘」！總之盡全力──咳咳！<br>……只、只是嗆到而已！我很好別擔心！"},
{index="10082",text="──我是克莉斯耶絲象徵。象徵家對我有恩。<br>身為其一員，無論是樹立的目標<br>還是被賦予的mission──都必得達成。"},
{index="10083",text="我是明亮光暈，主要業務是負責活動企畫。<br>請讓我為在舞台上發光發熱的各位……<br>盡一點微薄之力。"},
{index="10084",text="我是谷水琴蕾！追求目標是理想中的「吾」。<br>我無意以一時的軀殼偽裝自已。<br>破壞、踹破吧──然後朝向終結，前進吧！"},
{index="10085",text="我是櫻花桂冠。我的目標是世界，<br>也就是凱旋門賞！──呵呵，雖然現在<br>還只是個「夢想」……但總有一天我一定會實現。"},
{index="10086",text="……我是山人西風。<br>我追求的是成為風……比任何事物都要快、<br>都要自由的──風，正是我的目標。"},
{index="10087",text="我是小真──奧斯頓真弓。<br>有一天將變成世界的吉祥物。<br>請你一定要親眼見證喔。"},
{index="10088",text="你想瞭解我嗎？那就到賽場上來吧。<br>目白拉茉奴的……我的一切就在那裡。"},
{index="10089",text="我是叢林口袋啦。<br>想賽跑的話，我可以奉陪哦。<br>不過我不會將「最強」寶座拱手讓人就是了。"},
{index="10090",text="儂是從北方港灣飛來的紙翼候鳥♪<br>苫小牧的地方偶像──北幸樽前！<br>……嗯～是不是應該再想特別一點的呀？"},
{index="10091",text="我是葛城榮主，多多指教啦！<br>有夢想的話就別畏畏縮縮的喔？<br>讓人喘不過氣的高牆就由我來打破！"},
{index="10092",text="Rickey☆Lucky☆大吉利☆<br>我是小林歷奇喔！<br>讓我用風水的力量帶給你happy吧♪"},
{index="10093",text="我是奇銳駿。雖然看起來悠悠哉哉的，<br>但我其實很擅長一點一滴地努力喔。<br>請多指教囉～"},
{index="10094",text="我是佐岳鳴！關於歐洲競賽的分析工作<br>就交給我。和我一起達成稱霸「凱旋門賞」<br>這個仍無人達成的夢想吧！"},
{index="10095",text="來吧，踏上令人雀躍的旅途！<br>享受與夥伴起舞的每一天！Everyone!<br>想追夢的所有人──快搭上踢踏城市的船吧！"},
{index="10096",text="我是愛如往昔……我……沒什麼。<br>沒有什麼特別要說的事……<br>真要說的話，就只有……得保密的事……"},
{index="10097",text="我是極峰。<br>直到突破所有難關成為女王的那一天，<br>我絕不會被挫折打敗！"},
{index="10098",text="哦哦，我所深愛的musicista們啊！<br>今天也與我萬籟爭鳴，<br>一起演奏出彼此的melodìa吧！"},
{index="10099",text="我是比布魯斯哦！總有一天我一定要在<br>閃閃發光的杜拜參加名流般的競賽♪<br>我們一起去吧！這件事已經說定了嘛♪"},
{index="10100",text="唯一的渴望──就是「最強」的稱號！<br>我想成為留在人們記憶中的賽馬娘！<br>為此我需要的……沒錯，就是表現自我！"},
{index="10101",text="……我是大鳴大放。<br>我的目標不是勝利，而是更遠大的「最強」。<br>……就這樣。"},
{index="10102",text="嗨，我是北方飛翔！我喜歡服裝搭配、彩妝、<br>飾品，以及堅持不懈的努力。<br>還請看著我藉由這一切所琢磨出來的光芒！"},
{index="10103",text="太失敬了，快給我跪下。<br>──伏首跪拜在我黃金巨匠的霸道前吧。"},
{index="10104",text="我是都留岐涼花，<br>每天的工作是企劃製作各種豐富的內容，<br>將最棒的感動獻給各位。"},
{index="10105",text="……我是高尚駿逸。那個……雖然我明白<br>說這種話很不自量力，但……總有一天──<br>我、我會成為偉大的……沒事，我會加油的。"},
{index="10106",text="新宇宙提議<br>進行友好的「接觸」。<br>我的意思是──「請多指教囉」。"},
{index="10107",text="嗯，我是菱奇蹟。<br>我會拿出還算過得去？的幹勁盡量努力一下～<br>請多多指教～"},
{index="10108",text="我是緞通烈焰喔。<br>好了好了，別吵架嘛。<br>吃點甜食，好好加油～如何啊？"},
{index="10109",text="我是理事長秋川彌生！為了本校學生<br>以及支持她們的訓練員我會竭盡全力！！<br>希望各位可以儘管依賴我！"},
{index="10110",text="我是希望城市！競賽正合我意！<br>我會讓所有人輸到叫苦連天……<br>喂住手！摸什麼摸啊！"},
{index="10111",text="我宣告。「身為先鋒隊長，<br>將會掀起四大天王旋風！」<br>我們一起讓夢想膨脹得更大吧！"},
{index="10113",text="過程和道理這種東西一點意義也沒有。<br>贏家就是正義，不是嗎？<br>貴婦人會讓一切臣服。"},
{index="10114",text="我是萊茵實力！希望自己能繼承意志，<br>開拓出與未來聯繫的道路。<br>我想成為那樣的后冠賽馬娘！"},
{index="10115",text="我的宿願，是戴上后冠，<br>成為光輝未來的基礎。<br>──還請多多指教囉♪"},
{index="10116",text="我是疾風裝束喔！<br>人們很溫柔，所以我最最最喜歡人們了！<br>我想多和人們接觸，感情變得更好喔──！！"},
{index="10117",text="呀～哈哈，我正是無需理由！<br>為了統一天下，我將不擇手段。<br>來吧下剋上～！"},
{index="10118",text="我是迷人景致。我的夢想是<br>實現約定──抵達絕景。<br>還請多多指教，訓練員……呵呵！"},
{index="10119",text="若想商量遠征還請找我夢之旅……<br>來場恍若身處夢境般的旅途吧。<br>因為你有著那樣的價值。"},
{index="10120",text="我是謀勇兼備。為了嚴厲卻不失溫暖地孕育<br>我的故鄉……我要懷著遠大的夢想，<br>那就是「成為名留青史的賽馬娘」！"},
{index="10121",text="Follow my lead! 請拭目以待吧。<br>后冠的光輝必將沐浴在我身上──<br>沐浴在未來的女王，勇敢之心身上！"},
{index="10122",text="我是杏目。即使對手是傳奇，<br>我也會獲勝。並非別人，<br>而是我自己堅信著這一點！"},
{index="10123",text="我是幸運歐丁香。<br>為了成為賽場焦點，我會忍過各種的試煉。<br>還請多多指教。"},
{index="10124",text="嗨，我是放聲歡呼！<br>不論是0.75哩或是1.25哩，<br>未來的一哩女王是不會輸的！"},
{index="10125",text="那麼就請多多指教囉～阿訓♪<br>一起去尋找那些無比刺激<br>又令人期待的事物吧！"},
{index="10126",text="我是機伶金花。我的興趣是<br>把花擺飾得美美的。還有，我想想……<br>我不太喜歡──和人起紛爭。"},
{index="10127",text="目標是像母親那樣……強大又華麗的賽馬娘。<br>我是空中彌賽亞──我將親自證明<br>那份傳承的偉大與延續未來的可貴"},
{index="10128",text="我的名字是塔可拜茵！我期許能讓各位<br>賽馬娘更上一層樓，因此成立了<br>無人島計畫！來吧，解放本能啦──！"},
{index="10129",text="我是房一潘朵拉～♡<br>我真的超～天才，不需要別人操心♡<br>所～以～囉～麻煩別用毅力鍛鍊那一套喔♡"},
{index="10131",text="我是凱旋芭蕾。要成為主角……<br>要成為首席就只能努力不懈！<br>雖然周圍都是強者，但我不會氣餒的！"},
{index="10132",text="我是黃金旅程，請多指教。<br>來，與我隨興踏上黃金般的旅途，<br>展開一場愉快的旅行吧！"},
{index="10133",text="我是愛慕律動。<br>我不需要別人對我寬容或溫柔。<br>我只想不斷提升自己……僅此而已。"},
{index="10134",text="我是時代創世。<br>最喜歡做的事就是鑽研競賽的歷史。<br>而我自己……也想在歷史刻下自己的蹄跡。"},
{index="10135",text="我是浮岩光王。<br>夢想是刷新最高速度，喜歡直線。<br>就這樣。自我介紹也是最快的。"},
{index="10136",text="我的聖劍將釋放疾馳的光輝，<br>斬除加諸於你的黑暗！<br>我是杜蘭達爾，誓言與忠義之騎士！"},
{index="20001",text="彷彿追著太陽奔跑，一直奔馳到日落。<br>那就是這間特雷森學園學生的青春。<br><br>「那麼，大概是這樣吧。」<br><br>如此喃喃自語的她，看向眼前的<br>運動飲料以及幾個鹽味飯糰。<br>這樣還少的就是……<br><br>「呼啊、呼啊……小特，快一點。」<br><br>「鈴、鈴鹿……我已經、跑不動了～」<br><br>「呵呵，抵達了啊。這樣就到齊了。」<br><br>瞥向已超過門禁時間的時鐘指針，<br>她往宿舍的玄關走去。<br>首先要好好告誡她們必須嚴守門禁……<br>然後再好好慰勞她們的努力。<br><br>這就是屬於這特雷森學園宿舍長的青春。"},
{index="20002",text="「這裡要用這個公式……」<br><br>似乎都沒察覺到自己脫口而出的自言自語。<br>旁邊放著翻爛的參考書，<br>不斷動筆書寫的筆記本上<br>記滿了井然有序的公式。<br>不經意地，<br>我回憶起她曾這樣如此提過她的母親。<br><br>「媽媽是個做什麼都很優秀的賽馬娘。<br>是我崇拜的對象。」<br><br>如此說過的她，<br>現在像是要追上母親般默默地振筆疾書。<br>看著她這麼拚命努力的樣子，<br>不想打擾的我選擇靜靜離開。"},
{index="20003",text="萬里無雲的晴空之下。<br>大家都在呼喊她的名字，讚揚那份勝利。<br><br>「哈哈，感覺真棒。<br>……仔──細看好了！<br>我在下場競賽也會全力以赴！」<br><br>眼前是轟然巨響的歡呼聲。<br>然而，她的思緒卻飄向了遠方。<br>注視著那個跑在前方的怪物──"},
{index="20004",text="「接下來只剩下這個裝飾。<br>……所有人都有鼓起幹勁！」<br><br>粉絲感謝祭的準備非常順利！<br>這是當然的──因為一切的一切，<br>都由這個號稱女帝的她進行指揮。<br><br>「咦，『阿船特製炒麵販售會』？<br>……是這樣的布條嗎？」<br><br>「啊……？」<br><br>距離女帝的怒雷劈向犯人賽馬娘，<br>還有3秒──！"},
{index="20005",text="TSUI☆GEKI　TSUI☆GEKI<br>( ﾟ∀ﾟ)o彡゜( ﾟ∀ﾟ)o彡゜<br><br>U☆游擊注意注意！（什麼什麼？）<br>M☆彈匣發射一空！（HOO、HOO──！）<br>A☆發動襲擊♪（KO～！）<br><br>TSUI☆GEKI　TSUI☆GEKI<br>( ﾟ∀ﾟ)o彡゜( ﾟ∀ﾟ)o彡゜<br><br><br>「FOOOO！萌萌喵很可愛喔～！<br>……唔！？咦、這、等、眼、對──」<br><br><br>※還請稍待※<br><br><br><br><br><br><br>「……呼──在千鈞一髮回神了──<br>竟然在演唱會中靈魂出竅，實在太不小心……<br>……好！重振精神囉──！」<br><br><br>※回到一開始×∞"},
{index="20006",text="「呼……雖然完成了每天的例行項目，<br>但腳的感覺──應該還可以繼續。<br><br>就計算上的活動極限還有……嗯。<br>腿部推舉450公斤做12下的程度啊。<br>……這樣的話──」<br><br>眼鏡閃耀出精光，<br>鏡片下的金眸靜靜燃起火焰。<br><br>「只剩下驗證了……對吧！」<br><br>幹勁十足的她露出認真神情。<br>尾巴也看似愉悅不已地搖擺著。"},
{index="20007",text="閃閃發亮的大晴天！<br><br>「適合進行成熟少女對談的好日子☆」<br><br>搭配有點苦味的超商點心，<br>加上刊登著全新彩妝的時尚雜誌♪<br><br>「啊，上面說牡羊座的愛情運勢最棒喔☆」<br><br>「小曙！還有美容甜點特輯耶♪」<br><br>「呀──！全都不能錯過啊！」<br><br>總是充滿歡笑聲的少女對談！<br>當然也有做好了防曬工作☆<br>因為這就是大人的嗜好♪<br>少女們的談天還會持續下去。<br><br>──要小心別漏聽鐘聲了！"},
{index="20008",text="<br>……，…………？<br><br>「……嗯，沒錯。<br>……所以我畫了……喜歡的圖案。」<br><br>……，…………<br>……，…………，……？<br><br>「呵呵……猜錯了……正確答案是……雲……」<br><br><br>這就是她在雨天和「朋友」說的悄悄話。"},
{index="20009",text=".COMMAND；Squat<br><br>START：0830……<br>　WGT　100㎏+20㎏<br>　SET　10×3<br>……END：<br><br>──筆尖滑過筆記上方停頓下來。<br><br>「哈啊……哈啊……確認到出汗、體溫上升。<br>但是對臀腿的負擔不足。<br>再1 SET……加油，喔──」<br><br>在心中所浮現好友吆喝聲的鼓舞下，<br>她闔上了筆記本。"},
{index="20010",text="──嗶嗶！<br>宣告得分的哨聲響起。<br>球場上的主角獲得勝利。<br><br>「謝謝！大家都表現得很棒！<br>那份聲援鼓舞了我的肌肉喔！」<br><br>閃亮動人的是太陽，<br>還是她的笑容呢？<br><br>她出手征服的是籃框，<br>還是觀眾的心呢？<br><br>所有的答案，都是肯定的。"},
{index="20011",text="「請、請快看！上面寫了Thank you！<br>還有笑臉圖案……太可愛了！」<br><br>「呵呵，雪之也不會輸喔。笑臉。」<br><br>憧憬的新潮咖啡廳。<br>為了成為都會的都市女孩，<br>而踏入的嶄新世界──讓少女散發光輝。<br><br>「好、好了！接下來就是上傳到社群平台……」<br><br>「啊，妳有在經營社群平台啊。<br>……欸，可以追蹤妳嗎？難得有這個機會。」<br><br>「喔！？當當當、當然可以了！」"},
{index="20012",text="20XX.XX.XX<br>某個愛好研究的賽馬娘獨白。<br><br>「我正感到渴望。<br>興奮到會震動突觸的地步。」<br><br>某間在校舍3樓的空教室。<br>被厚重窗簾隔絕外界的陰暗空間<br>──就是所謂的實驗室。<br><br>這都是為了抵達極限的彼方，<br>事象的另一端。<br><br>「去找足以勝任燃料的白老鼠……<br>問問新藥的成果吧。」<br><br>──為了滿足這份永不知足的探究心。"},
{index="20013",text="──嗶。<br><br>鬧鐘響了一聲便安靜了下來。<br>從斜光的角度看來，判斷天氣與預報相同。<br><br>「呼……準時起床。用216秒整理頭髮、<br>310秒換穿運動服……」<br><br>「嗯呀……開始練習安可囉……」<br><br>……一臉幸福的睡臉露出微笑。<br>距離表定時刻已過了5.2秒。<br><br>不過──是讓人高興的誤差。<br><br>「閃耀也得練習……<br>偶像口號才行……喔……」<br><br>「……咦？」"},
{index="20014",text="「1、2……呼……」<br><br>遠離喧鬧的泳池邊。<br>不枉費自己努力做了伸展運動，<br>學生們開始陸續做放學的準備。<br><br>這樣總算可以安靜游──<br><br>「好痛──！？腳抽筋了～～！？<br>救我、救我啊！大進～～！！」<br><br>「～～唔！就──跟──妳──說──！<br>要先好好做伸展運動了吧！」<br><br>少女言行不一地站起身。<br>看來要進入泳池還要好一陣子。"},
{index="20015",text="～新．美麗計畫！！～<br>　　　　　　　製作人：美麗週日<br><br>【大綱】美麗製作基於美麗<br>　　　　且為了美麗的……計畫！！<br>【目標】對世界傳遞美麗的心情<br>【舉辦期間】現在！立即！立刻開始！！<br><br><br>「所以呢☆現在就要開始囉★」<br><br>寫有企劃重要事項的企劃書四處飄散。<br>但是沒空去管這個了。因為──<br>世界正在等待……美麗！！<br><br>※之後有確實整理了散亂的文件。"},
{index="20016",text="太陽從西向東落下！<br>運勢從凶轉往吉……不，是大吉。<br>不不不！會是更高一層的大大吉吧！<br><br>「降臨吧！開運必勝白興大人！」<br><br>取出的是<br>「特製☆福來白興大人諭示單」，<br>可別小看這個！就連競賽運勢<br>都能夠徹底看透。（製作者經驗談）<br><br>「競賽當天……晴、天、偶、爾……」<br><br>「多、雲……之、後……下、雨……<br>咦，這是占卜？……騙人的吧？」"},
{index="20017",text="「幸福要靠自己掌握！」<br>受這句話深深撼動的少女──<br><br>感到有點後悔！<br><br>「好、好難受……還有大家的視線也是……<br>嗚嗚……真的要這樣繞校園一圈……？」<br><br>「沒錯！一切都是獲得幸福的泉源！<br>Let's fight！Let's開運！」<br><br>「幸福的……Let's fight……<br>Let's、開運……！」<br><br>只要努力就一定會有回報。因為──<br><br>幸福其實就近在眼前。<br>一定會有人看見自己的努力……才是！"},
{index="20018",text="說是崇拜有點太過，<br>說是目標又有點不足。<br><br>即使如此，還是想要追上。<br>追上她前方的兩道身影。<br><br><br>「……好，先完成一項。<br>以雷恩的時間為目標。」<br><br><br>視線投射在光亮的賽場上。<br>──另一旁，則有其他人對她的側臉懷抱著憧憬之情。"},
{index="20019",text="沒什麼人的游泳池。<br>恣意游水的不是狼，而是一條魚。<br><br>「沒有比中午的游泳池更棒的好地方。<br>……好，再游一趟作為緩和運動。」<br><br>對已泡皺的指尖視而不見。<br>但流下額際的水珠可說是她努力的證明。"},
{index="20020",text="一流不是一日造成的。<br>一流是聞一知十。<br>一流是專心致志得到第一名。<br><br>「太厲害了！不光是練習內容，<br>竟然連心得都是一流的……！」<br><br>「喔──呵呵呵！<br>如果想變得像我一樣，<br>這個一流的三守則……<br>每天都要加在一起好好拜讀！」<br><br>「是的！一流加一流加一流，<br>所以就是三流……！」<br><br>「沒錯沒錯！…………給我等一下。」"},
{index="20021",text="「辛苦了！」<br><br>某天，我在訓練賽道上<br>看到同屆的訓練員而出聲打招呼。<br>她的臉上有著淡淡的紅暈。<br><br>「我來觀摩練習情況！<br>真是驚人的指導力，讓我深受刺激。<br>……我也不能輸。」<br><br>「我也不會輸……嗯。」<br><br>「溫順……是啊，我重說一遍──<br>我們是不會輸的。<br>一起互相切磋琢磨吧！」<br><br>這份宣言如藍天般清澈。<br>她的眼眸就猶如春天裡灑落林間的閃耀陽光。"},
{index="20022",text="看！鬆軟有彈性，而且還軟綿綿的！<br>這個就是關西的「魷魚燒」！<br>關東的話不是都整隻下去烤嗎？<br>而我們的「魷魚燒」則是像這樣。<br>從小我就經常吃這種點心，<br>可以說是陪伴我長大！<br>……你說現在還是很小？少囉嗦啦！<br><br>真是的，再亂說話就不分給你喔？<br>……騙你的啦，畢竟我很溫柔。<br>來，不用客氣大口吃吧！<br><br>……味道如何？嘿嘿，很好吃對不對！<br>能看到這麼棒的表情，就是關西人無上的光榮！"},
{index="20023",text="+＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝+<br>　　任何人都會乖乖聽從的魔法<br>+＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝+<br>【等級】★★☆☆☆　魔女入門<br><br>【材料】<br>．做了七天月光浴的水<br>．堅信會成功的想法<br><br>【步驟】<br>①用手指沾取做了月光浴的水，畫出五芒星<br>②詠唱對方的全名三次<br>③詠唱一次「話的我從聽」<br>④注入念力後闔上書本（大功告成♪）<br><br>※若被發現，或許會遭到制裁魔法懲罰！？<br>　所以要小心喔☆<br><br>「呵呵呵～太完美了。<br>這樣就能避開明天當倒垃圾值日生的事了！」<br><br><br>制裁魔法「宿舍長的指導」準備發動……<br>魔女的命運究竟會如何！？<br>"},
{index="20024",text="準備萬全、萬無一失！嗨到不行～☆<br>胡蘿蔔汁配上胡蘿蔔棒！<br>再加上洋芋片的話，<br>不來場派對怎麼行！？<br><br>「啊哈哈哈！嗨起來吧～！<br>素質看這邊──♪<br>喔耶──！陪好姐妹拍張照吧～！」<br><br>「咦，等等……」<br><br>來看看，怎麼樣？感覺很嗨呢！<br>不管是睡衣還是我們都超可愛的吧？<br>這個絕對可以圈粉！<br>一定會爆紅～？？天啊，好開心喔☆<br><br>「喔──喬登來啦。<br>過來過來──<br>喝胡蘿蔔汁可以嗎？」<br><br>「OK沒問題～<br>好猛，已經這麼熱鬧了～」<br><br>「是喬登太晚來了！！<br>話說，應該再找多一點人來吧？？<br>把栗東宿舍的大家都拉過來之類的。<br>啊哈！這樣就嗨翻天啦──☆」<br><br>派對的精彩之處現在才要開始，<br>人越多越嗨不是嗎？<br>這次感覺有可能全員集合吧？<br>現在應該大喝大鬧、嗨起來，<br>哪有閒工夫睡覺？？<br><br>欸，總之我們開始吧！<br>喔耶喔耶──！看這裡～！<br>大家都拿起杯子～！<br>那就──<br><br>「今晚要嗨通宵唷──！<br>耶──派對之夜～開始！！」<br>"},
{index="20025",text="啪！游泳池邊傳來暢快的聲響。<br>生野狄杜斯站在白板前面，<br>指導兩位賽馬娘。<br><br>「聽好了，渦輪。不做熱身運動就下水，<br>實在是荒謬至極。<br>即使是體能優異的賽馬娘，<br>若輕忽大意，<br>還是有可能危害性命，知道嗎？<br>首先要確實伸展肌肉──」<br><br>「嗚嗚，我知道了。妳講好久～」<br><br>「唐懷瑟，妳也是。<br>別光在旁邊看，趕快暖身！<br>做屈伸運動和前屈伸展時，要確實動到肌肉，<br>依照這上面寫的順序去做。<br>若可以好好落實，應該能比平常<br>有更好的效果──」<br><br>「是、是的～！」<br><br>連在旁邊觀看兩人互動的<br>待兼唐懷瑟，也受到了<br>生野狄杜斯熱心的教訓。<br><br>「請保護好自己的腳，<br>絕不要因為太亂來使腳受傷。」<br><br>即使是忍不住想抱怨<br>「別管我們了啦～」的雙渦輪，<br>也還是乖乖地聽了她這句話。<br>……這不是單純想訓人而已。<br>她的確是為同伴著想，所以才──<br><br>「──接著回到一開始再來一遍。」<br><br>……就這樣重複多次後，<br>熱身運動的重要性也<br>徹底記在腦海了吧。<br><br>「嘿──！！」的喊聲，<br>這次響徹了整個游泳池，<br>後來，生野狄杜斯的伸展指導<br>仍持續了很長一段時間。"},
{index="20026",text="「呀，好痛。<br>就說不能抓尾巴和耳朵！」<br><br>「哈哈，素質的家人真多～<br>很歡樂的樣子耶～」<br><br>這點還比不上妳吧。<br>話說，別在一旁悠哉看著，<br>希望能來幫幫我。<br>……不，我真的很喜歡小孩喔。<br>他們很可愛，天真又不帶惡意。<br>只不過──<br><br>「姐姐──妳的耳朵跟尾巴<br>好可愛喔！」<br><br>「對啊！非常可愛！！」<br><br>「唔……」<br><br>太過無邪也不太好。<br>竟然被小孩子說可愛，<br>我一點都不高興……啊啊，真是的，<br>希望他們不要用閃閃發亮的眼神問<br>「可以摸摸看嗎？」並徵求我的同意。<br><br>「就、就算露出那種表情，<br>不行就是不行……」<br><br>先用溫柔的語句拒絕看看。<br>……好好好，我知道。<br>這樣一定只是無謂的抵抗。<br>到最後還是會因為那些天真的笑容<br>而妥協吧。唉。"},
{index="20027",text="不知道天空是否喜歡那份花的禮物？<br>雖然花有很多種，但我聽說<br>雛菊最喜歡太陽……<br><br>總是等著太陽才開花……<br>花居然喜歡曬太陽，<br>真的跟天空好像。<br><br>而且，雛菊還有一個地方<br>很像天空──<br><br>就是雛菊的花語是「天真」<br>以及「真實」……<br><br>天空常又是午睡又是釣魚，總是快快樂樂的。<br>看起來如同隨風搖擺的雛菊，<br>那麼悠閒自在……<br><br>跟她聊過之後，讓我感到很輕鬆。<br>像是在告訴我可以不用勉強。<br><br>（要是天空喜歡雛菊就好了，<br>因為我也變得最喜歡雛菊了……）"},
{index="20028",text="沒想到你會想閱讀<br>《撒克遜賽馬娘英雄傳》……<br>不，我非常高興……<br><br>我想想……<br>如果是這間圖書室現有的藏書……<br><br>要不要試試這本新裝文庫版呢？<br>不僅註解詳細，<br>連小典故都記載得很齊全。<br><br>這本大開本也很推薦喔。<br>裡面有許多插畫，可以輕鬆在腦中想像<br>當時的生活與當地景緻……<br><br>啊，還有電影版小說……！<br>電影原創的橋段很刺激<br>五名賽馬娘的槍戰場景<br>也相當精彩。<br><br>不過，有機會還是希望妳能讀過原作！<br>可以在原文獨到的古樸穩重筆鋒下，<br>感受到真英雄才有的英勇……<br>（※以下省略）"},
{index="20029",text="「哦──呵呵呵！<br>來擬訂遠征全世界的計畫囉！<br>我的首要目標是──法國！<br>接著是美國！妳們呢！？」<br><br>「哦哦哦，全世界！神鷹我也想去跑！！<br>英國！杜拜！嚮往的巴黎！！！」<br><br>「不錯耶！好棒的熱情！<br>在通往溫莎城堡的長徑上並行練跑，<br>在凱旋門前與勁敵握手，<br>在杜拜的夜景中與夥伴們同樂。<br>如果有這樣的一週時光就好了！！！<br>那邊的女孩呢！？」<br><br>「我想在國內穩紮穩打地獲勝～」<br><br>「太棒了！不用刻意進軍世界也沒關係。<br>因為人們會為了一睹妳的風采，<br>從世界各地聚集到這個國家來！<br>沒錯，『世界』的中心就是妳！<br>嗯嗯～revolution！！！<br><br>真是美妙……大家各自<br>懷抱著precious的夢想。<br>放眼世界！接受世界的矚目！<br>如此一來我們便能成為寶石！！」"},
{index="20030",text="她總是很早起。<br>當其他賽馬娘還在睡夢中時，<br>她在打工送報紙。<br><br>打工結束後，她接著去上課與訓練。<br>充分練跑後，還會再去打工。<br>有時甚至會同時兼三份以上的差事。<br><br>每天都過得非常忙碌。<br>即使是賽馬娘應該也會支撐不了，<br>那她是如何撐過每一天的呢──<br><br>「好。補充營養後繼續努力！」<br><br>她已經準備好隨時起跑。<br><br>　　　～為努力不懈的你打造的能量棒～<br><br>自從這支廣告播出之後，<br>艾尼風神的粉絲們似乎購買了<br>大量的能量棒給她──"},
{index="20031",text="「閘門練習～？<br>練習在看到信號前，要等待～～？<br>……別小看我──！<br>這種小事對我來說很簡單啦！！」<br><br>…………<br>……………………<br><br>「唔嘎──！為什麼還沒有信號！？不打算給信號嗎！？<br>──唔～～既然這樣……」<br><br>（沙！沙！沙沙沙……！）<br><br>「看我挖洞衝出去──！」"},
{index="20032",text="──時間是現在的狂風暴雨之日。<br>一名身型嬌小的賽馬娘站在<br>滿是泥濘的賽道上。<br><br>「為什麼一臉鬱悶，<br>難道你認為我沒辦法跑嗎？」<br><br>──即使只是練習，<br>也沒有理由偷懶。<br><br>「少囉嗦笨蛋。<br>區區風雨就沒辦法好好跑步？<br>雙腳會因為泥濘道路而停下？」<br><br>──大家都說這世上已無江戶，<br>已無瀟灑可言。<br><br>「哈！格局太小！<br>實在太小了！」<br><br>──錯！<br>江戶風情還存在於此！<br><br>「逆著風才叫奔跑！<br>即便有泥濘，依舊是地面！」<br><br>──若要論江戶之子的瀟灑魂，<br>非這名賽馬娘莫屬！<br><br>「我是江戶孕育長大的稻荷一！<br>不論是暴風還是什麼，<br>總之向前奔跑就對了！」"},
{index="20033",text="「今天要介紹的商品，<br>是這個高壓清洗噴嘴！<br>能噴出強力水柱，即使不用力刷<br>也能將髒汙清洗乾淨！<br>別說是鞋子、就連車子或牆壁等的清潔<br>也都能輕鬆搞定！」<br><br>「哇喔～太神奇了──<br>不過這一定很貴吧～？」<br><br>「小青別擔心，<br>它的價格非常合理！<br>而、且！噴濺的距離也是Bueno！<br>即使是遠處的花壇也能澆到水！<br>妳看就像這樣──！」<br><br>（噴灑────）<br><br>「……啊。」<br><br>「……呵呵，神神……妳在玩水啊？」<br><br>「小草！？對對對對不起！<br>我不是故意的！！！！<br>只是不小心噴到剛好在花壇旁邊的小草！<br>妳說對吧！？小青──她不見了！？」<br><br>「神～神～？<br>……真是的。妳在清洗<br>訓練用的運動鞋嗎？」<br><br>「對對對、對啊！<br>因為它今天陪我一起努力，<br>我才想說要把它清乾淨！」<br><br>「對工具抱持敬意是件好事呢。<br>可以讓我跟妳一起洗嗎？」<br><br>「當、當然可以！呼……」<br><br>「話說，我會在競賽上<br>討回妳朝我潑水的仇喔。」<br><br>「這個……求之不得！<br>我可不會輸喔，小草！！」"},
{index="20034",text="那名賽馬娘輕輕擦拭額頭上的汗水。<br>從她凜然的側臉，可以看出其高貴的精神與<br>即使面臨逆境也不退縮的意志。<br><br>「即使如此，我還是要跑。」<br><br>……她的腳有如玻璃般脆弱，<br>讓不少人擔心她是否能奔馳。<br><br>「即使如此，我也不會放棄。」<br><br>她的雙眼凝視著兩道身影。<br>一個是在武術中獲得光明者，<br>一個是對淡紅抱持憧憬者。<br>她仰慕地望著遠方的背影們。<br><br>「即使如此，我也要競爭。<br>現在就想抬頭挺胸地追上去！」<br><br>即使如此……她說著說著站了起來，<br>只要還有一口氣……不，只要這條路還未到盡頭。"},
{index="20035",text="啊──不行不行，我要休息～<br><br>真的不敢相信耶。<br>怎麼會在並行練跑時出全力啊？<br>誰會在坡道超前啊？<br><br>她輕輕鬆鬆就超過我啦，<br>超好笑～太猛了吧～<br><br>……話說指甲還沒乾～<br>……呼啊～～欸啊～～～～～～！<br><br>………………沒想到會慘輸，我好遜。<br><br>──好，指甲乾了☆<br>總之先來跑坡道吧！"},
{index="20036",text="「這樣啊，不小心跌倒<br>把戴在手臂上的護肘弄壞了。<br>這的確會受到很大打擊呢。」<br><br>「是的……嗚嗚……<br>那是福來給我的<br>本月幸運道具，<br>結果碎成這樣……」<br><br>「啊啊，流鼻水了，拿紙巾擦擦。」<br><br>「不好意思…………（擤）……<br><br>上面有花紋還有一個緞帶，<br>我這一個月不論念書還是散步都戴著。<br>但我卻……嗚嗚嗚……我沒資格當她的朋友。」<br><br>「別這麼說，妳這一個月都這麼珍惜，<br>就是重視朋友的證明，<br>可說是抱抱＆和平啊！<br><br>話說怒濤不是沒有受傷嗎？<br>都是因為有這個護肘的關係呢！<br>幸運道具是有發揮效用的～！」<br><br>「這、這個嘛……<br>是、是這樣嗎……？」<br><br>「絕對是的。對吧，福來！？」<br><br>「說得沒錯！那個幸運道具<br>為了心地善良的怒濤，<br>用自己的身體擋下災禍了！」<br><br>「唔咦咦咦咦！？福、福來！<br>妳、妳是什麼時候來的～！？」<br><br>「雖然是我主動丟問題給妳，<br>但我真的也想問問呢。<br>怒濤那段動人心弦的故事都被妳聽到了嗎？」<br><br>「是啊，沒錯！彷彿白興大人的神諭降臨般，<br>我全都聽到了！<br>怒濤，妳真的很遲鈍呢～<br>所以來緊急占卜一下吧！<br><br>納納可羅比亞歐奇、納納可羅比亞歐奇。<br><br>……出現啦！怒濤下個月的<br>幸運道具就是甜食！」<br><br>「啊哈哈！那只能大家一起<br>去吃甜點了呢！等一下就出發如何？」<br><br>「咦……？<br>可是甜食是下個月的幸運道具……」<br><br>「沒關係啦！就先預支下個月的運氣啊！<br>雖然我也不知道能不能這樣！」<br><br>「嗚嗚嗚……<br>竟然對我這麼好……」<br><br>「來～擤個鼻子，我們就出發吧！」"},
{index="20037",text="「金黃色的湯汁，漂亮整齊的麵條，<br>燉到一夾就化的叉燒。」<br><br>「肚子餓時，就會想到拉麵。<br>不論是專業廚師做的正統拉麵、<br>還是街頭食堂裡廣受喜愛的味道甚至杯麵，<br>都是曾帶給我感動的美味食物！」<br><br>「啊！這些讓我遇見至高美味的人們，<br>相當適合『拉麵騎士』的勳章吧？」<br><br>「接著為了能做出更美味的拉麵，<br>再建設最棒的設備，希望能讓專業廚師<br>盡情發揮所長！<br>就取名為『拉麵王國』！」<br><br>「……什麼？<br>那樣反而會造成別人的困擾？」"},
{index="20038",text="她端正地坐在眾人高聲尖叫的中央。<br>看起來既覺得麻煩，又感到滿足，<br>若有似無的嘲諷笑容。<br><br>讓人猶豫是否該靠近，<br>但即使不想還是會進入視線裡……<br><br>真的有人有辦法<br>不去在意她那樣的賽馬娘嗎？<br><br>人群移動擋住了她的身影。<br>於是我伸長脖子一看，卻與她四目相接──<br><br>「為什麼擺出一臉不滿足的表情？<br>你也想被疼愛嗎？」"},
{index="20039",text="──妳曾這樣說過。<br>「為了不再讓妳翹掉打掃值日生的工作，<br>所以要監視妳，這也是為了其他同學。」<br><br>而正如妳所說的，就算我只是想稍微休息一下，<br>也會被妳碎碎唸個不停。<br>我真的只是摸一下手機耶！<br>這沒關係吧？<br><br>……喂，等等。妳什麼時候拿掃把過來的？<br>還說「趕緊掃。」<br>妳是我老媽嗎？<br><br>明明妳自己也有事情要做。<br>一直管我的話，車站前的泡芙<br>就要賣完囉？<br>妳不是一直很期待今天嗎？<br><br>……啊～夠了，都是妳害的。<br>所以叫妳快點掃完！"},
{index="20040",text="「呼──流了一身汗真舒服──！<br>肌肉都覺得很高興！」<br><br>訓練告一段落的<br>目白雷恩為補充流失的水分，<br>將運動飲料灌入體內。<br><br>「訓練員也進來陰影處遮陽比較好喔。<br>光是在大太陽底下就會消耗體力。<br>你不介意的話請喝這個──」<br><br>此時目白雷恩卻突然縮回了<br>遞出運動飲料的手。<br><br>「那、那個……啊哈哈！<br>不好意思把喝過的拿給你！<br>我去更衣室拿新的過來！」<br><br>臉頰微微泛紅的目白雷恩，<br>一邊如此說著一邊用<br>跟訓練時一樣快的速度<br>瀟灑地飛奔而去。"},
{index="20041",text="「……好厲害……」<br>獨自一人在教室裡<br>邊確認競賽影片，<br>邊不由自主地低聲讚嘆。影片中的表現威風凜凜，<br>壓倒性的實力與其展現的自信不相上下──<br><br>「……即使這樣我也一定要成為一等星……」<br><br>──正當她下定決心時，<br>教室的門卻被冒然地打開。<br><br>「喔喔！美麗的愛慕織姬！<br>沒想到我們會在這裡相遇！<br>我跟妳果然是命中注定……<br>有著斬也斬不斷的緣分啊！」<br><br>在看清楚打破寂靜的聲音主人的瞬間，<br>她關閉了筆電。<br><br>「我要為讓妳久等待而致歉！我的勁敵！<br>來吧！願意跟我合奏一首<br>名為火熱友情的交響曲嗎！」<br><br>「……根本就沒有在等妳，<br>我也不是妳的勁敵。」<br><br>她一邊提出異議一邊收拾筆電，<br>但她有辦法順利脫身嗎──<br><br>「妳的表情很陰沉呢！<br>讓我們一起來解決妳的難題吧！<br>唉～這是多麼令人感動的情境！<br>來，把妳的煩惱說來聽聽！」<br><br>「…………」<br><br>絕對不能讓她知道<br>自己正在看誰的競賽，<br>否則事情一定會變得更加麻煩。"},
{index="20042",text="「你知道『早安！』<br>這句話當中隱藏的涵意嗎？」<br><br>「早、安……早……早……<br>發現了嗎！？早晨的問候語當中<br>居然隱含著『早點』抵達終點的『早』之意！！」<br><br>「也就是說！『早安』是用<br>代表速度的詞彙進行問候！」<br><br>「也就是說只要在早晨持續打招呼的話，<br>驀進的速度也會增加對吧！<br>這就是驀進革命！！」<br><br>「所以要開始囉！<br>……早────安！！」"},
{index="20043",text="自從來特雷森學園後，<br>這已經是第幾封了呢？<br>給北海道的媽媽們的信──<br><br>雖然用電話傳達更快，<br>但像這樣寫成文章後，<br>我覺得自己真正的心情……<br>不論是愉快的事還是煩惱的事<br>都變得非常明確。<br><br>所以想必也能<br>明確地傳達給媽媽們吧。<br>我今天的心情也會確實地傳達到嗎？<br><br>「媽媽，妳過得好嗎？」"},
{index="20044",text="──會經常去這間店嗎？<br><br>真機伶：是啊！從我剛搬進宿舍，<br>　　　　打算要準備裝飾房間的小東西以來，<br>　　　　就經常會去♪<br><br>──是間充滿回憶的店呢！<br><br>真機伶：畢竟它的裝潢都沒有變，<br>　　　　會讓人不禁想起當時的事情。<br>　　　　啊……！這個馬克杯！<br>　　　　這也是從那個時候開始，就持續<br>　　　　賣到現在的相同款式喔♪<br>　　　　雖然真機伶買的那個已經褪色了，<br>　　　　不過還是覺得很高興呢～<br><br>──怎麼說？<br><br>真機伶：因為那是與訓練員開作戰會議時，<br>　　　　大展身手的杯子！<br>　　　　我在會議時，曾遇到<br>　　　　覺得「該怎麼辦才好？」的時候。<br>　　　　可是可是！就在這時候，<br>　　　　我稍微去休息一下……<br>　　　　腦中就突然「叮咚」地浮現出解決辦法！<br>　　　　所以……<br>　　　　想必是杯子褪色的部分，<br>　　　　讓我度過了難關。<br>　　　　那應該是用盡全力的證明吧。<br><br>──也就是日積月累而成的顏色，對吧？<br><br>真機伶：對！我今後也會繼續使用它，<br>　　　　想把它變成更～可愛的顏色♪<br><br>◆Profile：真機伶<br>隸屬特雷森學園的賽馬娘。<br>受年輕人歡迎的引領潮流者。<br>稱讚她的話語「可愛的真機伶」<br>經常進入趨勢話題的排名。<br>最近熱衷的事情是訓練。<br><br>Umastagram：＠Curren"},
{index="20045",text="哼唔！哼唔唔～～！？<br>鴿、鴿子……真的……<br>有在做……這種動作嗎～！？<br><br>唔呀～好、好痛……<br>我、我、我不行……了…………<br><br>──才～～怪……咧～！<br><br>我要把最耀眼的光芒！<br>「謝謝」和<br>「一起奔向賽馬娘偶像之道吧」的<br>這些心情──<br><br>都傳達給所有粉絲，<br>和支持我的人！<br><br>因為、飛飛是、<br>頂尖、賽馬娘偶像……啊啊～～～～！！<br><br>（閃到腰）<br><br>呃啊……"},
{index="20046",text="被風吹起，掉落在草地上的重要帽子。<br>看見那個景象後想起的，<br>是祖母傳授給我的魔法──<br><br>「哎呀哎呀……？<br>我可愛的Sweepy<br>怎麼在哭呢？」<br><br>「帽子髒了？呵呵呵……<br>這樣不需要哭啊，<br>可愛的Sweepy。<br>……妳問為什麼？因為<br>這代表妳向偉大的魔女更邁進一步啦！」<br><br>「魔女的帽子<br>跟著魔女一起奔跑而變髒、脫線，<br>才會逐漸累積魔法在裡面喔。」<br><br>「過來吧。<br>為了不要讓累積的魔力被水沖淡，<br>就教妳只清除髒汙的密藏魔法──」<br><br>「……對吧，祖母！<br>現在正是祖母教我的<br>『淨化魔法』派上用場的時候！」<br><br>「好～既然決定了，<br>就必須來準備魔法道具！<br>我記得要……清水和肥皂和──」"},
{index="20047",text="──這裡是平常的電子遊樂場，<br>但現在卻宛如演唱會舞台般熱鬧。<br><br>「嘿嘿～我要就這樣刷新最佳成績囉～！<br>大家更嗨一點──！」<br><br>正在機台前跳舞的她，<br>聲音既開朗又響亮，<br>尾巴也隨著輕快的舞步搖擺著。<br>然後她用綻放開來的笑容說道──<br><br>「──欸！你也來為我加油！」<br><br>──我怦然心動了一下。<br>立刻就察覺那個眨眼，<br>和說話的對象是自己。<br><br>「最後來個轉圈～擺出勝利姿勢！<br>耶──！最佳成績～！」<br><br>上面顯示出神一般境界的高分，<br>圍觀群眾歡聲叫好，連我也不由得拍起了手。<br><br>「謝謝大家為我加油～！<br>……啊，已經這麼晚了。<br>那麼下次在競賽會場上見吧！」<br><br>「帝皇大人我會表現得比今天<br>還～要更熱血沸騰！<br>──先這樣，掰掰啦──！」<br><br>她這樣說完就飛奔離去。<br>即使已經看不見她的身影，<br>但那笑容已深深地烙印在我的眼中。<br><br>……我想，大概從這時候開始，<br>我就已經成為小小「帝皇」的粉絲了──"},
{index="20048",text="「請問這些……全部都會吃掉嗎？」<br>小栗帽對忍不住出聲詢問的攝影師<br>認真地點點頭。不過筆者注意到<br>她的尾巴正不停地擺動著。<br><br>──是因為像小栗小姐這種級別的選手，<br>訓練的強度也相當高，<br>所以為了要恢復體力……是嗎？<br><br>小栗帽（以下簡稱小栗）：不。<br>我只是純粹想吃很多而已。<br>我很喜歡，<br>喜歡……吃飯這件事情……<br>喜歡任何能填飽肚子的東西。<br><br>說完這些話的小栗帽，<br>眼睛如同彗星般閃耀。<br><br>小栗：可以吃了嗎？<br>不介意的話，你們也一起吃吧。<br>那我就……開動了！<br><br>她的笑容就像盛開的花朵般，<br>想必是打從心底喜歡吃飯這件事……<br>我們用相機捕捉到酷炫「偶像賽馬娘」<br>令人意外的真實樣貌。<br><br>（摘錄自《閃耀月刊》<br>【首頁特輯！小栗帽──<br>「偶像的真實樣貌」】）"},
{index="20049",text="……不想被認為空有外表。<br>想證明自己有經過磨練的<br>不只是外貌。<br><br>「啊，又不小心燒焦了。」<br><br>……想變得更強。<br>變得自己的事情至少能自己負責。<br>變得不只有外層鍍金，<br>而是連內在也閃閃發亮充滿自信。<br><br>「……嗯。再試一次！」"},
{index="20050",text="「呼啊～～啊。<br>是菱亞做的飯糰。<br>這個用了很棒的鮭魚很好吃呢～」<br><br>「……我說妳啊。」<br><br>「啊，別擔心別擔心～。<br>這是菱亞事先幫我們做好的。<br>剛好也有帝王妳的份……」<br><br>「～～唔！我不是指這件事啦！<br>不是說好要去晨間練跑嗎！？<br>但妳卻連衣服都沒換，<br>還像這樣……站著喝水──！」<br><br>「哦哦～妳很有精神耶。<br>嗯嗯嗯～<br>我好像清醒多了～<br>那麼，我這就去換衣服囉～」<br><br>「…………菱亞做好的飯糰，<br>如果剩下來的話會被丟掉吧～」<br><br>（噠噠噠……）<br><br>「………………<br>……剩下來，應該不太好吧。」<br><br>…………（嚼嚼）。<br><br>「……唔！！……好吃。<br>…………這麼說來<br>最近這陣子，總是只想著競賽的事……<br>連好好品嚐食物的時間<br>都沒能擠出來呢……」<br><br>「啊，水藍色容器裡面<br>裝的是我老家寄來的醃漬小黃瓜。<br>那個也可以自行取用～」<br><br>「嗯唔！？……真是的！！<br>我知道了啦，妳快點去把衣服換好！！」"},
{index="20051",text="關於二度改寫紀錄的壯舉<br>她如此說道：<br><br>「我之所以能夠奔跑都是託大家的福。<br>這個成果若有稍微回報一些恩情的話，<br>我會感到很高興。」<br><br>想報答過去周遭的人們帶給自己的奇蹟，<br>因此這次要由自己喚起奇蹟了。<br><br>突破重圍的她將身後選手遠遠甩開。<br>──只剩影子緊追不捨。<br>那個瞬間，她懷抱的感恩與執著<br>在蒼藍雙眸中燃起了烈焰。<br><br>而將一切燃燒殆盡後她確實緊緊抓住了。<br>抓住那第三次的奇蹟──<br><br>（攝影：編集部／記者：乙名史 悅子）"},
{index="20052",text="「……嗯。<br>這個月的回顧，差不多就這樣吧。<br>沒有在訓練中昏倒，<br>也觀看了小特她們的出道戰……<br>…………嗯。<br>這一個月讓我更有動力想好好努力了。」<br><br>「唔……不能再這樣下去了！<br>趕緊來確認下個月的訓練內容……<br>不，應該先確認飲食內容嗎？<br>對、對了。貼布也必須買來補充──」<br><br>「……呃，咦？熱呼呼的茶？<br>什麼時候放在這……」<br><br>「唔呵呵。希望合妳口味～」<br><br>「光明！？早安！<br>抱歉，我完全沒發現……！<br>我會趁熱享用──好燙！」<br><br>「哎呀，不行喔～小鶴，<br>妳要先『呼～呼～』一下再喝。<br>來，跟我一起……呼～呼～」<br><br>「好、好的！呼～呼～～<br>…………（喝下）…………呼啊～～」<br><br>「呵呵呵，旁邊的茶點也請務必品嚐～<br>那麼，我先去盥洗室<br>整理儀容囉～」<br><br>「啊，好的！謝謝妳！<br>……（吃下）……呵呵，好甜喔。」<br><br>「好了，繼續繼續！<br>記得剛才在煩惱接下來要做的事。<br>……嗯，首先要掌握現況。<br>然後決定優先順序。<br>……耶嘿嘿，好神奇喔。<br>剛才腦子裡還那麼混亂的說！」<br><br>「──好！我要加油囉！」"},
{index="20053",text="「成田路……妳的文件掉了。<br>這是下一堂世界史要用的資料吧？<br>……我幫妳拿，分一半給我吧。」<br><br>「哇，謝謝！<br>不過，沒問題的！並不重。<br>況且這也是班長的工作！」<br><br>「話說織姬！<br>下一堂課妳準備好了嗎？<br>這次要移動到別處上課，<br>最好早點做好準備喔！」<br><br>「妳也太濫好人了……真是的。<br>給我，我來拿吧。」<br><br>「織姬……！」<br><br>「就是說啊，成田──路──！<br>也讓我和大進幫忙搬嘛──！！」<br><br>「別在我耳邊大吼大叫啦……！<br>……總之，就是這麼回事<br>趕快把事情搞定吧，成田路。」<br><br>「獎券……！還有大進！<br>那麼，恭敬不如從命，<br>模造紙就麻煩妳們兩位了！<br>地球儀拜託織姬了！」<br><br>成田路俐落地將搬運的東西分配好，<br>但是那裝滿文件的沉重紙箱，<br>她依然堅持自己搬……"},
{index="20054",text="「啊啊，太陽看見我的身影<br>竟然讓臉因嬌羞而變得如此通紅！」<br><br>「呵呵，這也沒辦法。<br>因為我正是全宇宙<br>最美的存在啊！」<br><br>「照亮世界每個角落的太陽啊，<br>為自己感到驕傲吧。<br>因你擁有能夠與我合影的榮譽！」<br><br>「來吧，怒濤！開始吧！<br>為我這終將登上世紀末霸王之座，<br>偉大的好歌劇進行攝影！」<br><br>「好、好的……！」<br><br>剛出道不久的好歌劇。<br>為了替她拍攝宣傳照而被選上的人<br>正是名將怒濤。<br><br>「主題當然是『世紀末霸王』！<br>如何，這件威風凜凜的披風！<br>充滿了霸王的莊嚴魅力吧！」<br><br>「看、看起來比平常還要耀眼……！<br>過去在聖蹄祭使用過的衣服<br>竟然這麼輕鬆就成功借到了……<br>真不愧是好歌劇～」<br><br>「那就開始拍囉～？<br>呃嗯，該從哪個角度拍才……<br>……咦，哇、哇哇哇哇！？」<br><br>名將怒濤不小心絆倒，<br>相機順勢被拋上空中。<br>而她則慌慌張張地<br>設法飛撲接住──<br><br>「唔噗……啊哇哇，對、對不起～！<br>相機差一點就要<br>被我給弄壞了～～！」<br><br>「不過，總算是死守住、了……<br>噫～～～～！！<br>變變變變成連拍了～～～！？<br>而且連續拍了非常多張～～～！」<br><br>「喔……？──做得太好了，怒濤！」<br><br>「拍到了最棒的一張照片不是嗎！<br>──妳看，如此燦然佇立的我！<br>自開天闢地以來的歷史歲月中<br>想必也未曾有過如此珍貴的至寶吧！」<br><br>「我要向妳致上衷心的感謝，怒濤！<br>竟能截取到我最尊貴美麗的瞬間，<br>不愧是我的宿敵！哈──哈哈哈！」<br><br>「好、好歌劇……！<br>啊哇……真、真不敢當……<br>但是我也很高興……！！」"},
{index="20055",text="手機的通知音效響起。<br><br>通訊軟體──LANE上，<br>顯示著最新的訊息。<br>「奧斯頓真弓<br>傳送了檔案」<br><br>仔細一看傳來的<br>似乎是個錄音檔。<br>至於其他訊息……<br>等了又等卻沒有傳來。<br>──於是我按下了播放鍵。<br><br>「電池，沒有異常。<br>麥克風功能也沒問題。一切順利呢。」<br><br>「那麼要開始了，<br>奧斯頓真弓廣播電台～<br>開玩笑的，平常不會這麼說。」<br><br>「另外今天會小心謹慎地，<br>待在塔屋上仰望天空。<br>還會讓兩隻腳晃來晃去。<br>……因為我一點都不害怕。」<br><br>「──昨天嘩啦嘩啦地下了一場大雨，<br>地面積了好多小水漥。多虧如此<br>小真才能待在天空與天空之間。<br>上面大大的天空，與下面小小的天空。」<br><br>「我現在，正在天空與天空之間。」<br><br><br>我停止播放錄音檔，<br>離開椅子站起身來。<br>腦中浮現的地點，<br>是學園內可以清楚看見天空的場所。<br><br>如果我用盡全力爬上樓梯抵達那裡，<br>她那對圓圓的雙眼是否會睜得更圓，<br>帶著些許困擾的表情露出笑容呢。<br><br>「……是。小真在這裡。」"},
{index="20056",text="我喜歡光彩奪目的東西，<br>像是最強的稱號，或是最高的榮耀。<br>大家都是這樣吧？<br><br>……不過，那傢伙不一樣。<br>那傢伙本身就比任何人都要眩目，<br>簡直就像真的會發光一樣，看起來有夠刺眼。<br><br>哈哈，好極了。<br>管你是光還是什麼的，都不重要。<br>我都會一口氣超越你們。<br><br>要不然我就無法奪下勝利啦？<br>畢竟我的目標，<br>就是那種最強【境界】啊。<br><br>「喂，速子。賞個臉吧。」"},
{index="20057",text="嗯……新的吹風機還不錯。<br>不會讓頭髮毛躁打結，有種自然風乾的感覺。<br>不愧是氣槽前輩推薦的產品……<br>之後有機會的話，真想告訴她用過的感想啊。<br>……要不要再附上百花香當作謝禮呢？<br><br>如果我努力打理一下頭髮的話……<br>說不定也可以弄出<br>像光明那樣蓬鬆柔軟的髮型？<br><br>我從以前就覺得那種髮型很可愛呢。<br>摸起來的觸感也很像棉花糖……<br>雷恩之前也說，<br>回過神來就讓她開始摸起來了。<br>……呃，我不是想被人摸頭髮啦！<br>那樣我倒是會有點害羞。<br><br>「唉，我想還是不太可能吧。<br>畢竟我跟光明的髮質完全不一樣──」<br><br>「Hey～多伯！那台吹風機<br>是妳的New item嗎？」<br><br>「哇，大樹！是、是啊。<br>這是氣槽前輩推薦我<br>用用看的產品……」<br><br>「Oh, so good！<br>氣槽的頭髮又直又滑順～<br>多伯也是又直又滑順～<br>也就是說，真是Best Match！」<br><br>「等妳待會吹乾了之後，<br>也請讓我盡情地滑～順一下。<br>我很期待哦！！」<br><br>「咦……真是的，什麼跟什麼嘛。<br>……稍微讓妳摸一下下是可以啦。」<br><br>結果大樹真的就一～直笑瞇瞇地等著我，<br>一聽到我說好，<br>就立刻飛奔到我身後，接著將手伸了過來。<br>然而不同於那股氣勢，<br>她輕柔地從我的髮根<br>一路撫摸到髮梢的那雙手，<br>遠比我想像中的還要細膩許多。<br><br>等我有辦法開口告訴她我覺得很害羞，<br>請她差不多該停手了的時候，<br>已經過了一小段時間。"},
{index="20058",text="「哈……啾……！」<br><br>「抱歉，我昨天開始就有點小感冒……<br>因此本來是沒有打算在公共場所<br>表演如此一個豪邁的噴嚏──」<br><br>「──把窗戶打開吧。<br>我想少許的塵埃也是造成噴嚏的原因。」<br><br>將窗戶打開後，帶著一股暖意的風<br>將乾燥的空氣趕了出去。<br>她深吸了一口氣，再慢慢地吐了出來。<br><br>「如果換作是平常，我並不會打出<br>那種噴嚏來……呵呵，真是傷腦筋。<br>正因關係親近，我才該讓自己上緊發條才是呢。」<br><br>她別開視線，將目光投向窗外。<br>一抹橘紅色的光芒，<br>讓她的臉龐染上了色彩。"},
{index="20059",text="──舉例來說，在剛入學的時候，<br>一說起愛麗速子同學，<br>那可謂是眾所矚目的焦點。<br>由於一個不小心就跟她同班了，<br>因此投以她的那些甚至可稱為無禮的視線，<br>讓我記得十分清楚。<br><br>剛開始的主要原因，莫過於她良好的血統。<br>能在這種學園就讀，<br>那種所謂家世優良的大小姐自然也少不了，<br>但她不僅祖母是奧克斯賽馬娘， <br>母親甚至還是不敗的櫻花賞賽馬娘，<br>光是如此就足以使她備受矚目了。<br><br>……接著，以她為中心蜂擁而至的向量，<br>很快就反轉了過來。<br>奇特的言行、詭異的實驗活動，<br>以及即使如此仍能有所發揮的耀眼才能……<br>嗯，這樣列了出來，<br>應該也足夠構成大家避之唯恐不及的理由了。<br><br>「呵呵呵……<br>出現了一篇挺愉快的論文不是嗎？<br>關於賽馬娘的肌肉收縮與能量的新學說……<br>這個點子或許能活用於下一次的實驗！<br>……隨便說說的就是了！」<br><br>在嘈雜的學生餐廳一隅，<br>今天又以她為中心出現了一圈空的座位。<br>與其說是一圈，不如說是結界？<br>看著那堆數量驚人的方糖在桌上高高疊起，<br>我心想她或許是在設置屏障什麼的吧。<br>──一道像我這種再平凡不過的學生，<br>絕對無法突破的屏障。<br><br>「速子。<br>……妳還是不要拿食物來玩比較好。」<br><br>「哎呀，咖啡！妳這句話難道不是<br>在看見食物不被當成食物時才會說的嗎？<br>我接下來可是打算把這裡準備的所有──沒錯，<br>所有方糖都放進紅茶裡！<br>也就是說我會全部吃掉，所以完全沒有──」<br><br>「就是有問題。」<br><br>而時至今日，這道屏障──<br>似乎已經有不少人能夠順利突破了。<br><br>咖啡同學在速子同學滿是空座位的對面，<br>輕輕地嘆息了一聲後便坐了下來。<br>而就在這時，我看見一顆堆疊在上面的方糖，<br>應聲掉了下來。"},
{index="20060",text="「一、二！三～四！<br>五～六、七、八！」<br><br>「最後深呼吸……<br>這樣暖身運動就做好了呢～！」<br><br>「來，讓我們盡情大游特游一番！<br>然後讓肚子徹底餓起來吧！<br>我今天做的點心，<br>成品也是非常地buono哦～！」<br><br>「嗯？你不太會游泳嗎？<br>那你抓著我的手吧。<br>我來教你怎麼游泳！」<br><br>「像游泳圈一樣圓～圓的甜甜圈<br>在等著你哦。<br>我們一起加油吧！」<br><br>「好～那我們就噗通～一聲，<br>朝泳池裡跳進……」<br><br>「啊，等一下～！<br>那個不是泳圈哦！<br>是我烤好的特大甜甜圈啦～～！」"},
{index="20061",text="～阿船炒麵緣起～<br><br>那是我仍未裹上糯米粉，<br>還是隻俏皮棕色的<br>阿船的時候──<br><br>『有沒有人……<br>有沒有人要買這個醬汁啊……<br>這是我們家代代傳下來的醬汁──<br>啊啊，沒有人願意買……』<br><br>接著，就在已經快要放棄的我，<br>開始在海邊堆起沙堡的時候──<br><br>海面突然裂成兩半，<br>一位有著驚為天人的美貌、<br>一頭秀髮宛如珍珠般的賽馬娘觀音，<br>出現在我的眼前，<br>並且對我如此說道──<br><br>『阿船啊，是炒麵──<br>妳要用那個醬汁做炒麵──<br>這樣妳跟醬汁<br>就都能成為萬人迷了──<br>然後再順便去參加幾場競賽怎麼樣？』<br><br>經過這件事情之後，<br>有著阿船標章的<br>宇宙無敵好吃炒麵<br>就這樣誕生了。<br>說完了。<br><br>──而這邊這幅掛軸上<br>所描繪的就是如此美妙的傳說。<br>咦？你說這位賽馬娘觀音<br>跟阿船長得一模模一樣樣？<br>……真是的，你搭訕的手法太老套囉☆"},
{index="20062",text="今天萬里無雲，超讚的！<br>這麼好的天氣，<br>不去兜風怎麼給小達一個「蕉」代呢？<br><br>來來來！快坐上副駕駛座！<br>小達說今天要帶我們<br>去它珍藏的漂亮景點哦。<br><br>小達每次都會帶我到<br>很漂亮的地方去玩，<br>讓我的心情變得超讚！<br><br>哎呀，可不能忘記要把<br>安全帶綁好唷♪<br><br>用跟小達同樣的速度所感受到的風，<br>可說是這世界上最棒的體驗了！<br><br>不管是工作還是休息，<br>都要油門全開、盡情奔馳，才會有最棒的享受哦！"},
{index="20063",text="（淅瀝嘩啦……）<br><br>……下雨了……<br>我還想再繼續跑的說……<br>不知道這場雨會下多久。<br><br>這麼說起來，之前跟小特一起練習<br>耐力跑的時候，也是突然就下起了雨……<br><br>那個時候我們好像一起在樹下躲雨，<br>看著雲朵玩起了聯想遊戲吧。<br><br>當時小特突然一下說什麼饅頭，<br>一下又說飯糰，<br>剛開始還聽不懂，結果是在說雲的形狀。<br><br>後來還有胡蘿蔔蛋糕和漢堡什麼的。<br>……她真的很喜歡吃呢。<br><br>……那朵雲看起來<br>很像訓練用的運動鞋。<br>那邊那朵則是很像蹄鐵的形狀呢。<br><br>那朵雲……是優勝錦旗的形狀。<br>啊……烏雲逐漸散開了。<br><br>太好了，好像只是場陣雨。<br><br>哎呀？那邊那朵雲……<br>看起來很像胡蘿蔔漢堡排？<br>呵呵，不知道小特她<br>有沒有注意到呢……？"},
{index="20064",text="嗯♪天氣非常好♪<br>陽氣如此飽滿的今天，<br>會是多麼美妙的一天呢？<br><br>一日之計，最重要的果然還是在於「顏色」！<br>為了度過美好的一天，<br>必須由自己確實掌控好運氣才行呢！<br><br>今天要跟哪一條手帕一起度過呢？<br>帶著掌管成長的綠色手帕，<br>在訓練時全力以赴……<br><br>不對，更重要的是，<br>要小心不要過度堅持囤積疲勞，<br>所以要選能夠帶來平靜的檸檬黃……<br><br>啊，不過訓練的時候<br>要是受傷了就得不償失了吧。<br>這樣的話，應該帶可以驅邪避凶的紫色……？<br><br>不對不對，<br>應該要想辦法找到相生的伙伴，<br>彼此一起訓練才對……！<br>所以要選能夠吸引新的開始的紅色！<br><br>花紋的款式就挑跟人際關係有關的花朵刺繡！<br>嗯！完美♪<br>這樣應該就能引來最棒的氣才對！<br><br>「歷奇？你還在選手帕嗎！？<br>再不出門就要遲到了！」<br><br>「妳之前也是說什麼襪子顏色怎樣怎樣的，<br>害我們差點就遲到了吧！」<br><br>「呃，咦咦！？已經這麼晚了！<br>謝謝妳，樽前！」<br>Rickey☆Lucky☆<br>朝向最棒的一天跑起來～！"},
{index="20065",text="美麗的藍天也好，過於炎熱的陽光也罷，<br>甚或是迎面而來的舒適徐風，<br>以及這杯啜飲而下的暖茶，<br>我多希望能將這一切烙印在腦海裡。<br><br>但是肯定會隨著時間逐漸淡忘。<br>哪怕沒有褪去多少顏色，<br>也會埋沒在其他更鮮明的記憶下，<br>變得再也無法映入眼簾吧。<br>所以就至少記住一個畫面──<br>記住她的這抹笑靨吧。<br><br>雖然在我們奮力奔跑過的日子中，<br>這僅僅只是一段平凡無奇的片刻時光。<br>但就連這樣的時光她也確實在我們身旁，<br>象徵著這段記憶的證明……<br>只要往後能夠回憶起這抹笑靨，<br>就算其他的景色全都消失不見，<br>還是會心想，<br>能夠喝到與今天一樣好喝的這口茶。"},
{index="20066",text="★天才Sweepy的魔法筆記9★<br><br>【透長石．斜長石．月長石】<br>這是能喚醒體內幹勁的咒語。<br>這道魔法借助了<br>寄宿在月長石這些<br>美麗礦石中的魔力，<br>能讓心情煥然一新。<br><br>＜紀錄＞<br>第●次　△月×日<br>遇見因為沒有順利幫助人<br>而使得心情陷入低潮的北部，<br>故為其施加咒語。<br><br>實驗對象的感想<br>「內心真的溫暖起來了！<br>變革，謝謝妳！」<br><br>結果：大成功！<br><br>★天才Sweepy的魔法筆記19★<br><br>【萬靈糖果】<br>透過祖母的祕傳方法精煉而成的魔法糖果。<br>舔一口就能產生活力。<br><br>＜紀錄＞<br>第●次　□月○日<br>訓練過後，我把透過祖母傳授的方法<br>所精煉而成的一顆那個，<br>給了一路背著我跑回宿舍的北部。<br><br>實驗對象的感想<br>「好吃！真是沁入身心的味道！<br>今天的疲勞好像都消失了！<br>變革，謝謝妳！<br>妳的魔法總是能夠<br>讓我打起精神來呢！」<br><br>結果：大大大成功！"},
{index="20067",text="「喂！要鬧到什麼時候啊！」<br><br>「Wow，Escape!<br>對不起～♪」<br><br>原先吵鬧的房間在被匆忙地關上燈後，<br>大樹便嬉嬉鬧鬧地跑了出來。<br><br>（哎呀，她這是在勉強自己打起精神呢）<br><br>說起來，今天多伯為了比賽<br>遠赴關西，所以不在宿舍。<br>兩人的遠征日期幾乎對不上，<br>也導致大樹常常獨自留在宿舍。<br><br>（真是的……寂寞的話，<br>大可以依賴我啊）<br><br>「站住！<br>──好，逮到妳了！」<br><br>「Oh～真遺憾！<br>菱亞，我已經反省了！<br>懲罰就no thank you……」<br><br>「大樹，今天要一起睡嗎？<br>來我的房間吧。」<br><br>「啊──！！我要去！<br>今天晚上好～溫馨喔！！」"},
{index="20068",text="在商店街街景所裁剪而出的<br>直長方框中，<br>她含蓄地笑著。<br><br>她的手掌托著太陽，<br>笑著說這麼做很孩子氣吧。<br>明明她自己也還是個孩子。<br><br>重壓在小小肩膀上的期待、<br>心中點燃的鬥志，<br>以及堅定掩藏的一絲澈悟。<br><br>種種的情緒，<br>都包含在她的那抹笑容之中。<br>於是，我如此心想。<br><br>那顆太陽，<br>直徑約有140萬公里，<br>是這世界上最大的金牌，<br>乘在她的掌心上再合適不過。<br><br>我向她許願。<br>希望她能保持笑容。<br>至少在這一刻天真無邪地笑著。<br><br>我向天空許願。<br>當她伸手抓住太陽時，<br>但願我是那個能握住<br>那雙纖柔的手，不讓她被灼傷的人。"},
{index="20069",text="＝＝＝＝＝＝＝＝＝<br>〇月×日（△）　天氣：太陽閃亮亮～！<br><br>今天小待跟小福前輩還～有小濤，<br>一起替占卜小屋大掃除了。<br><br>我們把金光閃閃的魚虎，<br>還有叼著胡蘿蔔的招財貓，<br>全都擦得亮～晶晶～！<br>最後輪到要擦幸運之壺～！<br>的時候……<br>的時候！！！！！<br><br>（小小的蜘蛛插畫）　←出現這個（＞＜）！<br><br>小待被嚇得半死！<br>小福前輩也被嚇得半死的小待嚇得半死！<br>小濤也被嚇得半死的小福前輩嚇得半死！<br><br>亂揮的撢子正中自己的鼻子。<br>淚水滑落。鼻血也直直落。<br>今天真是「好命苦啊～」的一天。姆～<br>＝＝＝＝＝＝＝＝＝"},
{index="20070",text="──喂，媽媽？<br>好久不見，妳過得好嗎？<br><br>──我嗎？我剛跟駿逸她們三人<br>一起吃完中餐哦。<br><br>──駿逸還是跟以前一樣<br>只愛吃褐色的東西，<br>比布魯斯也只吃讓她心動的東西而已。<br>真是讓人傷腦筋的孩子們！<br><br>──啊，不過妳放心，<br>我有讓她們好～好吃菜、吃飯。<br><br>對付比布魯斯就用老樣子的讚美戰術，<br>駿逸的話……如果她不吃，<br>就一直追著她說「我要餵妳囉」。<br><br>──呵呵。<br>哎呀，一點也不辛苦哦。<br>我早就習慣了。<br>而且……<br><br>──媽媽也很清楚吧？<br>我最喜歡照顧那些孩子們了。"},
{index="20071",text="「──心情振奮得令人差點放聲大叫。<br>即將衝過最後彎道之際，萊斯的雙耳<br>清楚地聽見了珍視的人們的聲音。」<br><br>（萊斯描繪的景象<br>清晰得彷若觸手可及……既然如此，<br>這裡就要刻意來場pianissimo呢……<br>畢竟迎來高潮前的情感累積可少不了啊。）<br><br>「一句『小萊，加油！』……<br>讓萊斯的心裡不再有絲毫迷惘。」<br><br>（接著從這裡接上最後的副歌！<br>蓄勢待發！<br>用慢板節奏演奏主題曲！<br>Grandioso！）<br><br>「踩踏大地的聲音響起。<br>下個瞬間，簇擁到了看台前的觀眾們，<br>看見一道疾驅在直線上的光芒──」<br><br>「……完美啊！果然在高潮時刻迎來<br>由交織的情誼而奮起的王道熱血青春發展，<br>具有一種普遍的力量呢。<br>而且，爭鳴……<br>這真是最棒的配樂！」<br><br>「哪裡哪裡，我的靈魂都為之震撼，<br>情不自禁地就加入了。<br>多虧了妳才能誕生如此美妙的旋律。<br>該道謝的是我才對喔，萊斯！」"},
{index="20072",text="大地見證了一切──<br>見證了原初的存在，<br>從冰與火的一滴中誕生。<br><br>見證了諸神以大樹為根基，<br>反覆上演著繁榮與爭鬥，<br>最後迎接黃昏的到來。<br><br>見證了世界終將迎來毀滅，<br>而後迎來新生。<br><br>──也就是說。<br><br>如果注入了最初的一滴，<br>就見證它的命運──<br>就將酒杯打磨到最後──<br>如此一來，<br>便能因新的潤澤而重生。<br><br>「好棒……！亮晶晶的！<br>那我也要更努力打磨！」<br><br>「……呵。很棒的決心。」<br><br>沒錯，我們也是如此。<br>只要努力打磨自己，這場命運<br>或許有朝一日便能迎來新生也說不定。"},
{index="20073",text="「──咦，是夕陽耶，天啊。」<br><br>「放學後時間的消失速度根本馬赫等級吧？<br>在放學之前明明都很漫長的～真不可思議。」<br><br>「啊？什麼？<br>相論……相……<br>相對論？」<br><br>「咦，所以我平常在說<br>『上課是要上一輩子？』是真的發生了嗎！？<br>什麼跟什麼，也太糟了吧～～！」<br><br>「……是喔，<br>所以才會覺得跑跑步、<br>閒聊一下時間就過了啊。」<br><br>「原來如此～哦……」<br><br>「但反正只要盡情跑步、<br>盡情閒聊來彌補就好啦！<br>所以你就再陪我一下吧～♪」"},
{index="20074",text="「那個，就是……！<br>八重，我是妳的粉絲！<br>妳總是強大又帥氣……<br>我最喜歡妳了！」<br><br>「好、好可……咳咳，<br>感謝妳一直不吝支持。」<br><br>（糟糕，實在太惹人憐愛，<br>讓我的表情忍不住鬆懈下來……<br>得繃緊神經才行！）<br><br>「──不勝惶恐！<br>我往後也會努力精進，喝啊！」<br><br>（我得好好守護──<br>她那份稱讚我「很帥氣」的憧憬！！<br>就算要賭上自己這條命！！！！）<br><br>「哇啊～好厲害！好帥喔～！<br>不勝惶恐！喝啊！<br>欸──媽媽！<br>我也能變得像八重一樣嗎？」<br><br>「呵呵，這孩子也真是的，<br>她總是在家裡<br>玩模仿八重的遊戲呢。」<br><br>「……！<br>唔……呃，好可……唔唔唔……！」<br><br>「這是我的榮幸，喝啊！！」"},
{index="20075",text="　　【Crew!（42）】<br><br>踢踏：<br>今天買披薩過去！！<br><br>GURA：<br>好突然啊，我要照燒的<br><br>HB：<br>為什麼啊～（笑）人家要瑪格麗特<br><br>茶子：<br>真的假的？我要有起司的<br>啊，我會帶點心去<br><br>踢踏：<br>我這裡有巧克力！大豐收！<br>Let's party!<br><br>HB：<br>有夠莫名（笑）<br>啊，那人家買飲料過去～<br><br>踢踏：<br>我在電玩中心收穫超多巧克力！！<br>披薩買20片夠嗎？<br><br>雙：<br>太多了太多了！<br><br>GURA：<br>可以啊，妳要負責吃光喔。<br>能幫忙買飲料的人超商集合<br><br>踢踏：<br>Okay！點餐到下午四點為止！<br>You snooze, you lose!<br><br>　　　　◆<br><br>「To surviving another day!<br>好好大鬧一場吧！」<br><br>「Foo～～～～～～～～！！」"},
{index="20076",text="「同世代賽馬娘的競賽報告」。<br>……我已經有了。<br>話說收集情報是機器人的工作。<br><br>「關於肌肉量和生理時鐘的關聯性」。<br>要我重新檢視睡眠時間？<br>……有夠麻煩。<br>是是是，會每天早上在規定的時間起來。<br><br>「提升呼吸肌訓練效率的提議」。<br>……哦？<br><br>啊啊？怎樣啦。<br>有不錯的數據當然要輸入進去吧。<br>……不要什麼都大驚小怪，噁心死了。<br><br><br>……所以？議題就這些了？"},
{index="20077",text="「奇奇前輩，<br>保溼乳液準備好囉～」<br><br>「不愧是小緞！<br>那就開始吧。<br>做好保溼工作，讓肌膚變得水嫩喔～」<br><br>「好的──！」<br><br>「……呃，是要從哪裡開始啊～？」<br><br>「先從小腿開始……<br>為了讓乳液吸收，在抹的時候要記得推上去。<br>呼嗯嗯嗯……我推我推～」<br><br>「哇啊～要出不少力氣呢。<br>感覺在很累的日子會偷懶……」<br><br>「疲憊的時候更要這麼做喔。<br>體態的保持，還有肌膚的保養，<br>只要妳偷懶一天，成效就會跟著倒退一天呢！」<br><br>「喔～真是名言。<br>那我也盡量能做到多少就做多少吧～<br>用力推～～～」<br><br>「就是這樣！<br>讓我們一起追求彈嫩的肌膚吧♪」"},
{index="20078",text="～「萬福招來☆福氣護身符」製作方法～<br><br>①<br>先準備布料！<br>花樣最好選擇<br>能夠消災的吉祥圖案！<br>這次選用即使在寒冬也會開花，<br>難能可貴～的梅花圖案！<br><br>②<br>選好布料後就開始縫紉成袋狀！<br>為了別讓神靈力量跑掉，<br>可用布櫬一針一針地仔細縫好♪<br><br>③<br>做好袋子後，用繩子穿過袋口！<br>建議這時可用繩子繞一個圈打結兩次，<br>就會更吉利喔！<br><br>④<br>接下來！從這裡開始是福來流！<br>帶著完成的護身符，<br>去各地所有的神社參拜！<br>和護身符一起努力累積功德！<br><br>⑤<br>終於來到最後一步！<br>之後只要將自己的願望<br>全力灌注在這個護身符上就好！<br><br>「──就是這樣！」<br><br>「馬上來注入心願吧！<br>呼哪嘎～哈哪嘎～」<br><br>「來吧，大聲許願！！」<br><br>「…………」<br><br>「喔喔，很棒的願望！<br>那麼就來收尾──」<br><br>「希望你的願望能夠實現～～！」<br><br>「好啦！這樣一來<br>『萬福招來☆福氣護身符』就完成了！！」<br><br>「還請好好收著，<br>直到願望實現的那一天喔♪」"},
{index="20079",text="「哇啊啊～～～☆素質、素質！<br>太陽公公亮晶晶呢★<br>真是最棒的美麗～☆★」<br><br>「呼啊啊……<br>是是是，美～麗……」<br><br>「汪汪汪汪～☆（美麗～☆）<br>喵～喵喵～☆（美麗～☆）<br>咕～咕咕咕咕～☆（美麗～☆）」<br><br>（……根本不知道她在說什麼，<br>卻有種多～少能理解的感覺。）<br><br>「噫～噫噫～☆（美麗～☆）」<br><br>「呃那是什麼！？是什麼生物！？」<br><br>「咦？<br>是美麗啊☆美麗★」<br><br>「這、這樣啊……」<br><br>（嗯──還以為自己搞清楚了……<br>但好像其實並沒有？<br>真是太深奧了啊，美麗。）<br><br>「大家～～～～～☆<br>今天一天也要美麗～～～～～★」"},
{index="20080",text="髮絲飄散月桂芬芳，嘴唇增添柑橘香氣。<br><br>溫柔地、溫暖地、仔細地，<br>為心頭點綴上泡泡的魔法。<br><br>塗抹在腳尖上的乳液，妝點指尖的金合歡。<br><br>今天也謝謝妳，明天也請多指教。<br>我為最重要的妳，點綴了魔法。<br><br>「……完成♪讓妳們久等了。<br>尾巴保養油想用哪種香氣的呢？」<br><br>「回歸初衷……那用櫻花的如何！？<br>我們第一次互相擦乾尾巴時用的那種！」<br><br>「『胡蘿蔔，不會忘記田地』……對吧！<br>呵呵呵♪那麼，我們就開始吧！」"},
{index="20081",text="「很好！這樣這孩子的衣服就做好了」♪<br><br>少女替與朋友如出一轍的人偶<br>穿上用心親手縫製的服裝後，<br>滿足地端詳著眼前的成果。<br><br>「飛翔好厲害！<br>真的好可愛呢。<br>小真娃娃也在跟<br>飛翔說謝謝哦。」<br><br>少女的雙眼隨即閃過光芒──<br>在某些人看來，甚是熠熠生輝。<br><br>「呵呵，<br>要道謝還太早了哦。<br>因為接下來才是重頭戲啊！」<br><br>語畢，她拿出了<br>佈滿使用痕跡的量尺與文具用品。<br><br>「這次的主題是<br>宛如雙胞胎的甜美可愛成對穿搭！<br>所以說，妳能過來這裡嗎？<br>因為我想仔細地量尺寸♪」<br><br>「哇哇哇？<br>難道飛翔妳燃起鬥志了？」<br><br>「當然，既然要做就要全力以赴！<br>身高、肩寬、袖長還有手腕圍──<br>要量的地方很多，我們快點開始吧！」<br><br>來，先低下頭──<br>充滿活力的談話聲，<br>在那之後還持續在房間裡迴盪了好一陣子。"},
{index="20082",text="撲通──<br><br>當身體進入水中後，<br>我隱約聽到遠方傳來了<br>重砲和券藏的歡呼聲。<br><br>抱歉啦，我搶第一個跳下水了。<br><br>因為我實在忍不住了。<br>空無一人的泳池，<br>以及那座高聳並彷彿在對我說<br>「來挑戰啊」的跳水台──<br><br>我從衝出去那刻就興奮不已，<br>起跳的瞬間更是興奮到了最高點。<br><br>膨脹的心情，猛烈地迸發開來！<br><br>嗯，果然很棒。<br>最先縱身躍進泳池的這股心情。<br>唯獨這份舒暢的感受，<br>我不想讓給任何人──<br><br>「好嘛好嘛──下一個換人家！<br>人家也會像泡泡一樣，<br>帥氣地起飛的！」<br><br>「那我就排在再下一個！<br>我可不能輸給妳們兩個呢！」<br><br>看著重砲和券藏面帶興奮神情站上跳水台，<br>我在泳池裡對兩人呼喊。<br><br>「快點下來吧！<br>感覺真的超棒的哦！」"},
{index="20083",text="皎潔的月光勾勒出<br>蘊含深藍色的烏黑秀髮，<br>白瓷般的肌膚，封存星光的紫水晶眼瞳。<br><br>就連在凜冬中璀璨閃耀的玉盤，<br>都不過是照亮她的聚光燈罷了。<br>如同一幅裝飾在奢華畫框裡的名畫，<br>她的身姿優雅卻魅惑人心，<br>沉靜卻充滿活力。<br><br>若能將此時此刻舀起，<br>保存在玻璃罐之中……<br><br>若能嘆著氣，<br>目不轉睛地凝視著<br>這無法衡量價值的瞬間……<br><br>我，一定會──<br><br>獻上自己所擁有的全部時光吧。"},
{index="20084",text="自出道後拿下四連勝。<br>作為挑戰三后冠的前哨戰，<br>我跑出了有史以來最好的成績。<br><br>……不過，這也只是第一步罷了。<br>只是剛開始踏上通往巔峰的階梯──<br>我抱持著那樣的心情。<br><br>我打算比過去<br>更加嚴格地進行訓練。<br><br>我會在鑽研的道路上，輝煌地留名青史，<br>所以還請多多指教了。<br><br>（沒錯，這只不過是個起點！<br>我的連勝之路，<br>還會繼續下去的～～！）"},
{index="20085",text="哈、哈、哈密瓜♪<br>哈密瓜聖代♪<br><br>甜美香氣誘惑著我♪<br>哈、哈、哈密瓜♪<br>哈密瓜聖代♪<br><br>只有今天♪只在中午♪<br>哈、哈、哈密瓜♪<br>哈密瓜聖代♪<br><br>吃下一口熟透的你♪<br>哈、哈、哈密瓜♪<br>哈密瓜聖──<br><br>…………<br><br>……嗯？<br><br>「怎麼了嗎？<br>生野。」<br><br>「呵呵……我覺得這是首<br>能直接傳達坦率心意的好歌。」<br><br>「……歌？<br><br><br><br>──────啊！！」"},
{index="20086",text="「唔……呼……<br>『哈、哈囉！那朵藍色薔薇，<br>真的灰常漂──』……！<br>我又吃螺絲了……」<br><br>「……那、那個啊。<br>因為這次得到了<br>當志工唸繪本的機會，<br>所以我想好好努力一下……」<br><br> 「我練習了一陣子，<br>可是完全唸不好……」<br><br>「這是我最喜歡的繪本中，<br>最喜歡的一句台詞，<br>所以我想完美地唸好它……！<br>可是，越這麼想，<br>就越唸不好…………」<br><br>「唔唔，拜……不，訓練員！<br>請陪米浴<br>一起進行唸繪本的特信……！」"},
{index="20087",text="「Hey, little bird<br>What's got you down?<br>（欸，小鳥兒。<br>你在難過嗎？）<br><br>Those blue, blue days<br>Are when the sun comes out.<br>（天空灰暗的日子，正代表將要放晴）<br><br>So lift those wings<br>And take to flight<br>'Cause blue skies<br>are all right.<br>（展開雙翼，飛向藍天吧。<br>像這樣憂鬱的日子，其實也不壞喔。）」<br><br>「……好動人的曲子呢。<br>該說是被撥動了心弦，<br>還是從中獲得了活力呢……」<br><br>「Thank you♪<br>呵呵，這是對作曲者最棒的稱讚。」<br><br>「咦！？<br>這首歌是勇敢之心寫的嗎！」<br><br>「是呀，這可是一首魔法歌曲，<br>不管多麼blue都能讓人打起精神喔♪<br>妳要不要也來唱唱看呢？」<br><br>「……可以嗎？」<br><br>「With pleasure!<br>來，擺好電子琴♪」<br><br>「Hey, little bird～♪」<br><br>（……真不可思議。<br>最近那股總覺得做什麼都是白忙一場，<br>焦躁不安、鬱鬱寡歡的心情逐漸消散了。）<br><br>「──'Cause blue skies<br>are all right～♪」<br><br>（……嗯。）<br><br>（──明天再重新加油吧！）"},
{index="20088",text="清晨，整理好儀容後，<br>我會先去一趟日光房。<br>因為我想盡量趕在太陽高掛前，<br>幫盆栽澆水──<br><br>離開宿舍後，看看花壇狀況，<br>有需要的話就幫忙澆個水。<br>如果有花兒看上去很沒精神，<br>隨手記錄下來，以防遺忘。<br>這樣之後才方便照料──<br><br>到了學園的教室後，<br>先幫花瓶換水……<br>換完水以後，<br>再一朵朵地調整花朵的角度，<br>讓它們呈現出當天最美的樣子──<br>碰上適當的時節，<br>也會加入新季節的花朵。<br><br>……我做的事情就差不多是這樣而已。<br>每一件都不是什麼大不了的事。<br><br>不過，就算是微不足道的小事，<br>只要一件件匯聚起來……<br>或許就能像一捧小小的花束──<br>為某人的日子增添一抹色彩。<br><br>若真能如此，那就太好了。<br>──我一直都是這麼想的。"},
{index="20089",text="那份狂熱，再度回歸──<br>眾位Prinfight齊聚大銀幕！<br><br>「不會吧，這裡是……<br>遊戲的世界──！！」<br><br>在超人氣遊戲的女神引領下，<br>Prinfight們踏入了劍與魔法的冒險世界！<br><br>「偶爾拿劍上陣感覺也不錯呢♪」<br><br>「如果讓我施展魔法，<br>我可是最強的！」<br><br>「是、是龍！？<br>不要──！人家很怕蜥蜴啊──！」<br><br>即便在遊戲世界，Prinfight也大顯身手。<br>一路高歌猛進，直達魔王之塔！<br>然而──<br><br>「怎麼會……女神大人，妳為什麼……！」<br><br>「Prinfight只要有我一個就夠了。<br>妳們的力量我就全收下了！」<br><br>力量被奪走導致無法變身，<br>同伴們一個接一個地倒下。<br>難道我們再也無法奔跑了嗎──<br><br>「……不對，我──我們！<br>已經創造過無數次奇蹟！」<br><br>讓拳頭承載大家的愛、正義與友情，<br>馳騁過奇蹟的勝利之路吧！<br>《劇場版Prinfight All Stars<br>奔跑吧，奇蹟的幻想之路》<br><br>「觀影贈品是奇蹟的<br>蹄鐵造型手燈！」<br><br>■試映會粉絲反響<br><br>「我長大後也要成為<br>Prinfight！」<br><br>「猛……我推太神了……<br>除了可愛，找不到其他形容詞……」<br><br>「這次也輕輕鬆鬆就超越我的期待！<br>真的太棒了！」<br><br>「Prinfight最棒了────！！！」"},
{index="20090",text="「哦，雨停啦！<br>嗯，身體也弄乾淨了，這樣就沒事了。」<br><br>「下次可別在下雨天爬樹了喔。<br>不然又會下不來的──」<br><br>「──哈啾……！！<br>抱歉、抱歉。嚇到你了吧？」<br><br>「哇，啊哈哈！<br>好癢喔，別舔了啦～！」<br><br>「小貓是想用自己的方式幫我擦身體嗎？<br>你很溫柔呢！」<br><br>「但是，我沒事的！<br>畢竟我很強嘛！」<br><br>「倒不如說，淋雨的英雄更顯得帥氣？<br>開玩笑的啦！啊哈哈哈哈！」"},
{index="30001",text="「各各各、各位，真、真的很感謝<br>你們總是熱情支支！」<br><br>大吃螺絲的樣貌十分逗趣，<br>會場內響起了歡笑聲。<br><br>「有、有好多人……！」<br><br>「小特，冷靜點。」<br><br>「不是練習過了嗎？不要緊不要緊！」<br><br>或許是因為兩人的話語而重拾冷靜，<br>她做了一次深呼吸，挺身面向前方。<br><br>「我、我今天，會努力傳達<br>對大家的感謝之意！」<br><br>歡呼聲隨著她的話語響起。<br>充滿笑容的勝利演唱會就此開始。"},
{index="30002",text="「其實……我有點害怕。<br>不知道該向大家傳達些什麼。」<br><br>演唱會會場變得一片寂靜。<br>只為了不漏聽那名站在中央的少女<br>口中所傳達出的一字一句。<br><br>「我……只是很喜歡跑步。<br>對跑步以外的事都不感興趣。」<br><br>她在一陣思考跟迷惘後，開口說出──<br><br>「不過現在我只想唱歌給大家聽。<br>要是能跨越這個舞台，<br>總覺得……就能明白為何會有這股激動的心情。」<br><br>──曲子響起。她做了一個深呼吸，<br>將手伸向前方──那裡有答案正在等待著她。"},
{index="30003",text="「嗨嗨──！雖然歌才唱到一半，<br>但大家看過來帝皇大人這裡♪」<br><br>在舞台一角進行粉絲服務的<br>東海帝皇，踏著輕快的步伐<br>開始在正中央跳出正確的「舞步」。<br><br>「今天的我是第1名，就站在中央！<br>不管是競賽還是演唱會，我都是最強的♪<br>──往後也永遠都是這樣喔！」<br><br>就連光芒四射的聚光燈<br>也站在她這邊，接著她豎起三支手指。<br><br>「我想成為『不敗的三冠賽馬娘』<br>根本是輕而易舉的事！<br>所以大家不用猶豫，放心跟著我吧♪」"},
{index="30004",text="──阿船艦不需要燃料。<br>有趣就會擅自起跑，膩了就丟一邊去。<br>黃．金＝船1世。<br>（詩人、超哲學家、鬼冒險家／？？？？～）<br><br>「礙事礙事！讓開讓開──！！」<br><br>最後的直線，應該在最後方的那個<br>可恨傢伙，揚起銀髮加速前進！<br><br>「呀喝──！大獲全勝～！」<br><br>發動大膽無畏、出乎意料的瞬間移動──<br>穿越終點鏡板後來到北極。<br><br>「喔喔，不小心越過K點了！<br>真是的，阿船也太粗心了☆」<br><br>下一集，「關東煮」絕對要看喔！"},
{index="30005",text="──對了，「她」在哪裡？<br>邁向直線的激烈競賽中，<br>在某人這麼低喃時，她早已開始加速。<br><br>「好耶！！在這裡開始一決勝負！」<br><br>從後方選手群中衝出來的伏特加，<br>就這樣輕巧地不斷往前直奔，<br>如滑行般超越一人又一人。<br><br>「嘿嘿！我是第一名……！」<br><br>不斷忍耐、慢慢熱身的引擎<br>以絕佳狀態持續加速，接著──<br><br>「這就是伏特加大人，給我記住了！」<br><br>一而再、再而三地大量排氣，然後獲勝。<br>能成為傳說的，<br>永遠都只有能貫徹自我魅力的人。"},
{index="30006",text="「插花是心的表現……」<br><br>伴隨清脆的聲響，<br>草上飛拿起剪下的花，<br>露出柔和的笑容。<br><br>「曾經有人這麼說過呢～<br>要用最美的姿態，去表現綻放於四季的花朵。<br>花展現出來的樣貌，就是插花者的心吧～」<br><br>帶著柔和笑意的眼角不經意地收緊，<br>看準位置……插上最後一朵花。<br><br>「那麼……覺得如何？<br>希望我的心有符合你的期待。」<br><br>纖細又豪邁。<br>她的「心」平穩而蘊藏鬥志，凜然而立。"},
{index="30007",text="──神鷹！神鷹！神鷹！！<br><br>在一片怒吼似的呼喊聲中，<br>一道搖晃的身影踏上舞台。<br><br>「紅區！來自──美國！<br>身高163公分，體重是祕密！<br>翩然降臨擂台的面罩選手，她的真面目是！？」<br><br>敞開大衣……那道身影往上擊拳！<br><br>「『怪鳥』！！<br>神──鷹──！！」<br><br>──哇啊啊啊啊啊啊！！！！<br><br>「Are you ready！？<br>藍區的你們！準備好跳舞了嗎！？<br>來吧！一起！震撼心靈！！」"},
{index="30008",text="一切都是她的策略。<br>察覺到這點時已經太遲了。<br><br>「呀哈哈～！我是第一名～♪」<br><br>配合發動後追的競爭對手，<br>青雲天空仍是高速奔跑。<br>「領頭」賽馬娘的關鍵在「最後的直線」。<br><br>「『不斷領頭休息』作戰大成功♪<br>這樣就算之後放慢也──」<br><br>「小青……我會追上妳的……！」<br><br>「──不會這麼輕鬆啊。呿！」<br><br>（不過我打從一開始就沒打算輕鬆獲勝。<br>畢竟我……也是想要贏的！！）<br><br>「能追上抓住我就試試看啊。<br>雲可是沒有形體的♪」"},
{index="30009",text="「怎麼樣，我可是狀況絕佳喔！！<br>……唔，喂喂喂，你在看哪裡啊！？」<br><br>嬌小的賽馬娘不斷跳躍。<br>在圍場的玉藻十字<br>就算又叫又跳也還是不醒目。<br><br>「喂──所有人都給我看向這裡！<br>別因為我個子小就瞧不起我──！！」<br><br>使盡全力往上跳，<br>終於吸引到眾人的目光──<br><br>「聽好，你們給我做好覺悟了！<br>會讓你們看見我奔跑的樣子感到害怕！」<br><br>那些面露微笑看著她生氣大喊的觀眾們，<br>再過不久就會被閃電給震懾到了。"},
{index="30010",text="「哇啊，好美……」<br><br>全場的粉絲配合曲子擺動。<br>美妙姿勢揮動的手，<br>也彷彿自然地流露出氣質。<br><br>（在競賽的心跳加速後，<br>竟然還有這樣的心跳加速在等著我）<br><br>讓人分不出是否為窗邊的剪影，<br>這份感動遠遠超出她的夢想……<br><br>（我還想要更多更多的回憶！<br>在這所特雷森學園和大家一起，再多──）<br><br>「奔跑、跳舞、歡笑！好好享受♪」<br><br>──因為幸運的四葉草，<br>是要不斷奔馳才能找到的！"},
{index="30011",text="即使是在微風吹拂的閘門之中，<br>艾尼風神仍在想著家人。<br><br>「爸爸、媽媽、妹妹們。<br>看著吧，姊姊會加油的！」<br><br>她起跑衝刺，全力飛奔而出。<br>或許因為這樣的反作用力讓她有些向右傾倒。<br><br>（糟糕！不過不要緊！）<br><br>使力抬高後腳，立刻調整好姿勢。<br>下個瞬間，失誤、家人、競爭對手<br>全都被她拋在腦後──<br><br>「呼啊、呼啊、呼啊……啊哈哈！」<br><br>微風根本不足以放在眼裡，<br>因為她就是橫掃賽場的暴風。"},
{index="30012",text="剩下200公尺，剛好在有點超過<br>起跑點的地方，好友們再次聚集。<br>跑在前列的勝利獎券<br>不用回頭也能感受到後方的熱意追趕。<br><br>「呼啊……呼啊……！可惡……！」<br><br>「呵……獎券……！」<br><br>（好開心！好開心！好開心！<br>還想再繼續和大進與晨光一起跑！）<br><br>但是她為了甩開兩位好友，<br>使出全力地放聲大喊。<br><br>「唔喔喔喔喔啊啊啊啊啊啊啊啊！！」<br><br>（不想輸、不想輸、不想輸！<br>就因為是那兩人，因為是朋友，所以……！！）<br><br>「絕對不會讓她們追上！！」"},
{index="30013",text="（沒有絲毫誤差……剛剛好，出發！）<br><br>空中神宮一臉猙獰地飛奔而出時，<br>「又來了」……場內所有人都如此嘆息著。<br>常有的失控表現，體力不可能維持得了。<br><br>（你們都會膚淺地這麼想吧）<br><br>然而她不但沒有亂了步調，甚至開始加速，<br>嘆息逐漸轉為驚呼聲。<br><br>（早就知道會有這樣的發展。<br>我可是有反過來推算增加持久力了！）<br><br>不斷進行的模擬情境<br>只導出一個「公式」，然後──<br><br>「證明結束，笨蛋！」<br><br>超乎預期的結果，使場內陷入一片罵聲之中，<br>只有空中神宮──露出嘲笑的神情。"},
{index="30014",text="金髮揚起，使雨滴柔順地滑過。<br>遠看美的讓人屏息，<br>但黃金城市其實──滿身泥濘。<br><br>「只要、再……一下下……！」<br><br>在這最後衝刺只要保持領先就能獲勝。<br>然而身旁不遠處就有氣息緊追而上，<br>腳下踩踏的泥土毫不留情地噴濺上來。<br><br>（啊──好難受，腳好沉重！<br>可是要堅持！堅持下去就能贏……！）<br><br>在分秒都不能鬆懈的攻防戰中，<br>她的表情卻非常亮麗。<br><br>（我現在的心情非常好……！）<br><br>──雨水、泥濘、汗水都是裝飾品。<br>這裡就是我展現光芒的伸展台！"},
{index="30015",text="「請看！<br>這就是班長的便當！」<br><br>櫻花驀進王的自信似乎都要<br>從便當盒滿出來……不，是已經滿出來了。<br><br>「野餐就是要配三明治！<br>營養和配色都很完美對吧！？」<br><br>食物配合她說話的語調晃動，<br>麵包搖擺、小黃瓜跳起、火腿舞動……<br><br>「那麼就張大嘴一口吃下去！<br>畢竟野餐才剛開始！<br>所以快點吃，乾脆邊吃邊跑！？」<br><br>回過神來──發現那雙櫻色的眼眸已近在眼前。<br><br>「來吧！驀進地吃下去！！」"},
{index="30016",text="來，給你一顆糖～<br><br>……沒錯，就是你喔。就、是、你♪<br>給一直看著我的你～<br><br>呵呵，一臉不安的樣子呢～<br>擔心我是否能獲勝嗎？<br><br>放心、放心。雖然小栗、<br>小稻和其他賽馬娘……<br>都很強，也都是乖孩子──<br><br>但一定會是我贏的。<br>所以還請放輕鬆守護我喔～<br><br>那麼，我要上場了～<br>要是你當個乖孩子靜靜等的話……<br>我就會摸摸你的頭喔♪"},
{index="30017",text="「各位──要喊出聲音來喔──！<br>首先讓我聽聽飛飛的優點♪」<br><br>可愛！聰明！超有意志力～！<br><br>「喂，最後的──！算了，無所謂☆<br>接下來喊飛飛的名字喔！」<br><br>領頭也很可愛，啊～飛飛──！<br><br>「嗯──感覺很棒☆那麼最後囉！<br>給飛飛愛心☆萌萌！」<br><br>L．O．V．E！<br>愛心萌萌飛飛──！！！！<br><br>「謝謝──！飛飛絕對<br>會持續領頭成為最紅賽馬娘偶像！<br>大家要全力追上來喔☆啾♪」"},
{index="30018",text="「今、今天我有話<br>想跟大家說……！」<br><br>握緊麥克風的手，<br>還有種稚嫩的感覺。<br><br>「真的非常謝謝大家<br>總是非常支持我。<br>雖然我還有很多事要學習，但……！」<br><br>──小小的花朵微微綻放。<br><br>「總有一天，<br>我一定會成為獨當一面的成熟女性！<br>還請大家能夠一直守護我喔！」<br><br>那天的演唱會後，會場的四處都傳來<br>「我要長命百歲」的喃喃低語……"},
{index="30019",text="冰淇淋之歌　　　　　主唱：春烏菈菈<br><br>冰淇淋、冰淇淋太棒了！<br>玩偶冰淇淋就更～棒了！<br><br>用機械手臂夾起來，就算搖晃也不會變形。<br>是因為吃下硬幣所以變大了嗎？<br>強大又無敵的超級冰淇淋！<br><br>冰淇淋用力抓住就會融化。<br>不過玩偶的話就可以盡情磨蹭！<br>（怎麼咬怎麼舔都沒味道喔！）<br><br>冰淇淋、冰淇淋全部都很棒！<br>不管是草莓、橘子、哈密瓜、葡萄還是──<br><br>「耶嘿嘿，變得想吃冰淇淋了！<br>一起去買吧──♪」"},
{index="30020",text="「唔唔，演唱會還想再更嗨一點？<br>看來要輪到正義的同伴出場了！」<br><br>「──也請務必讓我協助！」<br><br>「啊！這個聲音是……！」<br><br>「營養滿點！正義滿點！<br>胡蘿蔔素充能，胡蘿蔔超人！<br>以及──」<br><br>「用正義的翅膀打擊邪惡！奔跑展翅<br>拯救世界！直轟天際，微光飛駒！<br>最強英雄組合在此登場！」<br><br>──咚磅！！<br><br>「我們會守護大家的笑容！<br>來吧，上演正義的時刻！！」"},
{index="30021",text="訓練員，辛苦了！<br>我是理事長祕書的駿川手綱。<br>往後會全力提供支援，<br>什麼事都能找我商量，還請別客氣喔♪<br><br>那麼事不宜遲，這是本校的資料，<br>還請在開始工作前過目。<br><br>這間特雷森學園為賽馬娘們<br>提供充實的教育和設施。<br>當然，也會提供讓訓練員得以<br>成長的專業知識，還請放心！<br><br>衷心期待能和你一起工作。<br>往後也一起為了賽馬娘們<br>好好努力吧！"},
{index="30022",text="「謝謝大家的支持！」<br><br>目白麥昆優雅地揮著手。<br>從她額頭流下的汗水，<br>才勉強能看出她剛經歷過一場激戰。<br><br>「不過這次的第1名還只是夢想的中繼點。<br>我會懷抱著目白家的榮耀，<br>往後也將持續華麗地得到勝利！」<br><br>她尊貴的宣言讓觀眾歡聲如雷。<br>如大小姐般的舉手投足，在她轉過身後──<br><br>（決定了，今天要享用蛋糕獎勵自己。<br>該吃什麼好呢……）<br><br>──那在愉悅中煩惱的背影，<br>還充滿著少女的稚氣。"},
{index="30023",text="（加油啊，米浴，加油……！）<br><br>希望自己得到勝利的，只有一個人。<br>只有自己一人，少女是這麼想的。<br><br>──米浴、米浴、米浴、米浴……！<br><br>不過盡全力跑完後，<br>迎接少女的卻是彷彿飄落自無盡穹蒼的<br>盛大聲援。<br><br>「那……那個，呃……」<br><br>少女感到驚訝和困惑……即使如此，<br>少女還是邁出了那微小、但富含著巨大意義的一步。<br><br>「謝……謝謝、大家……！」<br><br>觀眾對少女的歡聲一直持續著，<br>完全沒有停息──"},
{index="30024",text="（盯著看…………）<br><br>「……嗯，身為布偶的我真是惹人憐愛。」<br><br>這是當然的，畢竟「我」<br>是在大量愛情的灌注之下誕生的。<br><br>「你們接下來會去到各式各樣的人身邊。<br>為了被珍惜、被疼愛。」<br><br>「媽媽～小栗栗好可愛唷。<br>好想緊緊抱住～！」<br><br>「啊……看來現在就是出場時機了呢。<br>交給你囉，『我』。<br>就連我的份一起被緊緊抱住吧。」<br><br>──拜託了！"},
{index="30025",text="特特，謝謝妳的來信。<br><br>沒想到妳立刻就迷路了，嚇我一大跳。<br>真搞不懂特特是路痴這點遺傳到誰……<br>要記得好好地向鈴鹿道謝喔。<br><br>我也很高興妳能認識溫柔的賽馬娘呢。<br>妳們似乎是住同一間寢室，<br>不可以睡過頭或是弄得亂七八糟，<br>給人家添麻煩喔！<br><br>現在才比較能說出口，我其實一直很擔心<br>特特會在沒有賽馬娘的土地上感到寂寞，<br>所以知道妳交到鈴鹿這個朋友，<br>媽媽真的很高興！<br><br>要多跟朋友享受學園生活，<br>我會寄特特最喜歡的胡蘿蔔過去，<br>跟鈴鹿一起享用吧。<br><br>祝福特特無論何時都幸福快樂。<br><br>　　　　　　　　　　　　媽媽筆"},
{index="30026",text="鏡頭中，<br>一名少女飛躍進來。<br><br>「大家哈囉──！我是渦輪──！<br>欸欸，有確實拍到嗎？？<br>……這樣啊！有在拍就好──！！<br>跟你們說，這次的比賽意義非凡──！」<br><br>少女這樣說著，並把臉靠近攝影機，<br>閃閃發亮的眼睛眨了好幾下。<br><br>「所以我今天也會領先到底喔！！<br>一定～一定！絕對會做到！<br>會領先到底然後獲勝！！」<br><br>感覺不到對比賽的緊張感，<br>開朗且充滿希望的聲音。<br>讓眾人回頭望去的少女，<br>用宏亮的聲音高喊。<br><br>「因為渦輪很強，<br>不論何時，從起點到終點，<br>都是渦輪引擎全──開狀態！！<br>會一～直跑在最前面！」<br><br>也許因為年幼無知，<br>從少女口中說出來的話，<br>是天真──或者可稱為魯莽。<br><br>「不會輸的！！」<br><br>那是對自己的鼓舞，<br>又像是想推某個<br>停滯不前的人一把，<br>用堅定的語氣對著螢幕的另一頭說<br><br>「所以，要看著我！！」"},
{index="30027",text="「啊哈哈哈哈！！好嗨！<br>這樣下去也許有機會唷──！？」<br><br>在夾雜歡呼的笑聲中，傳來<br>「又是她們啊」的溫暖視線。<br>就跟平常一樣，<br>已經習以為常了──<br><br>（……對啊，<br>不管是我們還是別人，<br>都有機會，都有可能性）<br><br>感覺腳底充滿力量。<br>……真不可思議，我的全身就像在傳達<br>還可以繼續跑下去。<br>這種情況應該叫什麼？<br>我記得好像叫做「分危」怎樣的。<br><br>「喔喔！？善信好猛好猛有夠猛！<br>氛圍超級無敵嗨的啦！」<br><br>啊，就是那個。<br>……嗯，現在正處於那樣的感覺。<br>從觀眾席傳來的呼喊聲，聽起來也很舒服。<br>可以贏，衝刺吧，別停下來。<br>我對自己大喊著要全力奔馳。<br>但可能會在中途筋疲力竭──<br>我這樣不安的想著。<br><br>「拿下第一吧────！！！<br>善────信────！！！！」<br><br>當我聽見背後傳來的聲音時，<br>不安情緒一掃而空。<br>居然在奔馳的關鍵時刻<br>幫對手加油，這傢伙搞什麼。<br><br>（謝謝妳，太陽）<br><br>……啊，身體熱起來了。<br>我還有腳力。<br>跑吧，儘管往前跑，<br>提升速度、提升速度，<br>提升到極限──！！<br><br>「看著吧，這就是我的強勢領頭──！！」"},
{index="30028",text="（我也認為是時候了，<br>小鑽！）<br><br>──啊，真的很厲害。<br><br>我可以聽見吐息聲。<br>腳底撞擊地面的聲音越來越近。<br>如同閃閃發光的耀眼寶石般，<br>遮住了我看向前方的眼睛。<br>妳總是像這樣，<br>讓我一刻都無法鬆懈。<br><br>（……不會讓妳超前）<br><br>因為妳照亮了道路。<br><br>以些微差距敗北的痛苦記憶，<br>我至今都還牢牢記著。<br>讓我們彼此拿出全力，<br>奮力跑到終點。<br><br>很痛苦、很不甘心──<br>但也很快樂。<br>所以我絕對不會輸，<br>也不想再輸了。<br><br>（但終究還是）<br><br>追上來了。<br>想獲勝的執念，<br>朝我的後方逼近。<br>我的背後感受到<br>這股強烈情緒所產生的熱度。<br><br>（……嗯，好開心，<br>太開心了，小鑽）<br><br>妳差不多要發動攻勢了吧？<br>又是面帶笑容對吧？<br>我知道，因為我也在笑，<br>畢竟就是如此愉快。<br>我想就這樣笑到最後，<br>所以──<br><br>「現在才要開始一決勝負……！<br>這次的贏家一定是我！」"},
{index="30029",text="（如果是小北，<br>一定會在前方發動攻勢吧）<br><br>──啊，果然很厲害。<br><br>這道無論何時何地帶著我前進的<br>溫暖背影。不管是頭髮還是服裝，<br>簡直就像一道黑影般，<br>但她奔馳的身影卻如此耀眼。<br><br>（……我想超越她）<br><br>那道背影的前方一定更加耀眼。<br><br>雖然我也很喜歡和妳一起追尋夢想，<br>一起笑、一起哭，<br>一起手牽著手散步，<br><br>最喜歡與妳一起玩鬧著奔跑，<br>然後等妳突然停下腳步，<br>回頭問我「有跟上來嗎？」<br><br>（就算如此）<br><br>這裡是神聖的場所。<br>是要帶著敬意和誠摯態度挑戰的地方。<br>即使感到痛苦、疲累，<br>也要堅持到最後一刻。<br>那是被選上之人要在這個場所應盡的義務。<br><br>（……不過真開心。<br>對吧，小北）<br><br>妳那拚命的側臉，<br>似乎在對我回以微笑。<br>看到妳這樣，我就知道我們兩個的<br>心情一致。所以我也──<br><br>「這場比賽的勝利……就由我拿下了！」"},
{index="30030",text="（──啊，剛剛肩膀往上抬了？<br>腳步也似乎有點加快。<br>所以差不多要發動攻勢了呢！）<br><br>待兼唐懷瑟累積了<br>在別人眼裡絕不尋常的努力成果，<br>目前正在挑戰這場比賽。<br>即使如此，她──<br><br>（我已經仔細看過她們的比賽。<br>不論是跑法還是習慣，包含<br>進攻的時機都徹底研究。但還是──）<br><br>這就是所謂「普通的努力」。<br>因為想贏過跑在前面的背影，<br>所以才會是「普通」。<br><br>（但如果想獲勝，光靠這樣還不夠。<br>我的腳必須動得更快更快──！）<br><br>自己非常了解比賽充滿艱辛，<br>獲得勝利的艱難之處也深深烙印在心裡。<br>但這些都是理所當然的事情，<br>所以願意踩地踏步。<br>想要為了獲勝而追上那兩個背影。<br><br>「好！！我也要從現在開始<br>奮力往前衝囉──！！」"},
{index="30031",text="雪子──！要加油喔～！<br><br>……嗯？你問雪子是誰？<br>看，就是在那邊揮手的女孩啊！<br>看到她的笑容，內心就溫暖了起來～<br>雪子……就像大家的女兒一樣，<br>會到田裡幫忙，幫大家揉肩膀。<br>……不過啊……我們還是最喜歡她跑步的樣子。<br>她奔跑時看起來很開心，能為大家帶來活力。<br>……所以！我們今天<br>都是來為那孩子加油打氣的！<br><br>咦？你也願意一起幫她加油嗎？<br>……嘿嘿！眼淚還是留到之後吧！<br><br>好──！現在就讓我們一起喊！<br>……預備──！"},
{index="30032",text="鍛鍊身體是武術之道，也是通往一切之道。<br>奔跑、舞蹈、演唱以及禮儀，<br>萬物不練而無優矣。<br><br>那天在眾多強敵中獲得一等殊榮，<br>立於舞台中央是勝者的<br>榮耀也是職責，<br>這點應該銘記於心。<br><br>發聲的基礎就是要透過腹部，<br>將力量凝聚於丹田，<br>腳掌穩穩踩住地面。<br><br>觀眾的情緒有如萬丈氣焰般沸騰。<br>落幕時，我兩手握拳大喊<br><br>「──承讓！！」<br><br>把我的朋友櫻花千代王<br>嚇了一大跳，<br>觀眾、表演者都笑到東倒西歪。<br><br>接著我在深深一鞠躬後，離開了舞台。"},
{index="30033",text="絕對！<br>我以為我絕～對會哭的。<br>因為從小時候開始，<br>每當我想起來都會哭。<br><br>打比的勝利者訪談。<br><br>不過真不可思議，<br>當我真的站上這個地方，<br>卻完全不會想流淚。<br>畢竟我不想遺忘。<br>湛藍的天空、<br>全場觀眾的笑容以及歡呼。<br>與我最喜歡的朋友們<br>全力競爭的景色──全都不想忘！<br><br>如果淚水模糊視線就太可惜了。<br>三人約好一起奔馳、互相鼓勵，<br>為了不落敗而不顧一切抵達的……<br>是夢想之地！<br><br>「我是在這場最棒的打比中<br>獲勝的賽馬娘<br>勝利獎券！！」<br><br>而夢想，<br>還會一直一直持續下去──！"},
{index="30034",text="「──那個，<br>我們分別從不同入口進去，<br>並在裡面會合怎麼樣……？」<br><br>於是兩人分開行動，<br>朝那散發著甜蜜香氣的<br>薔薇迷宮深處前進……<br>──這是幾十分鐘前發生的事……<br><br>少女氣喘吁吁地小步跑著，<br>不論怎麼找都找不到。<br>但是……<br><br>（加油……加油啊米浴……！<br>米浴絕對要先找到……）<br><br>（就像那天，<br>米浴被找到一樣……！）<br><br>（我一定會找到……！）<br><br>在走過轉角的瞬間，<br>少女紅潤的臉露出燦爛笑容。<br><br>「……找到了……！」"},
{index="30036",text="「徹底管理競賽生活的一切。」<br>這是對尚未成熟的她們<br>最好的指導方式。<br><br>「為什麼擅自下決定，<br>做了計畫中沒有的柔軟訓練？」<br><br>「我想讓激動的情緒冷靜下來……<br>很抱歉自作主張。」<br><br>一時的情緒低落在預料之中，<br>這點無須擔心。重要的是其他地方。<br><br>「樫本訓練員！只是做<br>輕度的柔軟訓練，沒關係吧？」<br><br>「不，大有問題。<br>首先那個『輕度』的想法本身就錯了。」<br><br>「訓練、柔軟訓練、吃飯、睡覺……<br>這些都不能輕忽。」<br><br>我很清楚──競賽生活的壓力。<br>我很清楚──通往夢想的橋梁有多脆弱。<br>我很清楚──晦暗的道路有多冷。<br><br>「那麼……保險起見，再暖身一次吧。<br>因為今天的地下道有點冷。」<br><br>我會繼續管理，<br>那是我……樫本理子該做的事。"},
{index="30037",text="這條皇帝之道的第一步，<br>是奇蹟，抑或是必然──<br><br>震耳欲聾的掌聲響徹天際。<br>她悠然地<br>站上了優勝者區域。<br><br>快門的聲音彷若失控般此起彼落。<br>然而她卻一如往常，<br>威風凜凜地擺出姿勢。<br><br>彷彿這場勝利<br>早已是上天注定的結果一般──<br><br>她伸出了一根手指，<br>筆直地指向了天空。<br><br>「──首先，先拿下一冠。」<br><br>她的這句細語消失在了歡呼聲中。<br><br>而傳說，就從這裡開始──"},
{index="30038",text="只有優勝者才能站上的地方<br>──優勝者區域。<br><br>少女在前往那裡的路上瞪大眼睛。<br>一場意外的相遇，<br>少女憧憬的對象，就在眼前。<br><br>因為深受她優異的跑姿吸引，<br>那天下定決心要與她並駕齊驅。<br>是一心一意使她贏得今天的勝利。<br><br>在百感交集而說不出話的少女面前，<br>憧憬的她如夢似幻地走過來，<br>──並帶著溫柔的笑容。<br><br>或許是勝利的餘韻使少女大意了？<br>對方伸手替她綁好鬆脫的腰帶。<br>拉近了距離，<br>使少女的臉頰染上淡淡的紅暈。<br><br>在盛開的碩大花朵旁<br>──有小小的櫻花悄悄綻放著。"},
{index="30039",text="這裡是夢想國度夢幻UMA王國。<br>我是這個國家的公主。<br><br>今天是我與王子結婚的日子，<br>國民們都歡天喜地為我祝賀。<br><br>我穿著婚紗待在禮堂裡，<br>王子緩緩朝我走來。<br>正當我準備牽起王子的手──下個瞬間！<br><br>敵方的重要幹部突然帶著部下們現身。<br>當然，接著公主便與王子一起<br>把所有壞人徹底打倒！<br><br>身為公主、並且身為新娘！！<br>幸福當然要靠「自己的力量」<br>拿到手啊～～～～！！！"},
{index="30040",text="♪美味的胡蘿蔔結婚蛋糕♪<br><br>＜材料＞<br>麵糊……<br>胡蘿蔔　60根<br>低筋麵粉　9kg<br>蛋　120個<br>砂糖　4.5kg<br>奶油　6kg<br>泡打粉　12大匙<br><br>奶油……<br>奶油起司　7.5kg<br>牛奶　600ml<br>砂糖　2kg<br><br>♪要招待很～多朋友來喔♪<br><br>「蛋糕添加了滿滿的愛，<br>所以非常美味喔♪<br>來，訓練員也吃吧～吃吧～！」<br><br>「……欸，川上。<br>妳看那該不會是一人份吧？」<br><br>「那還用說！真不愧是菱曙，<br>那股豪邁氣度，連身為公主的我<br>都想向她學習呢～～！」"},
{index="30041",text="可愛的東西。<br>美好的東西。<br>漂亮的東西。<br>──與我不相襯的東西。<br><br>從以前就一直遠離這些事物。<br>因為華麗的東西會吸引許多目光。<br><br>不過我想進步，<br>想成為充滿自信的自己，<br>想變得不畏懼任何人的視線。<br><br>這件禮服就是我的決心。<br>是能讓我變堅強的──夥伴。<br><br>總有一天，我會成為<br>配得上這件禮服的我──然後為自己感到驕傲。"},
{index="30042",text="甩開甩開，<br>比賽的贏家確定是我了──<br>這種天真的想法，我從來沒想過。<br><br>「呵……！就知道妳會來！」<br><br>一股極為強烈的壓迫感由內襲來，<br>讓我的背脊微微顫抖。<br>然而這是。<br><br>（只是興奮而已！！）<br><br>不受任何人阻礙的最棒的瞬間，<br>我等待此刻已經很久了。<br>不需要任何小伎倆的單挑──<br>實力與實力的正面對決。<br>怎麼可能不燃起鬥志呢！<br><br>「……要上囉」<br><br>足以蓋過周圍喧囂的這聲低語，<br>讓我倒抽一口氣。<br>……來吧，從現在開始是重頭戲。<br>讓我們堂堂正正地<br><br>「──一決勝負！！」"},
{index="30043",text="是白，是黑。<br>是勝利，還是敗北。<br><br>投擲硬幣會出現正反面。<br>同樣的競賽在閘門開啟時，<br>就會決定誰是贏家，誰是輸家。<br>不過若是盛大的舞台，<br>似乎還會有許多稍微困難的因素交織在一起。<br>希望誰贏，誰是第一名的賽馬娘。<br>我聽見許多嘈雜的聲音。<br><br>因為支持度最高，因為和藹可親，<br>因為大家都相信她會獲得勝利。<br>──喂喂等一下，正因為<br>不知道誰是第一，所以才叫競賽不是嗎？<br><br>這場勢在必行。<br>勝利女神會對誰微笑？<br>時間只剩下兩分鐘多。<br>快樂的比賽現在才要開始。<br><br>好……必須專注於眼前的事情。<br>開場小號差不多該響起了吧？"},
{index="30044",text="歡呼聲消失了……靜悄悄。<br>什麼都聽不見。<br><br>「姊姊，等等我！」<br><br>剛才跑過去的是……？<br>原來……是小時候的我。<br><br>那就必須跑得更快，<br>不停地拚命跑直到追上為止。<br><br>「姊姊──已經跑不動了嗎？」<br><br>就算這樣妳也要繼續跑，<br>不顧一切、凝視前方，<br>帶著信念前進。這樣一來──<br><br>「嘿，我們再兩人一起……」<br><br>「……奔馳吧，大姊」<br><br>「嗯，好啊。白仁！」<br><br>「各賽馬娘已經入閘完畢，<br>現在……競賽開始～～！！」"},
{index="30045",text="（我吸我吸我吸……）<br><br>「嗯～♪這杯果汁又甜又爽口，<br>真好喝♪」<br><br>（偷瞄……）<br><br>「哼哼，你也想喝吧？<br>但我絕對不會給你喝的♪」<br><br>（我吸我吸～我吸……）<br><br>「……唉～已經快喝光了！<br>你沒有嚐過真的好可惜唷！」<br><br>（我吸～我吸……）<br><br>「……欸，你想喝吧？<br>那就老實地說出來啊！」<br><br>（…………）<br><br>「……哼哼，真拿你沒～辦法♪<br>來，你的吸管在這邊。」<br><br>（空空……如也）<br><br>「你快點喝吧～<br>雖然只剩下冰塊而已！噗♪」"},
{index="30046",text="「耶嘿──！！！！」<br><br>操控滑水寬板在空中<br>輕盈飛舞的勝利獎券，<br>讓船上也跟著沸騰。<br><br>「好、好厲害……！」<br><br>「這樣的技術實在不像初學者。<br>不愧是券藏！」<br><br>「這就是所謂的野性直覺嗎……」<br><br>「超棒的～～！<br>再來一次！！」<br><br>「很有幹勁嘛♪那券藏來個二連翻GoGo♪」<br><br>「交給我吧！<br>看好了，這就是我的──！！」<br><br>──就像滑水板濺起的水花般，<br>船上也發出響亮的歡呼聲。"},
{index="30047",text="「咦！咦！咦！咦～～～！？<br>為什麼我要在最前面啊啊啊！？」<br><br>（雖然我的確排在最前面，<br>但那只是我平常的習慣，<br>不用真的按照這個順序吧……！）<br><br>「等等，特別週！那是我的尾巴！<br>不要抓……啊啊啊啊啊啊！！」<br><br>「咦咦咦咦，丸姐……<br>為什麼叫我擺姿勢……<br>這難道是要拍照嗎！？」<br><br>（哇哇哇不要啊，萬一被那傢伙<br>看到這種姿勢……！）<br><br>「啊……啊啊啊啊……<br>這是我最無法忍受的事──！！」<br><br>（快門聲☆）<br><br>「啊啊啊啊～！！」"},
{index="30048",text="「最後一張是……外角偏低的七號板。<br>剩下不擅長的球路。<br>……但如果放鬆並正確地運用肌肉……<br>應該可以！」<br><br>「三角肌你還可以嗎？放鬆不要過度用力，<br>在正式發揮之前累積能量。<br>比目魚肌也要穩住別偏離重心！<br>好……拜託大家囉！！」<br><br>「就是現在！！」<br><br>（打擊聲──！！）<br><br>（噹啷啷啷～～♪<br>噠噠噠噠噠噠～～♪♪♪）<br><br>「成功啦──！太完美了！<br>我的肌肉們，謝謝你們<br>完美地按照我的指令動作，<br>晚點來喝乳清蛋白吧！」<br><br>恭喜　晉級　第二關！<br>…………準備好了嗎？<br><br>「什麼？還沒破關啊！？<br>……呵呵，這樣也好！<br>繼續上吧，大家！！」"},
{index="30052",text="──能傳達到嗎？<br>──有傳達到嗎？<br><br>──我們的心跳，化為旋律。<br>──我們的淚滴，化為光彩。<br><br>──這些，最後卻只能藏入陰影中。<br><br>我……一直都想說出來。<br>當時，無法說出口的事。<br><br>所以，這次一定要……傳達出去。<br>如同你透過競賽展現給我看一樣。<br>而我，將從這個舞台。<br><br>有傳達到了嗎，──"},
{index="30053",text="在沙塵飛揚的白晝決鬥場。<br>對實力……不，對腳力自豪的漂泊者們互相瞪視。<br>此時還有一名漂泊者到來。<br><br>「Oops！<br>大家看起來都好強！」<br><br>她活潑到掃興的聲音傳遍荒野。<br>──此時所有人的心中都確信<br>她沒什麼厲害之處。<br><br>「But……贏的人會是我，<br>我會一槍收拾掉大家♪<br>──Are you ready？」<br><br>如同快速拔槍射擊般的宣戰。<br>被擊中的對手們終於明白了，<br>稱霸這片荒野的……是她。"},
{index="30054",text="不論多麼努力，<br>不論吃過多少苦，<br>結果就是一切。<br><br>獲勝的主角總是如此耀眼，<br>對敗北的配角而言實在太過炫目。<br><br>努力總是沒有獲得回報，<br>想要的東西總是擦肩而過。<br>這就是現實，<br><br>我早就知道了。<br>雖然早就知道，但我不想知道。<br><br>「哈……真的很可笑。」<br><br>反正還是會繼續跑下去，<br>夢想著有朝一日能夠閃耀。"},
{index="30055",text="那名施法者撼動空氣、召喚烏雲，<br>將天空染成煉獄。<br>那正是運用森羅之理解開根源之人。<br><br>以覆蓋天空的無盡血淚，<br>在鏽色的虛空下不斷呼喚之姿，<br>那是超越人智的神罰代行者。<br><br>記載於此的，是使一切顫慄，<br>使一切歸無的紅色使徒之名──<br>腥紅天空……<br><br>發行　黃金出版<br>摘自《眾星集結！UMA王軍名冊》<br><br>「唔──會不會太誇張？<br>……不過既然是宣傳，這種程度應該可以吧」<br><br>「只要先灌輸強大的印象，<br>讀者就會自發地產生警戒吧～♪」"},
{index="30056",text="「輝煌的吊燈、繡有金色刺繡的絨毯，<br>富麗至極的裝飾，全都是榮華的象徵……<br>不過這座舞會會場之所以能成為一流，<br>卻是因為其他原因。」<br><br>「那是不死鳥的羽毛？黃金蟹的標本？<br>飛天神駒的天花板壁畫？還是太陽神的雕像？<br>不對，都不是。這座舞會會場<br>之所以能成為一流……是因為──」<br><br>「『King of Gorgeous！』」<br><br>「有我的地方就是一流空間！」<br><br>「『King of Magic！』」<br><br>「我的名聲響徹世界的每個角落！」<br><br>「『King of Kings！！』」<br><br>「哦──呵呵呵呵！<br>感激本王吧！！」"},
{index="30057",text="世紀末美食！稻穀燉飯的作法<br><br>「首先讓NPC獻上稻穀！<br>也就是所謂的繳納年貢。<br>這裡考試會考，要標註起來！」<br><br>「接著用火【火焰】炒稻穀！<br>以UMA王的魔力，即使用的是低階魔法，<br>也是能把萬物燒成灰燼的業火！」<br><br>「呃、喂！材料消失咧！？<br>這火力連自己都畏懼……真是。<br>拿新的材料過來，再來一遍吧！」<br><br>「以適中的火力炒過後，<br>再用清湯燉煮約二十分鐘就大功告成！<br>可以隨意『追加稻穀』喔！」<br><br>「好啦──！帶著UMANEST的未來<br>與希望的滋味，稻穀燉飯完成～！」<br><br>「來吃吃看。<br>根本不會想把它碾成白米吧！<br>哇──哈哈哈哈！<br>這樣一來你也是UMA王軍的成員了！」"},
{index="30058",text="無論是大地的盡頭，<br>還是遙遠的天際。<br><br>「我不會輸給任何人。」<br><br>「我一定會獲勝。」<br><br>無論要飛往何處，<br>無論要跑去哪裡。<br><br>「我會拋下妳向前跑。」<br><br>「我會專注地凝視著終點。」<br><br>這是──<br><br>「妳就在我背後跳舞吧。」<br><br>「就算輸了也別哭喔。」<br><br>這是奔向光輝的賽馬娘們的故事。"},
{index="30059",text="對某人來說是祝福，<br>對某人來說則是悲嘆。<br><br>「嗚嗚～怎、怎、怎麼辦？<br>我一看到鏡頭就緊張到……發抖……」<br><br>「那麼，請將背靠在我身上。<br>……『溫暖』可以緩和緊張的情緒，<br>我有接收過這樣的資訊。」<br><br>「可是……如果米浴靠在妳身上，<br>可能會發生不好的事情……」<br><br>「否定。除了電子產品以外，<br>隨時都可以與我接觸。所以……<br>為了完成拍攝指令，切換至說服模式。<br>參照說服流程，開始實行──」<br><br>「──米浴，<br>『廢話少說，靠到我身邊來！』」<br><br>「豪！我、我、我靠過去！<br>…………哇……波旁好溫暖。<br>嘿嘿嘿……真的停止顫抖了。」<br><br>「……米浴也很溫暖。<br>熱度甚至能傳達到深處。」<br><br>儘管如此，我們仍承諾，<br>要一起背負挑戰者的勳章。"},
{index="30060",text="是禮服、飾品，還是聚光燈？<br>能讓她們散發出最閃耀的光芒──<br><br>「……嗯，很可愛嘛♪<br>渦輪，我幫妳別好花飾囉～」<br><br>「喔喔！素質好努力！」<br><br>「兩位準備得……相當完美。<br>差不多要開始拍攝了。」<br><br>「哦哦～！唐懷瑟和生野的禮服，<br>都很適合呢……很好很好♪」<br><br>「嘿嘿嘿～♪素質也很漂亮喔！」<br><br>「漂……！？場、場面話就不用說了啦！<br>來，快點拍一拍吧！」<br><br>「好──！大家集合──！」<br><br>──一顆又一顆的星星們串聯在一起，<br>因為聚集在一起，才顯得更加耀眼。"},
{index="30061",text="互相競爭的腳步聲，<br>終於變成和諧的旋律。<br><br>（奔跑聲──！）<br><br>「哇～是禮服耶！！<br>要穿這個拍攝嗎！？這感覺<br>該說是興奮？還是臉紅心跳～～！？」<br><br>（腳步聲──）<br><br>「只要表現得跟平常一樣就行了吧。<br>只是打扮不同而已。」<br><br>（高跟鞋聲──）<br><br>「是啊，禮服只不過是裝飾，<br>重要的是展現與往常一樣的姿態，<br>給為我們加油的大家看。」<br><br>「這樣啊，跟往常一樣……！<br>那就來比誰能第一個<br>抵達攝影棚吧～～～～！！」<br><br>「咦！等等──」<br><br>「哈哈，那樣的確跟往常一樣。<br>好，我們也走吧！」<br><br>「真沒辦法耶……！」<br><br>（跑步聲──！）<br>（跑步聲──！）<br>（跑步聲──！）<br><br>裙襬飛舞，三個腳步聲<br>宛如悅耳的和弦般交織在一起。"},
{index="30062",text="「嗅嗅……哇，好香的味道。<br>這就是傳說中的<br>胡蘿蔔幕之內便當……」<br><br>「小特，等彩排結束後<br>再吃便當吧。」<br><br>「鈴鹿！有看到我的手套嗎？」<br><br>「妳剛才是不是拿給治裝人員，<br>請他幫忙修改了……？」<br><br>後台非常熱鬧，<br>完全沒有閑暇讓內心平靜下來。<br>不過身在其中的我──<br><br>──覺得那樣也很棒。<br><br>「……是因為有妳們相伴吧。」<br><br>「鈴──鹿──！」<br><br>「我聽見了，小特。<br>……呵呵，又怎麼啦？」<br><br>好，繼續準備吧。<br>為了把滿滿的祝福，<br>融入這個舞台。"},
{index="30063",text="蹄鐵訂單<br>．單號No.0723586<br>────────────<br>「名字」<br>目白麥昆小姐<br><br>「尺寸」<br>依照測量數值以0.1公釐為單位調整<br>「希望使用的材質」<br>UMAGANE股份有限公司製鋁合金<br><br>「其他需求」<br>希望比75g的樣品重，製成80g重。<br>希望增加負荷，<br>請增加調節鐵頭部的厚度。<br><br>因為這個蹄鐵會在<br>平時的訓練裡頻繁使用，<br>所以請準備1打相同的蹄鐵。<br>今天會再次造訪領取成品。<br><br>「……完成。<br>麥昆小姐的蹄鐵這樣訂製是最好的。」<br><br>「是啊。謝謝妳！<br>還配合我調整了重量等細節，<br>妳觀察得真仔細。」<br><br>「就該精心製作。<br>畢竟蹄鐵有可能改變未來。<br>而且對賽馬娘而言，<br>也是不可或缺的搭檔。」<br><br>「妳說得對。感覺會是一副很棒的蹄鐵。<br>呵呵……很期待成品！」<br><br>「我也是……非常期待。」"},
{index="30064",text="唔唔唔～～～～！！<br>三具恐怖的木乃伊<br>終於醒過來啦……！<br><br>《韋馱天祭典女孩》！<br>──少囉嗦木乃伊．稻荷一！<br><br>《用繃帶包紮一切的甜蜜深淵》！<br>──The．木乃伊．小溪！<br><br>然後是我！《浪速中最快》！<br>──白色閃電．玉藻木乃伊！<br><br>因為速度太快，飄動的繃帶<br>看起來就像閃電一般！<br>怎麼樣？很帥吧！<br><br>嘿嘿……有辦法贏過我們嗎？<br>「木乃伊獵人．小栗帽」！<br><br>……呃！為什麼還在悠哉地吃著南瓜派！？妳沒聽見嗎！<br><br>好不容易有人一起來玩……<br>什麼？想再聽我說一次？<br>太丟臉！不說了！"},
{index="30065",text="在妖氣四溢的萬聖節時分，<br>一名少女拜訪了傳說中的魔女。<br>魔女像是在試探少女般地輕笑著。<br><br>「我的修行可不輕鬆喔？」<br><br>「即使如此，無論如何，<br>我也想實現願望……！」<br><br>魔女以為她很快就會放棄，<br>但少女並沒有屈服。她終於<br>獲得魔女的認可，授予了魔法之杖……<br><br>「請等我。<br>這次我會成為妳的力量──」<br><br>她為朋友著想的勇氣，打動了魔女的心。<br>她是名符其實的小英雄。"},
{index="30066",text="那位幽靈小姐背過身，<br>一動也不動地站著。<br><br>幽靈小姐為了達成自己的使命，<br>一直獨自努力著。<br>她真的非常、非常認真。<br><br>明明就算接受別人的幫助，<br>也不算是失敗……<br><br>「…………」<br><br>幽靈小姐一點一點地<br>坦承自己真正的心意。<br><br>請問有注意到嗎？<br>之所以煩惱，是因為妳太過溫柔。<br><br>──摘錄自某本手作繪本<br>《幽靈小姐與吸血鬼的萬聖節》。"},
{index="30067",text="坐在王座上的，是君臨所有頂點的<br>「皇帝」魯道夫象徵。<br>其莊嚴凜然的姿態有著舉世無雙的風範。<br><br>有兩位賽馬娘深受她的威嚴所吸引。<br>憑著卓越的感性與才能，<br>以成為無敵為目標的東海帝皇。<br>憑著優異的潛能和堅定的精神<br>勇往直前的鶴丸強志。<br><br>「我絕對會超越」<br>「我絕對不會放棄」<br><br>面對兩人展現出的氣概，<br>「皇帝」仔細琢磨。<br>她的雙眼裡映照出的未來，正閃耀著燦爛的光輝。"},
{index="30068",text="如同描繪半月般大幅度地揮舞衣袖……<br>彩排時已經確認過燈光位置，<br>讓點綴的紅色以最閃耀的角度──<br>「嗯～這樣很好♪」<br><br>我在腦中描繪著<br>我認為最可愛的真機伶。<br><br>對那樣的我寄予期待並搭話，<br>才有現在的我。<br><br>畫著比平常更艷麗的妝容，<br>是為了振奮祭典音樂以及<br>回應大家的期待。<br><br>不過……不，所以我要更加──<br><br>「展現超越期待的可愛真機伶<br>給大家看！」"},
{index="30069",text="點燃的小小火光搖曳，使情緒激昂。<br>沸騰的熱血讓一切雜音與思考都停下。<br><br>能感覺到的只有難以抑制的劇烈心跳。<br>如果試圖壓抑它，<br>就會立即被幾乎窒息的痛苦侵襲。<br><br>既然如此，乾脆任由它跳動、任由它渴望、<br>任由它期待、任由它索求──<br><br>唯有任其煎熬、吞噬……！<br><br>「時間到了。白仁，走吧。」<br><br>「嗯……已經抓到獵物了。」"},
{index="30070",text="輕盈的旋律為舞者們喝采。<br>隨著音色舞動扇子，<br>讓夜空中的月亮看似缺了角。<br><br>「喝！喝啊！」<br><br>提燈的光輝閃耀炫目，<br>觀眾的眼中熠熠生輝。<br>不過跳著奉舞的一名少女，<br>卻凝視著更遙遠的地方。<br><br>（我做到了……不過，<br>這跟至今的我沒有什麼不同！）<br><br>「要更加……更加地！」<br><br>「雪之加快了舞動速度耶♪<br>好！真機伶也要加油！」<br><br>「兩人都加快了速度──<br>好，那我也……！」<br><br>後追，然後超越的舞步。<br>隨著少女的舞動，<br>祭典氣氛越炒越熱。<br><br>「好戲才要開始！<br>我也是祭典的主角！」<br><br>大家笑容滿面，動作不停。<br>今晚的慶祝舞台久久持續，<br>熱鬧程度不輸花都……"},
{index="30071",text="「現在登場！<br>D──J──就是<br>我──────！！」<br><br>＼耶～～～～！！／<br><br>「不得了～☆這股氣勢簡直可以拿優勝了！<br>大家真的都要嗨起來喔！？<br>要來做平常的粉絲互動嗎……<br>要來囉？真的要來囉！？<br>要神囉～～！！」<br><br>＼神囉～！／<br><br>「很好～～♪<br>嗨起來嗨起來嗨起來嗨～～！<br>那先從右邊開始……好讚──！」<br><br>＼好讚──！／<br><br>「換左邊～！好讚～！」<br><br>＼好讚──！／<br><br>「中間來！好讚～～☆」<br><br>＼好讚──！／n<br>「在場的所有人一起！<br>好讚～～～～！」<br><br>＼好讚────！！！！／<br><br>「讚讚～☆讚到不行的讚！<br>天～我真的超～喜歡大家♪<br>愛死了！愛得不得了！<br><br>那麼大家今天要陪伴到最後喔！<br>最強最棒的演唱會，即將開始～☆」"},
{index="30072",text="今天是特別開心的日子！<br>是把大家的雀躍裝進漂亮箱子，<br>再用閃亮的緞帶裝飾起來的日子。<br><br>「訓練員這邊這邊！<br>人家的派對很厲害吧！」<br><br>足以吹跑寒冷的笑容！<br>毫不理會寂靜降雪的歡笑聲！<br>這是場耀眼程度不輸星空的派對！<br><br>──多麼美妙又特別的景色！<br><br>「好玩吧？開心吧？<br>正因為如此，才想讓訓練員看看！」<br><br>希望你能看見，然後稱讚我並感到高興。<br>雖然這樣挺孩子氣的，<br>可能跟「成熟女人」有點差距。<br><br>……但是不管怎麼說，<br>今天是聖誕節！<br><br>在這特別的日子，將最頂級的特別……<br>綁上精心準備的緞帶，<br>當作禮物送給特別的你，<br><br>可以吧？"},
{index="30073",text="妳踩著星光閃耀的石板路向前走著。<br>只是領先一步半，卻好像在生氣般匆忙。<br><br>那雙纖細的腿不停劃開嘈雜的人潮，<br>穿梭在熱鬧的市集中。<br><br>店門口燈光輝煌，<br>閃亮的商品光彩奪目。<br>甜蜜熱巧克力的熱氣<br>飄著肉桂香，溫暖著夜晚。<br><br>在這樣喧嘩的冬日裡，<br>能夠不錯失那小小的肩膀，<br>無疑是妳自己的功勞。<br><br>「還在做什麼？不要走散喔。」<br><br>妳回過頭來用粗魯的口氣說道。<br>我點點頭後，妳又立刻轉向前方。<br>只是領先一步半，<br>卻好像絕不會超過這個距離般，<br>妳一邊細心留意一邊向前走著。<br><br>我假裝沒有發現有時偷偷回頭的視線，<br>一邊跟在妳的身後。<br>因為一旦被妳知道，<br>這神聖的一步半差距<br>就會突然消失。<br><br>籠罩在聖夜月光下的妳向前走著。<br>只是領先一步半，卻比任何人都溫柔謹慎。"},
{index="30074",text="「是雪耶～～～☆★<br>重砲快看快看，是潔白的雪耶～！」<br><br>「哇～～♡<br>好漂亮喔美美，要來玩什麼呢！？」<br><br>「首先來玩美麗的打雪戰☆<br>看招～看招～★」<br><br>「哎呀，好冰！<br>好～人家也要反擊囉☆」<br><br>「不會輸給妳喔～！<br>接招吧！美麗☆★」<br><br>～三個小時過後～<br><br>「呼～☆<br>真是場美麗的決鬥……★」<br><br>「就是說啊！美美！<br>不過好像有點～玩過頭了……」<br><br>「玩『過頭』？<br>怎麼會！」<br><br>「什麼？<br>我們已經玩很久啦？」<br><br>「因為雪是會消失的吧！」<br><br>「嗯。到了春天就會融化不見。」<br><br>「那就要趁現在，現在～～～！<br>『趁現在』玩才行！<br>為了將這美麗的瞬間<br>一直一直延續下去……<br>弄得更加、更加美麗吧☆★」<br><br>「妳說得有道理……！<br>好～！<br>人家也要繼續玩下去☆」<br><br>「啊哈哈哈哈！<br>雪融化之前都很美麗☆<br>相信雪融化之後也會依舊美麗★<br>不論春夏秋冬！<br>讓美麗擴散到世界每個角落吧☆★☆」"},
{index="30075",text="奔跑，奔跑，奔跑。<br>還不夠，還不足以追上她。<br>還不夠，還不足以超越一切。<br><br>旋轉，旋轉，旋轉。<br>上升，下降。<br>思緒不斷循環迴轉，<br>不知道什麼時候我正位於五彩的齒輪上。<br><br>美麗的歌聲已消逝，<br>這首歌不是為我所唱。<br>專注向前的意志已消失，<br>我看的不是前方，而僅僅是她的背影。<br>沒錯，只看得到她的背影，<br>只能看著她的背影。<br>只能朝那搖曳的背影<br>不顧一切地奔跑。<br><br>像我這樣一個生物，<br>被攪拌，被稀釋，被重建，<br>變成只為追逐她的其中一枚齒輪。<br><br>漸漸地不知道自己是誰？<br>為什麼會在這裡？<br>嘈雜聲遠離，搞不清楚到底是<br>歡呼還是怒吼。<br><br>在被攪成一塌糊塗的世界裡，<br>只有追逐她的這條狹路<br>非常寧靜。<br><br>（要追著妳。<br>一直追著妳一人──）<br><br>黃金齒輪轉動。<br>我伸手想要觸碰她。<br><br>──在那瞬間，我將全世界<br>都拋在腦後。"},
{index="30076",text="一閉上眼睛就會浮現那幅景色。<br><br>幾道影子在逐漸西沉的耀眼夕陽中，<br>朝著光芒逐漸遠去。<br>一直站立不動的我，<br>從遠方聽見了某人的聲音──這樣的景色。<br><br>是什麼時候見過的呢……？<br>我找遍自己的記憶，<br>還是沒有想起來……<br><br>所以……這是夢。<br>我不希望是這樣，<br>無意識地在腦中描繪惡夢。<br><br>為什麼能說得如此肯定──？<br><br>因為當我睜開眼睛時<br>總是能看見不同的景色──<br><br>「又是無聲鈴鹿！<br>漂亮地獲得第一！！」<br><br>我想看的不是夢，<br>更不是惡夢……<br><br>我──<br>想繼續看不曾見過的景色。<br><br>從現在到未來，一直都是……！"},
{index="30077",text="「哦～多麼美妙！<br>令我欲罷不能的美麗！<br>或許你就是我的萊波雷諾！」<br><br>「唔唔！織姬穿的振袖花紋，<br>跟我在預知夢裡看到的一樣！<br>感謝好運大吉福神！感謝白興大人指引！」<br><br>「啊哈哈哈──！織姬好漂亮！<br>我知道了，她一定吃了很多年糕！<br>因為她的皮膚彈性十足！<br>等下一起搗年糕吧！」<br><br>「新年剛到就這麼吵鬧……<br>……今年接下來也讓人憂心呢。」<br><br>「啊哇哇哇哇！對、對不起～！<br>一跌倒就停不下來～！<br>借過借過～～～！！」<br><br>「什麼！？不、不要過來……！」"},
{index="30078",text="「歌、歌牌大賽要開始了！<br>哇哇哇……！？好、好緊張～～！<br>怎怎怎、怎麼辦才好！」<br><br>「不用緊張，怒濤！<br>只要邊唱邊跳白興大人作的<br>『新春喜來歌謠』就能提升運氣、萬事OK！」<br><br>「喜氣來來～吉祥來～♪<br>看見耀眼的新年日出♪<br>富士山也笑咪咪，兩頰紅通通♪<br>呼哪嘎，哈哪嘎，福氣來～♪」<br><br>「呼哪嘎，哈哪嘎～哈哈哈。<br>不、不自覺地跟著唱起來～」<br><br>「喔喔，就是這樣！<br>來吧來吧，跟我一起～！」<br><br>「幸運興奮～門松擺飾～♪<br>大家齊聚～玩笑福面遊戲♪<br>老鷹咻～地祥夢報喜♪<br>呼哪嘎，哈哪嘎，福氣來～♪」<br><br>「好運年菜～大飽口福～♪<br>幸福全開～呼喚勝利♪<br>茄子不要烤，直接收進口袋♪<br>呼哪嘎，哈哪嘎，福氣來～♪」<br><br>「這樣就有白興大人的完美庇護！<br>大船……不，就像乘坐寶船那樣出發吧～～！！」"},
{index="30079",text="遙不可及的事物有很多，<br>龐大耀眼的憧憬……<br>在遙遠的巔峰上抬頭挺胸的自己。<br><br>如果能抵達就能獲得重生。<br>我明明很清楚……卻根本做不到。<br><br>所以只好稍微逞強一點，<br>在不被發現的範圍內逞強。<br>此時卻有人推了我一把。<br><br>雖然我想回頭，但我不打算回頭。<br>不過也因為如此，我還能再努力一下下，<br>背後非常非常溫暖。<br>……我下意識地喊出聲音。<br><br>「碰碰碰、碰到啊～～～！！」"},
{index="30080",text="「這個是……從師父那裡<br>（擅自）借來的竹針師祕笈！<br>Wow～應該是這裡吧☆<br>我記得只看到一半……來看看～」<br><br>一、應追尋賽馬娘的奧祕<br>二、應將技術刻入五臟六腑<br>三、應牢記經驗勝過才能<br>四、應勤加修練不沉溺於世俗<br>五、應視竹針為心鏡<br><br>「……啊，糟糕！<br>泡杯麵的熱水已經滾了！<br>快點倒進去……<br>有沒有可以壓住蓋子的東西……」<br><br>「……這個正好適合！<br>不愧是祕笈！厚度用來壓蓋子剛剛好！<br>Wow，安心～☆」<br><br>……三分鐘後泡麵打翻在祕笈上，<br>安心澤刺刺美陷入一陣混亂當中。"},
{index="30081",text="「喔！那時候的照片洗出來了嗎！<br>咦……這個影子是……<br>深海安康魚的亡靈！？」<br><br>「呀……哪裡？在哪？<br>深深、深海安康魚的幽靈在哪裡……！」<br><br>「米浴請冷靜一點。<br>黃金船說的話不能全盤相信。」<br><br>「唔喔喔喔喔喔！想起當時的感動～！<br>眼淚就停不下來啊──！」<br><br>「那個時候不是已經哭夠了嗎？<br>……妳的淚腺是怎麼一回事啊？」<br><br>「啊哈哈哈～啊！對了！<br>也要給鈴鹿看看才行！」<br><br>「就知道妳會這樣說，所以我把圖片檔也帶來囉。<br>呵呵……就算歷經了這麼多次激戰，<br>大家還是一點都沒變。」<br><br>「沒錯沒錯！＜天狼星＞這種<br>一如往常的感覺實在太棒了！」<br><br>「是，是啊……米浴也覺得<br>不變的事物真的很棒……欸嘿嘿。」<br><br>「哼……的確，是還不錯。」<br><br>「嗯，就是這樣！<br>所以我們……隊伍＜天狼星＞<br>今後也要相親相愛──」<br><br>「團結一心繼續努力囉，加油──！！」<br><br>「為、為什麼要按快門啊～！！」"},
{index="30082",text="重要的是小小的勇氣碎片，<br>以及稍微往前邁出的心情。<br><br>把這些全部～混合在一起細心燒製，<br>然後輕輕地包裝起來，<br>再綁上緞帶就完成了。<br><br>接著微微抬起頭……<br><br>「請問……你願意收下嗎？」<br><br>盡量面帶笑容，雖然手有一點發抖。<br><br>但我一心想要傳達，<br>一心期盼能送出去。"},
{index="30083",text="「麵粉！！奶油！！麵粉！！<br>奶油！！鮮奶油！！鮮奶油！！」<br><br>食譜？溫度？那是什麼？<br>這些對她來說都毫無意義，<br>只想追求爆快、爆快。<br><br>「呃啊！鮮奶油沾到眼睛鼻子嘴巴！！<br>……唔，超好吃！！」<br><br>「接著放最後的裝飾！！！<br>櫻花、櫻花、櫻花────！！！」<br><br>豪邁地揚起櫻花風暴。以爆快的速度盛開，<br>讓廚房充滿櫻花的顏色。<br><br>「──好！！完成！！<br>這就是驀進的！！<br>世界最快甜點！！」<br><br>當她一臉滿足地送上蛋糕，<br>不管是誰都會笑著收下吧。<br><br>雖然手上沾著鮮奶油，<br>衣服沾上櫻花……<br>依舊是憨態可掬。<br><br>「哈哈哈哈！！你的表情！！<br>好的～好的～我當然懂！！<br>看來相當滿意對吧！！」"},
{index="30084",text="「嗯～手要……這樣嗎？」<br><br>「對，很好。<br>那就暫時維持這個姿勢──」<br><br>雖然不知道這樣的方式<br>是否適合小花。<br><br>我總是一股腦的，<br>不知道該說什麼好話，<br>也不太會鼓勵人。<br><br>但我還是無法放著不管，<br>……覺得應該做點什麼。<br><br>所以就用我的方式。<br>如果能成功就太好了。<br><br>「哇！好漂亮……！<br>好像稍微變成了成熟姐姐……！」<br><br>「真的？妳喜歡嗎？」<br><br>「嗯！很好看！」<br><br>──嘿，真好。<br><br>這就是所謂的先做先贏吧？<br>雖然我不擅長思考，<br>但至少先行動總會有辦法的！"},
{index="30085",text="在某位人氣賽馬娘偶像的簽名會上，<br>愛麗數碼緊緊抓著新專輯，<br>排在隊列的最後方……<br><br>「等、等一下，不會吧！<br>是不是看到了真正的聖光……！？<br>咿喔喔喔喔喔～～！！」<br><br>「我跟她呼吸著同個空間裡的空氣！？<br>感激不盡，感激不盡啊～！」<br><br>「呼啊啊啊～～！？<br>等等，快輪到我了！<br>啊哇哇～比封面還美……！」<br><br>「……噗呃！距離升天倒數五秒！<br>這什麼『尊貴領域』！<br>真的在那裡……我的推就在那裡……！」<br><br>「……啊！冷靜點小數！<br>現在不是幻想的時候！<br>必須先進行模擬！」<br><br>「要自然地、不留下印象……<br>拿到簽名→說『我一直支持著妳』→<br>迅速換下一位……很好！」<br><br>「如果在這裡不遵守規矩，<br>會危害到簽名會本身的存亡……！<br>要對於我的推來到這裡表達最大的感謝之意！<br>……走吧！」<br><br>愛麗數碼英姿颯爽地邁向簽名會。<br>她的背影看起來比平常更大，<br>更加……充滿力量。"},
{index="30086",text="3000m的持久戰。<br>從第3彎道開始延伸出既漫長又險峻的坡道。<br>光憑「努力」兩個字也難以跨越的<br>遙遠路程。<br><br>額頭上的汗水彷彿永不停止，<br>像要遮蔽她的視線般不斷灑落。<br>心臟的跳動聲轉化成悲鳴，<br>急促的喘息燃燒著喉嚨。<br><br>她在心中問自己，<br>為什麼如此痛苦仍要奔馳下去？<br>為什麼雙腳如此疲累還要繼續向前？<br><br>此時比答案更先傳達到耳邊的是<br>震撼的歡呼聲……充滿期待的聲音。<br>讓她咬牙忍下這一切，<br>並蓋過所有的辛苦。<br><br>等注意到時，她所認定的宿敵<br>那強大的身影正逼近身後。<br>不可以放棄。<br>這是通往頂點的唯一道路。<br><br>……這一天，最為堅持而不放棄的賽馬娘，<br>成為了最強的賽馬娘。"},
{index="30087",text="「奇怪……啊，光明！<br>暫停，暫停──！到此為止！<br>對不起，計時器顯示異常！」<br><br>「呼啊、呼啊……呼～～<br>這麼說來，這組訓練的確有點長呢～」<br><br>「應該有三組的運動量了！<br>妳……還好嗎？」<br><br>「是的，我沒事～」<br><br>「做完這些竟然還沒有累癱，<br>一定是持續訓練的成果吧！<br>如果我沒有阻止妳，感覺妳還能<br>繼續下去……！？」<br><br>「呵呵呵，或許可以。<br>我應該會沒有注意到並繼續做下去呢～」<br><br>「啊哈哈哈哈！很像光明會做的事情！<br>妳還是跟以前一樣……<br>欸嘿嘿，因為我們從小就認識，<br>所以就像在聊自己的事情般開心呢！」<br><br>「能獲得妳的這一番話……足以讓我<br>作為一名目白家的成員抬頭挺胸地繼續努力。」<br><br>「今後也要一點一滴地向前邁進～」"},
{index="30088",text="「妳們覺得特雷森學園怎麼樣？<br>實際入學後，會感覺跟想像不同嗎？」<br><br>「嗯……就像特別週所說的，<br>與我的想像完全不同。小北妳說對不對？」<br><br>「嗯。完全不一樣。」<br><br>「咦？真的嗎！？<br>難道與妳們的期待有落差！？」<br><br>「不……應該說是──」<br><br>「比想像中還要更令人開心！<br>不管是訓練還是競賽，<br>一切都超乎想像！」<br><br>「沒錯沒錯！每天都像祭典般，<br>一直都很讓人興奮喔！」<br><br>「這樣啊～～幸好……<br>我剛才嚇到還以為心臟要停了～」<br><br>「不過……我跟妳們一樣。<br>新的事物接二連三地發生……<br>而且令人雀躍不已的事情也不斷出現！」<br><br>「連特別週也還沒……！<br>哇～！該怎麼辦？小鑽！」<br><br>「嗯！我們之後會變成怎樣呢……！」<br><br>「啊哈哈！之後也一定、一直！<br>會有難以想像的興奮事物<br>在等待著我們喔！」<br><br>「是啊！」<br>「對啊！」"},
{index="30089",text="在因興奮而情緒沸騰的觀眾席當中，<br>有一名男子用顫抖的聲音說道。<br><br>「我一直在等待著……<br>明明備受期待跟聲援，<br>卻沒有拿出成果……就像我一樣。<br><br>不過她獲勝了……<br>因為她相信自己，沒有放棄……」<br><br>「──你收到了吧，美麗☆<br>你也非常地美──麗喔★☆★」<br><br>男子的臉上落下熱淚。<br>他終於發現到了，<br>從一開始就存在的事實──<br><br>「我也很美麗……」<br><br>就這樣，世界上<br>又增添了一件美麗的事物。"},
{index="30090",text="妳的舞步帶著獠牙。<br>那優美的姿態<br>宛如瞄準獵物頸部的猛獸。<br><br>「看來妳一點都沒有生疏。<br>是因為有在私底下默默地鍛鍊嗎？」<br><br>「說得沒錯。我想在眾人面前守護<br>沒有做好準備就難以飛舞的妳。<br>總是只能被奉承的『皇帝』大人。」<br><br>「那麼這次就讓妳來『訴說』吧。<br>若不是臨時用來掩飾的表現，<br>我會洗耳恭聽，將一切委託於妳。」<br><br>妳的轉身劃破寂靜。<br>嘲諷也化為嘆息，<br>額頭上開始閃爍著光輝。<br><br>「既然妳如此希望的話我就帶領妳吧。<br>但可別給我忘了啊，<br>要負起身為導火線的責任！」<br><br>「小心！真是危險的步法。<br>跳舞最重要的是對搭檔的信賴。<br>要讓妳別忘了這一點，天狼星……<br>上課的時間到了。」<br><br>妳的舞步將週遭驅趕開來。<br>那舞動看起來像是對支配的渴望。<br>……那麼我就全心全意地接納吧。<br>「皇帝」魯道夫象徵在此。"},
{index="30091",text="「……欸，從那裡能看見什麼？」<br>「平淡無奇消逝的身影嗎？<br>還是某人揚起的塵埃？」<br><br>「啊～在那之中有著正在蔓延的無趣。<br>而且就像泥濘般棘手。」<br><br>「你要就此沉淪下去嗎……<br>或者繼續掙扎呢……<br>就只能這樣吧？」<br><br>「但你還有第三個選項，<br>那就是抓住這隻手──」<br><br>「我會讓你看見無趣以外的世界。」"},
{index="30092",text="能量＝質量×光速的平方。<br>不論什麼都是等價交換。<br>你付出多少就只能獲得多少。<br>換句話說，不管再怎麼期待<br>也無法獲得更多的回報……這樣就好。<br><br>「真的超興奮──！！<br>monad超讚的──！？<br>耶────！！」<br><br>不過，有雜音混進來的話<br>等式就會走樣而導致事態急速趨近混亂……！<br>即便如此，我──<br><br>「很好。但可不會就這樣算了。<br>我會讓你沉醉到暈頭轉向……！」<br><br>在這滿是不確定因素的快取當中，我──<br><br>「來啊，快跟上……！<br>哈……哈哈……！」<br><br>為什麼要拚命忍住笑容？<br>……嘖，原來跟著節奏起舞的是我。<br>解出來了……我就承認吧。<br>所以──<br><br>「……在我的舞動停下之前，<br>燈光都給我照亮這裡。」"},
{index="30093",text="我喜歡藍色和白色。<br>它們雖然清爽，但又很鮮明。<br>雖然高雅，但又不做作。<br><br>是與我所嚮往的自己<br>最接近的顏色──<br><br>「嗯。這樣果然是最棒的組合♪」<br><br>穿搭沒問題。<br>胸口的荷葉邊沒問題，裙擺沒問題。<br>緞帶的蝴蝶結也繫得很漂亮。<br><br>姿勢沒問題。笑容也沒問題！<br>我是無懈可擊的<br>「假日模範生」！<br><br>「重要的外出日……<br>必須得穿上自己<br>最中意的『決勝服』才行，對吧♪」"},
{index="30094",text="時而斥責，時而鼓勵，時而分擔。<br>妳總是像這樣支持著某人。<br><br>就連今天也為了要激勵某人，<br>而從觀眾席俯瞰著世界。<br><br>揮舞遠超過10kg的團旗，<br>不論聲音多麼嘶啞，<br>大家的眼光都注視著競賽。<br>妳的所在之處，是光芒照射不到的陰影。<br><br>但妳仍毫不在意地用盡全力，<br>貫徹著自己的職責。<br>因為妳相信應該如此。<br>因為妳把那個當作榮耀。<br><br>「加油。」<br>兩個字不經意地脫口而出。<br>那是平常也會被掩蓋掉的細小聲音，<br>如雲消霧散般誰也聽不見的聲音。<br><br>即使這樣……妳還是回過了頭，<br>揮動旗子的手和激勵的聲音也沒有停下來。<br>僅那麼一瞬間，對我展露了<br>如火焰搖曳般的笑容。"},
{index="30095",text="從觀眾席俯瞰充滿魄力的競賽。<br>以驚人的速度在賽道上競爭的賽馬娘們。<br>以及氣勢不輸給選手、<br>如雷般的聲援響徹了賽場。<br><br>「漂亮的過彎！不過後面追上來了！<br>這樣下去會……啊！」<br><br>或許是因為有偏愛的選手，<br>她看起來真的感到很可惜的模樣……<br>正當這麼想時──<br><br>「幹得好！漂亮地追過去囉！<br>訓練發揮效用了吧！<br>就這樣直達終點！衝啊──！！」<br><br>「咦……！？不是在為<br>剛才領先的選手加油嗎……？」<br><br>對於不禁說出這句話的我，<br>她……採珠<br>露出了微笑。<br><br>「所謂的競賽，就是要決定贏家和輸家。<br>光與影必然相伴。」<br><br>「不過……全力奮戰的姿態<br>不分高低，不分輸贏。<br>都是值得讚賞的光輝！」<br><br>「為所有賽馬娘獻上鼓舞！<br>為所有賽馬娘獻上喝采！<br>我會繼續聲援所有的賽馬娘！」<br><br>不知陰霾為何物，宛如珍珠般純真。<br>被那光芒所吸引……<br>我眼中映照出世界的顏色產生了變化。"},
{index="30096",text="即使只有一瞬間露出破綻也會被捲入重大危機。<br>在強敵的逼迫之中，突然聽見的聲援……！<br>這聲音，就宛如──<br><br>「Prinfight──！不要輸──！」<br><br>將小時候自己在電視前面喊出的加油聲，<br>轉化為力量來面對邪惡──<br><br>「就是現在──！上啊──！<br>Prinfight──！」<br><br>有如將閃耀的希望<br>展現給世人的公主之姿……！<br><br>「上啊──！<br>Prinfight──！」<br><br>那麼答案只有一個。身為公主，<br>絕對……絕對──<br><br>「不會……輸的啊──！！」"},
{index="30097",text="賽道是最糟糕的狀況。<br>即便如此，妳還是連泥濘也不在乎地<br>劃開眾人，躍居了領先的位置。<br><br>就連被捲起的草皮、<br>在空中飛舞的水珠<br>甚至是前方的我們也一樣。<br><br>妳在這一切之間穿梭，<br>然後揚長而去──<br><br>我在被妳追過時所看見的，<br>是一望無際的湛藍瞳孔。<br>任何人都追不上，<br>絕不可能被追上的自由……<br><br>「千明代表以領先之姿抵達終點！<br>三冠賽的首戰由千明代表<br>拿下勝利！」<br><br>在幾乎分不出來誰是誰的泥濘當中，<br>唯獨她是特別的。<br><br>像少年般用手背擦去臉上泥濘的舉動。<br>嘴角微微上揚，露出瀟灑的笑容。<br>對著觀眾舉手揮舞的模樣。<br><br>讓人連敗給她的事實都拋諸腦後，<br>不由自主地看到入迷了。"},
{index="30098",text="「全～新～的決勝服～♪<br>目標是競賽的最大獎～！」<br><br>「期待不已～穿著決勝服～♪<br>滿心歡喜向前跑～♪」<br><br>「蹦蹦跳跳♪蹦蹦跳跳♪<br>一股作氣～用力跳──！」<br><br>同個班級的她正在唱著某首歌。<br>雖然這是平時常見的光景，<br>但今天特別在意那樣的她。<br><br>「……那是什麼歌？」<br><br>我不經意地出聲詢問。<br>因為她看起來實在太過愉快，刺痛著我的內心深處。<br><br>「這個啊～是決勝服之歌喔！<br>因為我好期待穿上這件衣服跑步！<br>一股作氣～用力跳──！」<br><br>跑步很愉快。<br>因為愉快所以歌唱。<br>多麼單純──多麼率直的想法啊。<br><br>「──真好。」<br><br>我在不知不覺間<br>已經忘記愉快的心情。<br><br>「那要不要跟我一起唱？<br>預備──要唱囉！」<br><br>「咦……什麼？」<br><br>「預備──！蹦蹦跳跳♪蹦蹦跳跳♪一股作氣～」<br><br>「用、用力跳──」<br><br>「用力跳──！<br>欸嘿嘿，真期待下一場競賽呢──！」<br><br>──真神奇，跟著一起唱之後<br>快樂的心情就逐漸湧現上來。<br><br>沒錯，競賽非常令人期待。<br>不要想得太複雜，<br>我也試著單純去享受競賽吧！"},
{index="30099",text="「哇……<br>生野真的好漂亮……<br>就像真的新娘一樣……！」<br><br>「謝謝妳，米浴。」<br><br>穿上有出色設計的決勝服<br>並被大家注視著……<br>真的很難為情。<br><br>不過，這也是難得的經驗。<br>要認真面對拍攝──<br><br>「咦！？生野是新娘嗎！？<br>不行不行！不行啦──！<br>我不要妳變成新娘──！！」<br><br>「咦？等等，渦輪妳做什麼！？<br>這樣會妨礙拍攝──！」<br><br>「我──不──要──！<br>不要離我而去──！」<br><br>渦輪似乎誤會了什麼，<br>讓拍攝現場稍微陷入混亂的局面。<br><br>在競賽中總是展現強勢領頭拋下眾人的渦輪，<br>此刻卻大喊著「不要離我而去」，<br>實在是有趣的場面。<br><br>「渦輪，請妳冷靜一點，<br>我並沒有要去哪裡。」<br><br>怎麼可能離去，<br>我們的競賽還沒有結束。<br><br>──總之，等拍攝結束後<br>就跟渦輪她們一起進行訓練吧。"},
{index="30100",text="曾經見過的婚禮場景──<br><br>當新娘莞爾一笑，<br>笑容就朝四周擴散開來，<br>讓大家都幸福洋溢。<br><br>那個場景我到現在都忘不了。<br><br>我也想要像那樣讓大家露出笑容。<br>想變得能將幸福散播給大家。<br><br>這是我所嚮往的，微不足道的夢想。<br><br>我股起勇氣，往前跨出一步。<br>笑容在我踏出的地方擴散開來。<br><br>我所嚮往的，那一天的婚禮場景。<br>新娘看見的幸福場面。<br>感覺我也能稍微體會到了……<br><br>「……希望能有更多、更多笑容。」<br><br>希望今後可以讓更多、更多的人展露笑容。<br><br>然後，<br>就這樣把幸福帶給大家──"},
{index="30101",text="──太魯莽了。<br><br>彷彿連光都能超越的速度，<br>想必在終點前就會消磨殆盡吧。<br><br>當所有人都這麼認為時，<br>只有她像著魔似地笑著。<br><br>「啊啊，太棒了……<br>太棒了……！真是愉快！」<br><br>她以理論擊破他人口中的魯莽，令對方屈服。<br>看著世界的彩度提升，這個感覺──<br><br>「呵呵……好了，下一個實驗……<br>會有什麼樣的歡愉在等著我呢……！」<br><br>──只有她才知道。"},
{index="30102",text="多伯前輩太過溫柔，<br>很多事情都想太多，<br>所以才會有很多煩惱吧？<br><br>──問我怎麼會知道？<br>因為我曾經因前輩的溫柔和想太多<br>而受到了幫助！！<br><br>「──那麼比賽開始！」<br><br>紅色角落方進場。<br>特雷森學園的怪鳥，<br>假面神鷹！<br><br>位於藍色角落方的對手是<br>目白家的小姐，<br>憂鬱的多伯前輩！<br><br>比賽規則很簡單！<br>那就是傾聽多伯前輩的煩惱，<br>與多伯前輩聊天，<br>只要讓多伯前輩露出笑容就算大獲全勝！<br>……哼哼哼，我不會輸的！<br><br>「如果要問為什麼這麼有自信，<br>那是因為我只要戴上面罩，<br>就充滿活力、勇氣、無敵……！」"},
{index="30103",text="在故事中描繪的森林裡，<br>有兩名掛在藤蔓上<br>快速移動的賽馬娘──<br><br>「我說大樹啊！」<br><br>「What？什麼事？」<br><br>「在這種情況下，<br>我有一件無論如何都想做的事……<br>不，應該說想說的話？<br>不對，還是該說想大聲喊出來……！」<br><br>「……I see！<br>我現在的心情跟唐懷瑟一樣！」<br><br>「真的嗎！那麼就<br>喊三、二、一之後一起……！<br>3、2……1！」<br><br>「啊──啊啊～～～～～～♪」"},
{index="30104",text="「有水魔誘惑的岸邊，<br>有妖精引導的庭院，<br>有星星指示的門扉……<br>迎接跨越眾多考驗，<br>最後抵達目的地的<br>村民們的是<br>世上最美的景象──」<br><br>「Amazing……！<br>牆壁真的閃著藍光！」<br><br>「真的就像是另一個世界……<br>居然有這種地方……！」<br><br>「面對如此夢幻的景象，<br>村民們不自覺的發出驚嘆──」<br><br>啊啊，啊啊──！<br>我現在真的在故事當中！"},
{index="30105",text="「成為日本第一的賽馬娘」<br><br>那是我的夢想。<br>是我與媽媽約定好的重要夢想。<br><br>但我的夢想有如寒冷早晨的迷霧，<br>無法順利塑形，還只是個憧憬。<br>而我則不顧一切地想去掌握那無形之物。<br><br>──不過。<br><br>歷經許多邂逅，<br>讓我的夢想鮮明了起來！<br>與勁敵間的熱血競賽，<br>和必須跨越才行的障礙。<br>痛苦的事情，難過的事情。<br>高興的事情，開心的事情。<br>這一切都讓我的夢想具體了起來！<br><br>你有憧憬的事物嗎？<br>有不想放棄的願望嗎？<br>去追吧！我們一起！<br>去抓住你最重要的夢想！"},
{index="30106",text="關係到能否達成母女皆稱霸奧克斯這個歷史性紀錄的競賽。<br>會場上充斥著各種流言，<br>讓她的肩膀承受著龐大的壓力。<br><br>但當「女帝」現身的瞬間，<br>就像一陣薰風橫掃了所有喧鬧。<br>宛如將風都納入其支配下一般，<br>她以威風凜凜的步伐邁向起跑閘門。<br><br>令萬物折服的銳利眼神。<br>彷彿要刺進皮膚般緊緊握住的五指。<br><br>追求的是理想。欲求的是勝利。<br>武器是身為「女帝」的自尊。<br><br>「──絕對要贏。」"},
{index="30107",text="超讚姐姐的天氣預報♪<br><br>今天的我陽光明媚☆<br>如盛夏般熱情耀眼的光線<br>會直接射中每個人的心！<br>記得在海邊玩個痛快才能跟上流行唷♪<br><br>但是快樂的時光總是短暫……<br>到了傍晚時分<br>或許會覺得有點冷也說不定？<br><br>夕陽則會讓人有點消沉<br>部分地區可能會出現感傷警報。<br><br>不過，完全～不用擔心！<br>因為照亮我的<br>並非只有太陽而已……<br>還有熱情到讓我興奮不已、<br>非～常耀眼的存在喔♪<br><br>稍微沉浸在感傷的氣氛後，<br>想必明天又會是個溫柔的晴天吧♪"},
{index="30108",text="我所期望的，是令人沉醉的一瞬間。<br>踏上盡可能單純，<br>卻又刺激無比的舞台。<br>靜待對手們的＜加注＞。<br><br>我的命運取決於敵人手中……<br>就是這麼一回事。<br><br>──判定的時刻。<br><br>這一瞬間，彼此將共同把命運燃燒殆盡。<br>消逝而去的燈火們。<br><br>啊啊，沒錯。<br>正是為了這一瞬間，所以我……<br><br>「──就是因為這樣，所以我才戒不掉啊。」"},
{index="30109",text="「有超讚心志就有櫻花心意」<br><br>（出處《某場白熱化的對決》）<br>意思是如同有人因為崇拜<br>超讚心志及生存方式而奔跑，<br>希望為崇拜對象盡一分力的心情<br>只要認真付出的話也有可能<br>獲得好的結果。<br><br>（解說）<br>正因為有崇拜對象在<br>我才能一直努力到今天。<br>所以，這次換我成為崇拜對象的力量！<br>為了讓她能盡情享受並燃起鬥志──<br>我要盡全力去打倒我崇拜的人！"},
{index="30110",text="……歡迎光臨。<br><br>你今天……也來了呢。<br>……是……<br>暫時會在這裡，幫忙父親……<br><br>請問你要點……<br>好的，和之前一樣的黑咖啡。<br>立刻送過來──<br>…………牛奶要多一點，是嗎？<br>不……沒問題。<br>是沒問題……只是覺得，有點難得……<br><br>……原來如此，真是辛苦你了……。<br>………………<br><br>──那個……雖然剛才說了立刻送過來……<br>能不能，給我一點點時間呢？<br><br>「為客人獻上特別的一杯」<br><br>……父親曾這麼教過我。<br>我想稍微……加入一點不同的嘗試……<br><br>你問我，什麼樣的？<br>這個嘛──<br><br>……就把這點，當作稍後品嚐時的樂趣吧。"},
{index="30111",text="不論是競賽還是其他事物，<br>每次面對挑戰的時候，<br>我心裡比起緊張更多的是興奮。<br><br>雖然人家常說我「好奇心真旺盛耶」，<br>但其實不光是那樣而已。<br><br>成功辦到後，或是抵達終點後……<br>大家對我傳達的那種閃閃發亮的感覺！<br><br>我現在已經很期待了。這場勝負的前方，<br>不知道會有什麼樣的光輝在等著我呢！<br>所以，絕對要用我的操作技術──<br><br>「藍色圍巾隨風飄揚～♪<br>轉動方向盤吼叫吧最強車種～♪」<br><br>「帝皇──皇──♪帝皇──皇──♪」<br><br>「帝皇──皇──皇──！！！」<br><br>「真是的，渦輪！我正在想很嚴肅的事<br>別擅自創作奇怪的歌啦～～！」"},
{index="30112",text="雙渦輪今天也是<br>在訓練賽道上全力奔跑。<br><br>「吸……呼……呼……」<br><br>可是，她總是維持全力奔馳，<br>每繞一圈，跑步速度就會逐漸下降。<br><br>「喂──二重推進器！<br>差不多該休息了吧？」<br><br>「我叫雙渦輪！<br>比起那個我要再跑一次，<br>好好幫我計時，帝皇！」<br><br>「遊戲也是一樣。<br>只要越努力就能跑得越快！<br>我絕對不要放棄！」<br><br>「我要再使出像遊戲裡面的那種技能！<br>要上囉，渦輪全開──！！」<br><br>雙渦輪再次充滿氣勢地起跑。<br>但是，卻很快就慢了下來而且搖搖晃晃。<br><br>即使如此，<br>看著她一心一意不停向前奔跑的樣子──<br><br>「……果然還是很帥氣呢。」"},
{index="30113",text="乘著鐵製的飛機飛越山巔──<br><br>在現實中是理所當然的景象。<br>將符合飛行力學的設計圖<br>與零件相互組合即可……但在這裡不同。<br><br>從未見過的材料，<br>從未聽過的原理……<br><br>要想實現計畫，<br>果然應該先從理解這個世界<br>這件事開始著手……<br><br>「嗯……這個在我們的世界<br>相當於鈦金屬嗎？<br>然後這是利用蒸汽機的最初發明……」<br><br>「唔……？這是無線電嗎？<br>竟然是利用電磁波覆蓋地表的輸電系統？<br>而且還透過壓縮蒸汽達到了半永動機？」<br><br>「等等，歸根究柢，難道已經開發出<br>足以承受如此巨大壓力的合金了嗎！？<br>而且還遠遠超過鎢金屬！？<br><br>「……這只是奇幻世界。<br>再吐槽下去會沒完沒了的。」"},
{index="30114",text="「肖像畫是我們家族的榮耀。<br>是留名歷史的功績與繁華的榮譽。」<br><br>嘹亮的聲音響徹高雅的階梯平台處。<br>少女站在掛滿整面牆的肖像畫前。<br>纖細的身形散發著空靈氣質，<br>眼神清澈而凜然。<br><br>「我的母親和祖母也在這裡。<br>她們於無數競賽中勝出，並獲得URA獎。<br>在我們家族中也是傑出的光輝。」<br><br>白瓷般的指尖輕巧地劃過空中。<br>優美的右手<br>放在有紅色緞帶擺動的胸前。<br><br>「每位家族成員，無一例外──」<br><br>她的話語迴蕩在挑高的階梯平台處。<br><br>而佈滿牆上的每雙眼睛，<br>都注視著少女的背影──"},
{index="30115",text="萬聖節扮裝攝影會～喔耶☆<br>我要把超上鏡的善善給拍起來！<br><br>「喔～服裝和背景都超正式的耶！<br>感覺一定可以拍得很美～」<br><br>「對啊～！善善，<br>惡魔扮相超適合妳唷！一億分！」<br><br>像這樣的叫什麼來著，妖豔？<br>果然善善拍這種<br>成熟感覺的照片也美到爆♪<br><br>「好，趕快來拍拍看吧～！<br>善善，變成一個真正的惡魔吧～！」<br><br>「咦咦，要融入角色是嗎……<br>那樣子，有點害羞耶。」<br><br>「沒～問～題！<br>想像自己是個超～貪心的小惡魔～<br>然後奪走一切就好了！」<br><br>「原來如此，奪走……OK，我試試看！」<br><br>「──我說你，有股很香～甜的味道呢……<br>感覺比點心還要更美味……♪」<br><br>唔哇～迷死人了！<br>不管是誰都會想被善善給吃掉的！<br>超正超美的照片，爆誕降臨啦！<br><br>──月夜下的微笑惡魔！<br>萬聖節之夜開始囉～！"},
{index="30116",text="萬聖節扮裝攝影會！<br>要來拍太陽的超美照片喔！<br><br>「喔耶喔耶～！萬聖節快樂♪<br>如何？天使的我，好看嗎？」<br><br>「呵呵，超好看的！果然<br>太陽跟活潑的造型超搭呢！」<br><br>她總是會喊著喔耶並追求樂趣，<br>同時為身邊的人帶來好心情呢。<br>太陽給予大家的元氣，<br>簡直就像是天使的恩惠……之類的？<br><br>「好，太陽就隨意活動吧！<br>我會跟著妳然後自己找機會拍照的！」<br><br>「真假！？那麼我就<br>到處去發點心吧～！」<br><br>「喔耶喔耶～☆<br>天使小姐來囉～！<br>這些點心是送給大家的禮物～for you♪」<br><br>竟然是去發點心！<br>不斷帶給大家元氣<br>並盡情享受歡樂氣氛的太陽……<br>嗯，這一定是最棒的畫面。<br><br>──陽光下的閃耀天使！<br>萬聖節派對開始啦！"},
{index="30117",text="《風風的魔王城計畫書》<br><br>＜魔王城的設定＞<br>魔王風風的恐怖魔王城！<br>凡是踏進這裡的人<br>都會遇到可怕到不行的東西，<br>然後陷入恐怖的深淵！！<br><br>＜形象＞<br>．使用1間教室！！<br>．全部黑漆漆！牆壁掛上黑色幕布！<br>→暗黑魔王的城堡要很暗很恐怖！<br>．最終BOSS★★風風魔王★★<br>．不先通過很多試練的話<br>就沒辦法到達魔王大人面前！<br>．通道會繞來繞去非常複雜，<br>讓人搞不清楚自己在哪裡！<br>．考驗的種類<br>→從有很多恐怖陷阱的箱子中找出鑰匙<br>→和妖怪戰鬥<br><br>＜妖怪候補！＞<br>．巨大妖怪※總之很大隻很可怕！<br>．南瓜妖怪※會飄浮<br>．惡魔※被抓到的話會全身動彈不得！<br>．殭屍※被咬到的話就會變成跟它們一樣<br><br>所～有人都會陷入恐怖谷底，<br>魔王軍要開始支配世界啦！！"},
{index="30118",text="時間到了。<br><br>隨著步伐的前進，<br>歡呼聲、腳步聲、心跳聲──全都逐漸遠去。<br>然而──<br><br>靈魂，發出勇猛戰吼。<br>苦味已被我緊咬不放。既然如此，<br><br>「唯有將其咬碎」。"},
{index="30119",text="在那裡，<br>有過懊悔。<br>有過嘆息。<br>有過遺憾。<br>但是，必定也都伴隨著<br>對於未來賽馬娘的祈願──<br><br>多麼高尚、偉大的先進們啊。<br>多麼崇高的意志啊。<br><br>「總有一天──<br>總有一天，我一定會親自證明。」<br><br>證明所有的祈願<br>都確實為將在當下飛奔至未來的我們<br>提供了持續前進的動力。"},
{index="30120",text="這是神馬們練習「思織」時的一幕──<br><br>「八重妳看起來像是<br>一點都沒感覺到火焰的熱氣，<br>威風凜凜地跳著舞……<br>太了不起了。<br>我非常想向妳看齊，<br>請問有沒有什麼祕訣呢？」<br><br>「不，像我這種資歷尚淺的人<br>稱不上有什麼祕訣──<br>只是，當我跳舞時會不可思議地<br>感覺不到熱氣……」<br><br>「原來如此……真可說是<br>『滅卻心頭火自涼』<br>這句話的體現呢」<br><br>「如果真的有達到那個境界<br>我會非常開心的。<br>……呵呵，只要一專注就會<br>忽視周遭的性格──<br>總以為是我的壞習慣，<br>但從不同角度來看<br>說不定也能成為我的武器呢。」<br><br>「是的，一定可以……」<br><br>「既然如此，我八重無敵發誓<br>無論面對多麼熾熱的烈火<br>也會以堅定無比的內心，<br>必將我的職責貫徹到底……！<br>即使烈火將此身<br>烤到熟透焦黑<br>我也會毫不動搖，<br>把舞蹈跳到最後……！！」<br><br>「呵呵呵，真是了不起的氣魄。<br>只是，烤到熟透焦黑的話<br>可就糟糕了……<br>還是多多練習<br>安全的跳法吧。」<br><br>「……是！！」"},
{index="30121",text="粉絲感謝企畫的邀請函<br><br>感謝你<br>一直以來對賽馬娘們的支持。<br>我是執行委員美浦波旁。<br><br>我們一心以終點為目標<br>不斷奔跑至今。<br>但是──<br><br>不論是受夢中景色深深吸引時<br>還是為眼前高牆深感挫折時<br>我們都不是孤單一人。<br><br>你的鼓勵，總是陪伴著我們。<br>每當聽見你的聲援，<br>都讓我們重新振作並追求新的夢想。<br><br>與大家一起留下的足跡，<br>也即將進入第二彎道。<br><br>以競賽來比喻的話，<br>就像剛結束暖身……<br>將保存的力量注入雙腳起跑的時刻。<br><br>因此，雖然不成敬意<br>為了表達平日的感謝與今後奮起的決心<br>我們決定舉辦粉絲感謝企畫。<br>務必希望能邀你同樂。<br><br>今後，我們也會繼續奔馳。<br>與無可替代的你一起跑下去。<br><br>「……好了！像這樣的感覺如何？」<br><br>「好厲害……沒改變內容<br>就消除了文章生硬的感覺……！」<br><br>「我同意鈴鹿所說的。<br>若是這份邀請函的話，<br>推測粉絲們能夠輕鬆地參加。<br>也就是說……『非常棒』。」<br><br>「耶嘿嘿～！不過，這都要多虧有小波<br>一開始寫的那份充滿心意的文章，<br>才能有這麼好的效果喔♪<br>剩下的只等當天讓大家都玩得開心了☆」<br><br>「是的。<br>……當天……令人『非常期待』。」"},
{index="30122",text="1、2、345、67、8、910……<br>節拍器如果亂了調，<br>就無法完成它的職務。<br><br>刻入、刻入──沒有例外以相同間隔刻入。<br>那份美麗是我的指標。<br>仔細聆聽、保持均衡。可是卻──<br><br>123、4、567、89、10……<br>我沒有將亂了調的節拍器矯正，<br>直接將它塞進忘卻的箱子。<br><br>感動、昔日、嬉笑、鄉愁、羨慕、<br>落淚、執著、往來……！<br>這些事物現在，正朝我不斷逼近！<br>宛如故障的鐵皮玩具，<br>輕快的節奏無法抑制！<br><br>「Danke！Danke！<br>……Danke！！」<br><br>留下的只有歡喜的坩堝……<br>Danke！這是現在唯一的心情！"},
{index="30123",text="「妳也會有這樣的表情啊。」<br><br>對於氣槽的發言，<br>成田白仁的耳朵不禁晃動了一下。<br>接著她看了這邊一眼，<br>像是在說「妳有什麼意見嗎」般。<br><br>「只是想告訴妳這是一張好照片。<br>聖誕夜，就應該像這樣。<br>本來以為妳可能不喜歡聖誕節……<br>想不到似乎沒那回事？」<br><br>「嗯，因為不管吃多少肉<br>也不會被大姊嘮叨啊。」<br><br>「哈哈，那很好啊。原來即便是晨光<br>也不會在聖誕夜掃人興致呀。」<br><br>「而且……」成田白仁說道，<br>並抬頭仰望<br>耀眼奪目的化朗塔。<br><br>「偶爾像這樣，也挺不賴的。」<br><br>「難得我們看法一致……我也這麼認為。」<br><br>化朗塔的燈光不停地閃爍。<br>成田白仁與氣槽，<br>則一起欣賞了那光芒一段時間……"},
{index="30124",text="特雷森學園聖誕節派對的<br>前一天，氣槽和富士奇石<br>正在討論某一件事。<br><br>「咳……『聖誕快樂。<br>非常感謝各位，<br>今天蒞臨特雷森學園。』──<br>首先我打算這麼開場。」<br><br>「嗯，可以很清楚地感受到<br>氣槽的誠意喔！只是考慮到當天<br>是聖誕節，或許太嚴肅了一點？」<br><br>「……果然嗎。<br>但我一想到要在公開場合<br>代表學生會發言，就實在……」<br><br>「因為氣槽妳非常重視<br>時間、地點和場合嘛！<br>不過既然如此，換個想法怎麼樣？<br>要在聖誕節派對上扮成聖誕老人的話，<br>那動作就必須像他才行呀──」<br><br>「──『呵、呵、呵、呵！<br>Merry～～Christmas～～！』<br>像這種感覺！好，輪到妳了喔！」<br><br>「什麼！？唔……唔唔……<br>『呼、呼、呼，Merry Christmas！』<br>……這樣嗎！？」<br><br>「嗯～～可惜！<br>……與其說是聖誕，感覺更像撒旦？」<br><br>「妳說誰是惡魔啊！」<br><br>「啊哈哈，就是這樣！<br>表情變得非常生動呢，<br>氣槽！<br>……這點應該是最重要的不是嗎？」<br><br>「唔……<br>……不，原來如此……說得也是。」<br><br>「這樣子的話會被母親斥責吧──<br>聖誕節是『快樂』的活動。<br>那麼──作為『享樂』的場所，<br>就該由我先發自內心地傳達給大家才行。」<br><br>「沒錯！<br>呵呵，當天妳也要玩得開心喔，氣槽。」<br><br>「是啊，我會努力的。」"},
{index="30125",text="表演得如何呢？我絕不會這麼問。<br>因為我將一切都投注在舞台上了。<br><br>高聲演唱直到聲嘶力竭。<br>賣力的舞步彷彿能將地板踏破。<br>因為無論如何都想讓妳注意到我，<br>所以拿出了我的所有。<br><br>這是來自我的訊息。<br>傾注了一切，此刻最真實的心情。<br>所以說，小仁──<br><br>「真希望下次妳也能一起歌唱。<br>……就在我的身邊。」"},
{index="30126",text="本次競賽聚集了稱霸過GⅠ賽事的強者。<br>另一方面。山人西風<br>尚未取得引人注目的成績。<br><br>無人將關注的目光投向她，<br>也是理所當然的事。<br><br>不過，人們很快就會發現，<br>將她視為微風（=西風）而小看她是一場錯誤。<br><br>「──喝啊啊啊啊啊啊！」<br><br>山人西風早早就發動進攻。<br>那道身影，宛如疾風。<br><br>在第四彎道位居第三名。<br>後在直線上飛躍而出奪得領先。<br><br>自由自在，比誰都要迅速的風飛快疾馳。<br>宛如昔日，她曾目睹的那個憧憬一般。<br><br>──任何人都無法靠近的烈風。<br><br>「……這就是，那陣風所看到的景色。<br>多麼清新的風啊。」<br><br>「但是，尚在風道的途中。<br>不能在此停下腳步。」<br><br>「真正的風位在前方。<br>而我將化為快過一切的風，向前吹去。」<br><br>回到終點鏡板前的她，<br>把右手伸向了天空。<br><br>──賽場上吹過了一陣風。<br>那是帶來祝福的薰風。"},
{index="30127",text="「小特知道寄託在<br>板羽球上的願望嗎？」<br><br>將要在臉上塗墨用的毛筆<br>拿給我的小草，突然<br>問了我這麼一個問題。<br><br>「寄託在板羽球上的願望……？」<br><br>「據說在插著羽毛的果實寄託了<br>『保佑身體健康』<br>這樣的願望……<br>羽子板則寄託了『消除各種災厄，<br>祈求健康平安地長大』<br>這樣的願望，<br>並在過年的時候用來當作贈禮喔。」<br><br>「喔～！」<br><br>「所以板羽球原本，<br>並非對打的競技，<br>而是為了祈求彼此的健康<br>要相互擊球久一點的活動。」<br><br>「咦咦，原來是這樣啊！<br>那麼接下來得儘量持續久一點才行！<br>……啊，那再請問！小草老師！<br>難道說在臉上塗墨的處罰，<br>也有什麼典故嗎？」<br><br>「好問題。特別週同學。<br>有一說認為墨的黑色是能驅魔的顏色，<br>只要將其塗在臉上就能除魔<br>並藉此達到護身的作用喔。」<br><br>「因此也就是說，<br>萬一不小心讓板羽球掉落，<br>只要將墨塗在臉上就沒問題了。」<br><br>「原來不是單純為了處罰啊！<br>──好！」<br><br>我接過毛筆<br>然後用力緊握並深呼吸。<br><br>「希望小草<br>一整年跑步都不會受傷，」<br>在她右眼畫上一個大圓圈。<br>「不會感冒也不會生病，」<br>在她左臉畫上一筆斜線。<br>「吃到很多美味的東西，<br>獲得很多的歡笑。」<br>左臉再畫上另一筆斜線。<br><br>每一筆都灌注心意。<br>作為朋友，作為勁敵，<br>希望今後無論何時何地，<br>我們都能一起奔跑下去──<br><br>「……為了我祈求這麼多<br>謝謝妳，小特。<br>不過，呵呵，妳是不是有點塗得太多了呀？」<br><br>「咦？哇！？對不起！！！！」"},
{index="30128",text="她靜靜地走在白雪覆蓋的石階上。<br>閃耀著光澤的尾巴與蕾絲傘開心地搖曳，<br>清冷的風中隱約聽見了哼歌聲。<br><br>突然，攝影師叫了她的名字。<br>她的尾巴先是大力地搖動一下<br>接著緩緩朝這邊回過頭──我不禁屏息。<br><br>落在美麗容貌上的雨傘陰影。<br>當中綻放的一點紅，與若隱若現的潔白。<br><br>望向身後的目光，<br>略微傾斜的細頸。<br>看著她舉止端莊地握著傘柄的雙手，<br>原本在我印象中的她不知被帶往何處。<br><br>驚為天人的美貌。<br>在我眼前的確實是她，<br>卻讓人深深著迷到不禁懷疑現實。<br>──彷彿被施了魔法般。<br><br>不經意地與她的視線相交。<br>她開心地瞇起雙眼，笑著開口。<br><br>「哼哼，很完美吧？<br>未來的大魔女<br>可是能變成各種姿態的喔♪」"},
{index="30129",text="一盞、兩盞地逐漸增加──<br>那是在天亮前的神社境內，<br>心繫擔任賽馬娘巫女的她們而點起的燈火。<br><br>她們的話一定可以完成任務，<br>信心的火炎擴散了開來。<br><br>「……好美呢。」<br><br>將隆冬夜晚刺骨寒風給融化的，<br>是溫柔燈火，<br>也是某人為某人著想的真誠心意。<br><br>遠處漆黑的山影。<br>眺望那燈火已熄滅的山頭並心想──<br><br>希望她們有注意到。<br>這份美麗的溫暖心意。<br><br>但願能夠傳達到。<br>點亮手中提燈的每個人，<br>都還沒有對她們兩人放棄希望。"},
{index="30130",text="「再來，換下一首曲子。<br>這首歌……大家知道嗎？」<br><br>「嗯！是生日的歌──！」<br><br>「嗯，這是用來慶祝生日的歌喔。<br>用來說恭喜、謝謝。<br><br>可是，聽說它原本<br>是不一樣的歌喔。<br>並非只為了某個特別的日子，<br>而是為每天的『早安』所唱的歌。」<br><br>「真的嗎～？」<br>「奇蹟姐姐，早安～！」<br><br>「啊哈哈。嗯，早安。<br>那麼這次配合鋼琴的音樂，<br>來打招呼看看吧。」<br><br>「──無論是我，還是你們，<br>新的早晨都一定會來臨。<br><br>所以呢，夜晚在床上準備睡覺時<br>如果感到寂寞的話，<br>就想一想大家一起唱過<br>這首歌曲吧。<br>然後，再這麼告訴自己──<br><br>『睡覺不是因為黑暗的夜晚到了。<br>而是為了在早上，跟大家說聲早安』。」<br><br>黑暗的夜晚不會永遠持續下去。<br>等待你們的，<br>一定會是溫暖的未來。"},
{index="30131",text="～美麗☆巧克力～<br><br>請大家期待最後的成果吧☆<br>將帶給你美麗的心情喔★<br><br>「咦，這個楓葉造型的巧克力<br>是第一次吃到的口味！似乎有點<br>接近楓糖。感覺就像花蜜很好吃……！」<br><br>「這、這個重現跑車造型的巧克力，<br>雖然很厲害但不方便吃呢……不，這是什麼<br>獨特的口感？<br>尤其後照鏡部分更是一絕！」<br><br>「呼、呼喔喔喔喔喔！這個天鵝湖的巧克力，<br>奧傑塔的悲傷<br>流進了口中！？簡直就像是<br>直接將藝術本身吃進肚子裡！」<br><br>啊哈哈哈哈☆很不可思議對吧，<br>奇怪的巧克力如果不親自吃吃看<br>就無法知道究竟好不好吃★<br><br>這點跟人生一模一樣！<br>不嘗試看看就不知道，<br>究竟會發生什麼事，<br>而正因不知道所以美麗☆<br>來，盡情享用美麗吧★"},
{index="30132",text="「歡迎光臨！<br>這位客人，讓我來為妳帶位！」<br><br>「嗯嗯，那就拜託妳囉，小微♪」<br><br>「啊～曙曙！這是練習，<br>妳要好好扮演客人喔！<br>那麼，請往這邊！」<br><br>「阿薩姆紅茶！……不對，<br>這是妳點的阿薩姆紅茶。<br>豐富的口味層次能夠帶出甜點的香味，<br>因此請、和、這邊的、一起……！」<br><br>「沒、沒問題嗎～！？那麼多甜點，<br>不用雙手拿的話很危險喔？」<br><br>「敢、敢面對困難才算英雄！<br>就像雷恩前輩和和艾尼先輩一樣，<br>我也可以成功辦到！」<br><br>（然後──我要像正義的夥伴那樣，<br>成為能夠讓大家依靠的自己！）<br><br>「～～唔！讓妳久等了！為妳送上<br>究極．奢華．飛駒<br>甜點天堂！！」<br><br>「哇啊，每個都完好無缺！<br>好厲害好厲害，竟然可以<br>一次端這麼多！<br>就像英雄一樣很帥氣喔～！」<br><br>「是、是嗎？……嘿嘿♪<br>──那麼，這位客人。<br>請妳慢慢享用！」"},
{index="30133",text="大家buono♪今天的UG直播<br>要製作微苦好吃的<br>「黑巧克力」喔！<br><br>其實呀，我本來有些煩惱<br>不曉得如何教大家這道食譜。<br>因為，有的人就是接受不了苦的東西吧？<br>而且我想做的，是像相撲火鍋那樣<br>能讓大～家都露出笑容的料理。<br><br>……可是呀，<br>當我看著那位小小英雄，<br>便覺得自己也必須拿出勇氣才行。<br><br>所以我決定要<br>拿出最大誠意面對大家。<br>因為我想要用最喜歡的巧克力<br>和大家一起說著buono♪然後互相歡笑！<br><br>「好想吃吃看小曙的巧克力啊～」<br>「我也想要曙曙的巧克力！」<br>「曙曙喜歡的黑巧克力讓人很感興趣呢。』<br><br>啊……！嗯，那個啊！<br>推薦的可可比例是……<br>啊，有件重要的事忘了說。<br><br>大家──情人節快樂！"},
{index="30134",text="貫徹完美。<br>展現豔麗。<br>貢獻至愛。<br><br>美妙的身軀只為向前奔馳。<br>紫紺的雙瞳只容得下無瑕的榮耀。<br><br>菊、櫻、橡木、薔薇。<br>眾花無一不俯首稱臣。<br>嫉妒、渴望、憧憬、鬥志。<br>一切情感皆望塵莫及。<br><br>她將向前奔馳。接著奪得勝利。<br><br>其名為──"},
{index="30135",text="很多人會這麼說。<br>「這麼高的牆，根本不可能跨得過去。」<br>「但總有一天還是有人能辦得到吧。」<br>「有朝一日，肯定會有人……」<br><br>可是──不是這樣吧？<br>正因為沒人要上，才更該靠自己的雙腳邁進！<br>害怕的心情、想要放棄的心情，<br>全部都放在一邊，往前衝就對了！<br><br>如果還是不敢踏出步伐的話──<br>就看著我吧！跟著我一起衝！<br>讓我來開闢眼前的道路！<br><br>這樣才是賽馬娘們的王牌！<br>葛城榮主！！"},
{index="30136",text="響徹四方的蹄鐵聲不絕於耳。<br>彷若在來回迴盪一般，<br>包覆著全身。<br><br>……嘈雜聲──逐漸變得火熱。<br><br>目標的所在地、想要獲得的事物、<br>抵達的境界。<br>雙眼裡寄宿的火焰，<br>懷抱的鬥志不分上下，<br>那是否要一起馳騁在翠綠之上呢？<br><br>「No way」<br><br>任誰……都不會放手──不會拱手讓人。<br><br>能站上那個地方的只有一人。<br>衝吧、衝吧、衝吧。<br>拿出捨我其誰的自信向前衝刺。<br>這樣才能讓這個場所──<br>以至於有朝一日讓這個世界，<br>持續高揚下去。"},
{index="30137",text="讓我向妳們傳授睿智。<br>願先人點燃至今的知識燈火<br>得以成為你們的指標。<br><br>讓我聽聽妳們的苦惱吧？<br>那些苦惱也是其他人曾經有過的經歷。<br>即使身處昏暗的森林，只要跟隨腳印前進便能豁然開朗。<br><br>需要勇氣嗎？<br>那就讓我來訴說吧──<br>訴說曾經馳騁四方的人，是如何踏出第一步的。<br><br>即使時代變遷、就算形式不同，<br>深鑿在大地上的蹄鐵痕跡始終不變。<br><br>就讓我們將積年累月所編織出來的錦旗上，<br>一針一線所代表的故事講述給妳們吧。<br><br>接著將一切連繫起來，<br>獻給奔馳於現代的賽馬娘們！<br><br>傳說將會締造下一個傳說。<br>──繼承者們，願你們獲得無限的祝福。"},
{index="30138",text="我闔上雙眼，想要回憶起妳的樣子。<br>可每次浮現的， <br>都一定是妳逐漸遠去的背影。<br><br>彷若跳著舞般向前飛奔而去的妳，<br>帥氣到讓人不禁笑了出來──<br><br>真是不甘心呢。從我的角度，<br>看不到妳臉上有什麼表情啊。<br>這樣我就算想追過妳，也無法如願以償嘛？<br><br>……真希望能拿出一點點的勇氣，<br>讓妳至少能回過頭來，<br>然後叫妳看向我……<br><br>──可是，我時至今日累積下來的一切。<br>我所希望能夠達成的目標。<br>都還未能傳達給妳。<br><br>所以我要透過這支舞……<br>將這些全部刻印在妳的心裡！"},
{index="30139",text="由於不習慣舞會的氣氛，<br>閒暇之下我來到了露台。<br>……卻跟早一步來這裡享受夜風的<br>目白麥昆四目交接。<br><br>「你也是來這裡休息的嗎？」<br><br>我找不到舞伴，<br>所以沒辦法加入社交舞的行列。<br>明明這樣老實回答就可以了，<br>我卻只是苦笑一下蒙混了過去。<br><br>「……難道說……你也是為了逃離<br>其他人排山倒海的邀約才逃到這裡來……？」<br><br>我見機不可失，用力點了點頭。<br>不能在她的面前露出自己丟臉的樣子。<br>被這種毫無來由的虛榮心所支配的我，<br>忍不住別開了視線。<br><br>「……我們回去吧──」<br><br>「──請你跟我一起回去，跟我共舞。」<br><br>還沒等到我的回應，<br>目白麥昆便向前邁開了腳步。<br>她只回過頭一次，用銳利的眼神瞪了我一番。<br>我慌慌張張地小跑步追了上去。<br>她的腳步變得稍微快了一些，<br>步伐間似乎可窺見一絲雀躍之情。"},
{index="30140",text="如流水一般的步伐。<br>既優雅……又纖細……<br>但我很清楚。<br>妳那將歡呼聲佔為己有的柔韌雙腳，<br>並未因這點小事而感到滿足。<br><br>「麥昆，感覺不錯！<br>對手們傳來的視線都好火熱哦～！<br>哼哼，我們肯定是最佳舞伴了！」<br><br>「妳的情緒都已經高漲起來了呢。<br>舞步的速度變快了喔。」<br><br>「因為啊，這樣下去的話──」<br><br>「我們『只能』獲得最佳舞伴的頭銜。<br>妳是想這麼說吧？」<br><br>「嘿嘿，就是這樣！<br>我們的目標要更上一層樓！<br>好了，跟上來吧……！」<br><br>配合彼此的呼吸，既溫柔又優雅。<br>如同飛舞於蒼天的雙翼。然而──<br><br>「──這樣不夠。我也有自己的自尊……<br>也有應該抵達的頂點。<br>我們要繼續向高處邁進囉……！」<br><br>「啊哈哈！這樣才是麥昆──<br>才是我的搭檔呢！<br>證明給大家看吧！<br>我們是『史上最棒的舞伴』！」"},
{index="30141",text="美浦波旁開始進食。<br>為了有效率地補給能量，<br>她默默地以固定的速度<br>將干瓢卷塞入口中──<br><br>「波旁做的干瓢卷，<br>外形真漂亮呢。<br>是很完美的圓柱狀。」<br><br>「我在捲動的時候有注意施以平均的力道。<br>不嫌棄的話，請吃一條。」<br><br>「謝謝，我就收下了。」<br><br>「小波，<br>要不要跟我的凍派交換？」<br><br>「也吃吃看我做的炸雞塊吧！<br>這是我經營定食店的父母親自傳授給我的料理！」<br><br>「我用爆速做好的三明治，<br>也請務必品嚐看看！」<br><br>「……各位，謝謝妳們。」<br><br>美浦波旁在接過大家的料理後，<br>靜靜地露出了微笑。<br><br>（經過剛才的交流，<br>察覺到特殊的能量獲得補充。）<br><br>（我希望大家也能獲得<br>「開心」狀態。<br>只是，我不曉得我能否實現這個目標……）<br><br>美浦波旁不禁抿起了嘴。<br>──但當她看著其他四人時，<br>雙頰又再次放鬆了下來。<br><br>「推測帶來這股能量的重要事物……<br>是我現在這張『自然的笑容』。<br>開始執行任務──<br>『回報活力』。」"},
{index="30142",text="櫻花桂冠在接下傳球的那一瞬間，<br>回想起了自己的童年。<br><br>身體孱弱的她沒辦法參與激烈的運動，<br>總是待在一旁看著大家。<br>那些日子她都只能坐在球場的邊線外，<br>笑著將滾過來的球交給大家。<br>一直以來，<br>她都憧憬著能與大家一起跑跑跳跳。<br><br>今天，她終於瞭解到了。<br>跟相互信賴的夥伴一起遊玩，<br>原來會是件令人如此雀躍的事。<br><br>櫻花桂冠用力往地板一踏，<br>縱身躍向了高空。<br><br>「我想跟這個隊伍──一起獲勝！！」"},
{index="30143",text="致親愛的搭檔──<br>小時候，我們時時刻刻都陪在彼此身邊呢。<br>我因為生病而沒辦法到處跑，<br>但你卻總是可以帶著我到很遠的地方。<br>能夠憑著自己的力量想去哪就去哪，<br>讓我開心到忘我地不斷踩著踏板的那個時候……<br><br>有一次，我們還一起挑戰過那個<br>大家都說不可能騎得上去的高地呢。<br>再怎麼爬都好像永遠爬不完的那條坡道，<br>儘管途中有過數次想放棄的念頭，但還是努力爬到了頂點，<br>最後俯瞰而下的那片海真的好漂亮……<br>時至今日，那次的經驗都還是支撐著我的動力。<br><br>而今天，在我與夥伴們的努力不懈之下，<br>得以將一幅美不勝收的景色收進眼簾裡。<br>燈光照射下的舞台。<br>大力揮舞著的手燈。<br>許許多多的笑容與歡呼聲。<br><br>這幅景色跟當初與你從高地上<br>俯瞰的景色一樣絢麗。<br>無論何者，都是我獨自一人所無法抵達的景象。<br><br>能帶我走到這裡的，<br>毫無疑問，絕對是你。<br>讓我們再一起踏上旅程，<br>去尋找那些未曾見過的景色吧。"},
{index="30145",text="這裡是特雷森學園──<br><br>擁有時而突發奇想、<br>時而放鬆悠閒的歷史。<br>一出生便擁有來自另一個世界的名字，<br>而她們繼承那份靈魂<br>悠哉地於青春奔馳……<br>這就是，她們的日常？<br><br>既有天空降下落雷的日子，<br>也有發生難解事件的日子，<br>說不定也會有什麼都沒發生的日子。<br>這就是──她們的日常！？<br><br>好了，今天又會是怎樣的一天呢？"},
{index="30146",text="「思驅」起點。<br>從這個位置也能清楚看見「思織」──<br>熊熊燃燒的「蹄板」，化為火花<br>昇上天空的情景。<br><br>「小栗，妳幹嘛邊盯著天空<br>邊站在那裡發呆？<br>很快就要輪到我們的『思驅』上陣囉？」<br><br>「沒有，只是……<br>我在想我總有一天，<br>也會寫下『蹄板』，<br>並將意志託付給某人吧……」<br><br>「……到時自己<br>究竟會在『蹄板』上<br>寫下什麼樣的意志呢？<br>一想到這點就忍不住開始思考很多……<br>但是，思考再多卻還是沒有答案。」<br><br>「哈哈，那種事妳現在再怎麼想<br>也不可能會知道啊！<br>對吧稻荷？」<br><br>「當然啊！<br>我們能為明天做的，<br>就是盡全力做好現在能做的事而已！」<br><br>「對啊！不如說<br>妳只要抱著『我要在蹄板寫下這件事！』<br>這種心情去努力跑就好了吧！」<br><br>「『要在蹄板寫下這件事』……是啊，<br>小玉和稻荷說得對。」<br><br>沒錯，現在只要專注奔跑就好。<br>直視眼前的終點<br>奔向目標──<br><br>為了在不知何時到來的「那一天」，<br>自己可以在『蹄板』上<br>寫下更多的『謝謝』──"},
{index="30147",text="（哇啊啊啊啊啊啊──！！）<br><br>彷彿要連今天的烏雲也一併吹散般的歡呼聲，<br>傾瀉在了她身上──<br><br>那並不是如細雨一般溫柔的觸感，<br>而是像整個會場的熱情全部化為聲量，<br>用力打在佇立於賽場的她身上一樣。<br><br>這場競賽的氣氛隱約與平時有所不同，<br>是一場彷若鬥爭般充滿熱氣的激烈競賽。<br><br>一直追求最強的目標，不斷追逐著<br>自身憧憬的叢林口袋證明了一件事。<br><br>能夠獲得最強稱號的，<br>只有站到最後的人──<br><br>「唔喔喔喔喔喔──！！」<br><br>她在滿堂喝采之下，高聲咆哮，<br>宛如要將天空撕裂。<br><br>（哇啊啊啊啊啊────！！！！）<br><br>歡呼聲還沒有歇止。<br>由撬開新時代門扉的她所創造出的這場競賽，<br>其震撼強烈到足以吸引人心──"},
{index="30148",text="良辰吉時。<br>我拾起色彩繽紛的鍛帶<br>將其一圈又一圈捲在手上，等著某人的到來。<br>逐漸接近的腳步聲，<br>聽起來比平常還要愉快、還要奇特。<br><br>「你在興奮什麼啦。<br>真的是……笨蛋。」<br><br>我從薄紗的縫隙間，<br>可以窺見她幸福洋溢的笑容……<br><br>「真是的，你怎麼比我還開心啊？<br>……明明只是要與決勝服<br>立下誓言而已……呵呵。」<br><br>我可以理解這股心情。<br>畢竟今天的我可是最耀眼的呢。<br>不過，你應該也很清楚吧。<br>……清楚我絕對不會僅止於此而已。<br><br>沒錯……今天是良辰吉時。<br>翻開雪酪色薄紗的時刻只有那一瞬間。<br><br>「留待以後再讓我看見你最棒的笑容吧。<br>……我們的終點還很遙遠呢。」"},
{index="30149",text="終於來到這裡了呢。<br>給你五個乖寶寶花章吧。<br>大朵的乖寶寶花章、小朵的乖寶寶花章，<br>這裡有著許許多多不同的花朵。<br><br>一路上發生了好多事，我們也都一一經歷了呢。<br>親友之間毫無仁義的競賽。<br>小真的漫畫化作品<br>創下接近百萬套的銷量紀錄。<br><br>啊，我交給你的小真娃娃<br>現在過得好嗎？<br>接下來還有很多娃娃在等著，<br>建議你先準備好放的地方。<br><br>掰著手指回首過往，<br>才發現往事已經逐漸多到兩隻手也數不完了。<br>我想再過一陣子，就算加上腳趾頭，<br>恐怕也會不夠用吧。<br><br>……哎呀哎呀？<br>看你一副不知所措的表情，像是被獵人抓住一樣。<br>唔唔，你都忘記了啊。<br><br>那還真可惜，只好沒收你的乖寶寶花章了。<br>用橡皮擦把它擦一擦……<br>這樣就輕鬆擦乾淨了。<br><br>不過請放心。<br>只要再從小朵的乖寶寶花章開始就好了。<br><br>別擔心。你跟我一起。<br>一起創造新的回憶吧。"},
{index="30150",text="「唉～要是可以用這傢伙飆一下，<br>我就真的滿足了啊。」<br><br>伏特加忿忿不平地瞪著<br>一望無際的藍天。<br>看她早已熱好了引擎，<br>甚至忍不住想往地板踏的樣子。<br><br>「……嘿嘿，乾脆就這樣騎出去吧！<br>有種不顧一切逃離的感覺啊！」<br><br>「有時候沿著海岸兩人共乘，<br>看著地平線飛快地消失在眼角餘光裡；<br>有時候在夜空之下，<br>只有排氣管聲的陪伴便騎到天涯海角──」<br><br>就在那個時候，附近一帶響起了教堂的鐘聲。<br>那是宣告著夢中旅程劃下句點的音色。<br>伏特加別開瞪著藍天的視線，<br>露齒而笑。<br><br>「──唉，就只是做做夢罷了。<br>現在我想追尋的東西實在太多了，<br>光是在現實（這裡）就用盡全力了嘛。」<br><br>「……好，決定了！<br>保持著與此刻一成不變的我們，<br>總有一天絕對要放手去做。」<br><br>「挑一個稀鬆平常的日子、<br>挑一個稀鬆平常的地點──<br>到那裡像笨蛋一樣開懷大笑吧。<br>……約好囉！」"},
{index="30151",text="因為呀，我一直很期待嘛。<br><br>只要我抬起頭，你就在我的身邊。<br>只要我一笑，你便會回以我笑臉。<br>要是我開心地拉著你的手，<br>你就會露出一副拿我沒轍的表情。<br><br>好想再繼續看下去。好想再繼續玩下去。<br>可是啊，眼皮……好重哦……<br><br>「人家下次啊……會好好練習<br>該怎麼……熬夜的……」<br><br>……約會的後續，就在夢裡相見。"},
{index="30152",text="──實在太戲劇性了。<br>與其說是競賽……<br>不如說是在看一場歌劇。<br><br>歡呼聲、喝采聲，<br>彼此交纏，逐漸結合，最後化為歌聲。<br><br>沒錯，這是篇共計八幕的偉大敘事詩。<br>而那正是所有演員<br>齊聚一堂的大結局（grand finale）──<br><br>「現在就讓我在這裡重新宣布一次吧！<br>我就是『世紀末霸王』！！」<br><br>啊啊，我聽見歌聲了──<br>聽見那讚頌達成不朽成就的人──<br>讚頌世紀末霸王的歌聲！"},
{index="30153",text="真希望這個夜晚能夠一輩子持續下去。<br>波浪輕撫的沙灘閃閃發光，<br>與白天的模樣簡直有著天壤之別。<br><br>如同大海與繁星一般，<br>絕對無法交錯的湛藍與亮黃，<br>就好像盛裝了一杯夜晚似的。<br><br>象徵兩人的無酒精調酒，<br>杯裡的碳酸冒出清脆的聲響──<br><br>原本熱鬧又嘈雜的海邊，<br>此刻也彷若在安撫著灑落的月光般輕拍著岸邊。<br><br>我總是忍不住認為，<br>自己必須要比任何人都來得耀眼。<br><br>不過如果跟妳在一起，<br>我就可以只要做自己……<br><br>在海潮聲中，<br>摯友那倒映在雙眼裡的笑容，顯得比任何人都溫柔。<br><br>今晚的月亮，<br>彷彿太陽一般溫暖了兩人。"},
{index="30154",text="哎呀，這是到海邊時的照片吧。<br>妳們去玩海上拖曳傘了啊。<br>看起來真是玩得不亦樂乎呢。<br><br>對啊對啊！<br>大海非常透明，從空中往下看，<br>那些魚都像寶石一樣，超漂亮的！<br><br>海豚也跳得好高，<br>都快可以碰到帆傘了！<br><br>結果太陽她興奮到手腳一直亂揮，<br>還把海鷗都引了過來耶。<br><br>呵呵呵，不過話說回來……<br>妳的表情真是不錯呢，善信。<br><br>那天真無邪，就像是忘懷重力<br>盡情飛翔的海鳥一般自由的笑容……<br><br>啊哈哈……嗯，我鼓起勇氣一飛起來，<br>自由就變得更寬廣了。<br><br>呵呵，對了，<br>這張照片是怎麼拍出來的呢？<br><br>就太陽她的手機被海鷗搶走啦～<br>可是太陽她不是跟誰都能打好關係嗎？<br><br>最後海鷗就把手機還給她了啊～<br>結果才發現被拍了好幾張這種照片。<br><br>海鷗跟太陽<br>到底是何方神聖啊……！？"},
{index="30155",text="教室裡的女孩子們，<br>一邊翻閱著時尚雜誌，一邊有說有笑。<br><br>而我在今天也從教室的角落<br>看著同學們的交談。<br>我自己也不是真的完全沒有興趣。<br><br>實際上，我很嚮往能成為引領潮流者，<br>甚至也偷偷追蹤那些人的社群平台。<br><br>可是我總覺得<br>那不是自己這種人有資格踏入的地方，<br>所以現在只是旁觀而已。<br><br>就算真的踏進去了，要是自己突然<br>變了一個人，不知道大家會怎麼想──<br>「盲目追隨流行」「不自量力」<br>我會一直忍不住思考起這些事。<br><br>（叮咚♪）<br><br>手機傳來通知，<br>告訴我喜愛的引領潮流者更新了社群平台。<br><br>「嗯……？咦！？<br>這是太陽同學！？」<br><br>映入眼簾的是總開朗無比又充滿朝氣的太陽同學的照片。<br>可是，今天卻不太一樣。<br>照片上的她看起來很成熟，有別於以往的樣子──<br><br>「今天的我跟平常不一樣！<br>心情煥然一新，超嗨的～！」<br><br>太陽同學的表情跳脫了以往，<br>在清爽中又帶有一點豔麗。<br><br>我可以感受到她享受改變的心情──<br>享受讓其他人看見與平常不同的自己。<br><br>我一直覺得這是有點恐怖的事情。<br>我要不要也試著稍微改變下自己呢……？<br>只要一點點就好，先從小地方開始……<br><br>抬起頭來，<br>我看見同學們翻著雜誌，<br>看著裡面的UG特輯聊得很開心。<br><br>「欸，我可以……跟妳們一起看那本雜誌嗎？」"},
{index="30156",text="……人生的確不是<br>只會遇到開心的事呢。<br>但是世上的所有的一切<br>都不可能只會開開心心的吧？<br><br>在比賽上會被其他人追過、<br>會被拿來和其他人比較……<br>如果想在一件事情上努力，<br>那不管再怎麼喜歡都會變成一場苦難。<br>一旦放棄，那就結束了。<br>但是這樣就不有趣了對吧？<br><br>最重要的啊，是要持之以恆。<br>只要持續下去，一定會有好事發生。<br>不但會發生愉快或開心的事情，<br>而且也會變得有趣起來哦。<br><br>只要不放棄，繼續跑下去。<br>哪怕跑到滿身泥濘，還是繼續跑下去。<br>這麼一來便也不會輸給四次的彎道。<br>就算到了最後的直線，也一定能獲勝呢。<br><br>你看，就像今天的我一樣哦。"},
{index="30157",text="……有人將我捧了起來。<br>連同我棲息著的世界，<br>用那溫暖的手心捧了起來。<br><br>哪怕不被任何人理解也無妨。<br>我的世界並非他人所想像的樣子，<br>既不灰暗、也不寒冷、更不孤獨。<br>所以，誰都不要來打擾我。<br>我只有在這裡才能夠呼吸到空氣。<br>因為外面的世界會讓我變得很痛苦……<br><br>但那雙手心並沒有打算<br>將我帶離我的世界。<br>它彷若不讓我的世界有任何一點流失般，<br>安穩地包覆了起來。<br><br>我今天也棲息在這個世界裡。<br>然後，我會看見眩目的光芒。"},
{index="30158",text="嗯？你在看什麼？<br>啊！這不是海灘派對的<br>時候的照片嗎！<br><br>那個時候真的好開心啊～！！<br>又是玩沙灘排球玩得超開心，<br>又是吃了一堆烤肉，<br>然後在看完慢慢落入大海的夕陽後，<br>一起玩煙火玩到不亦樂乎！<br>最後大家還一起仰望星空！<br>就連速子跟咖啡也都笑得超開懷的耶。<br>啊～好想再辦一次哦～！<br><br>……嗯？<br>啊哈哈哈！別擺出那個表情嘛～！<br>海灘派對確實是<br>結束了沒錯啦～<br>不過留下最棒的回憶的過程，<br>可不會那樣就結束了對吧？<br><br>繼續把日子用力過下去！<br>不只是夏天，春天秋天冬天都一樣！<br>接下來所～有的季節都要過得很充實！！"},
{index="30159",text="嗯，辛苦了。玩得還開心嗎？<br>……我嗎？<br>呵，就如你所見。<br>老實說，我也沒有想過，<br>自己竟然有辦法變得這麼開放。<br><br>遇見陌生的自己。<br>與無法取代的他人邂逅。<br>這些如奇蹟一般的體驗<br>之所以能這麼容易就發生，<br>或許也是「這個季節」<br>才有的特色呢。<br><br>對了，我都忘了要乾杯呢。<br>敬這個季節……敬這段邂逅。乾杯。"},
{index="30160",text="「彌生，妳還記得嗎？<br>小時候，我們也曾像這樣<br>一起仰望星空。」<br><br>「懷念。當時我們都向星星許願，<br>希望夢想能夠實現呢。」<br><br>「但是……<br>無論多麼強烈企盼、付出多少努力，<br>在歷經各種風霜後的今天才得以明白，<br>還是有無法實現的事情──那就是夢想。」<br><br>「所以我們必須把這些經驗傳承下去，<br>培育出能在隆尚2400m的草地上，<br>以超越所有人的速度馳騁而過，<br>立足於世界巔峰的賽馬娘。」<br><br>「宿願──即使未仰賴滿天星斗，<br>這次也一定要憑著我們自己<br>與當代賽馬娘的力量實現夢想。」<br><br>「是啊，務必要完成這項創舉。<br>……就讓我們共同目睹吧。<br>目睹日本競賽界至今<br>始終無法得償所願的景色──<br>目睹那全新時代到來的瞬間──」"},
{index="30161",text="仰望無比晴朗的天空。<br>腳下的地面雖然沉重，但沒關係。<br>今天我想在這個地方起飛。<br><br>一站上起跑位置，<br>情緒便自然地沉靜了下來。<br>我開始回憶。回憶起這一路走來的過往，<br>回憶起那些讓我站在這裡的人們……<br>──只為了摘下唯一的榮耀。<br>這個夢想已經不是我獨自一人的夢想。<br><br>跑在比任何人前方。<br>直至抵達那任誰也無法企及的地方。<br>朝著無人能及的境地──<br>今天我就要從這裡，展翅翱翔。"},
{index="30162",text="派對會場很是喧囂。<br>我即便隻身一人也無所謂，<br>因此打算安靜地待在角落，但是──<br><br>「織姬～！<br>妳不介意的話，可以陪我到處走走嗎？<br>拜託妳了！」<br><br>事情的走向不該是這樣子才對……<br>總是像顆散發出正確光芒的北極星般的她，<br>牽起了我的手，<br>把我帶到明亮熱鬧的會場中央。<br><br>如今回想起來，這座學園就是這樣的地方。<br>既明亮，又熱鬧得令人感到吵雜，<br>每當我回過神來，總是會有人在身邊。<br><br>「拍一張大家的笑臉……<br>他們說要拍紀念照耶！<br>啊哈哈，好擠唷！<br>織姬覺得很癢？<br>我也是，呵呵！」<br><br>這座學園裡總是充滿著歡笑聲，<br>今後想必也一直都會是這樣──"},
{index="30163",text="如果想看見「出其不意的勝利」的話……<br>大概就得選中山慶典了吧。<br>那個賽馬娘給人的感覺不就是那樣嗎？<br>反正這是個無法實現的夢想。<br>如果能夠得償所願，<br>還不如去期待更加充滿夢想、更有趣、<br>更令人大吃一驚的「那些對象」……<br>要有樂趣多了呢。<br><br>──說是這麼說啦，<br>但我也不過是在開賽前故作鎮定，<br>裝出一副自己經驗老道的樣子罷了……<br><br>哎呀哎呀，<br>只要等到真正親眼見識到<br>「那個」的當下，<br>我想是人都應該說不出什麼像樣的感想。<br><br>來了！上吧……！！<br>難道……<br>妳終於要實現我的夢想了嗎……！？<br>拜託了，拜託了啊……！！<br><br>──加油啊！！！！！<br><br>「沒錯，這樣就對了。<br>輸贏現在才要開始──」<br><br>「把多餘的事情全都忘掉，<br>期待那空前絕後的夢想吧！！」"},
{index="30164",text="中山的乾枯草地上，<br>怪物的尾段加速還在提升。<br>以兇猛之姿展現出令人臣服的壓倒性力量，<br>支配了2500公尺的戰場上迎來的高潮。<br><br>那是無人能及的奔馳。<br>是擊潰了無數心靈的威脅。<br><br>已經追不上了。<br>已經無法匹敵了。<br>任誰都足以意識到這股威嚴。<br><br>然而。<br><br>「──還沒完。」<br><br>一道影子從後方逼近。<br>踏著強力的步伐奮力追趕，<br>試圖追上前方怪物的背影。<br><br>絕不放棄的心。<br>專注凝視前方的雙眸。<br><br>──不屈的靈魂翩然搖曳。<br><br>「來吧……單挑的時間到了！」"},
{index="30165",text="「來，在靈魂複寫機前面整隊！<br>為了在大祭典上<br>高舉我們那輝煌的覺悟！」<br><br>「Yes Ma'am!<br>那我要站在正中央！」<br><br>「我要排在妳旁邊！<br>快，克莉斯也過來吧。」<br><br>「──知道了。」<br><br>「喂，不要把我夾在聒噪的人中間。」<br><br>「不，我不會君臨那裡。<br>我要成為幻影籠罩妳們！<br>賢者注定要創造我的虛像！」<br><br>「……跟妳說話好累。」<br><br>「呵呵，大家零零散散的。<br>真是奇怪的聚會呢♪<br>不過，或許就是這樣才有趣。」<br><br>「沒錯，充滿個性、令人愉快的一群人！<br>比起『幸運女神的喝采』，<br>改叫「零零散散劇團』說不定更合適！」<br><br>「哦，企圖做出改變的映襯嗎？<br>要賭上名譽的話，我來當你的對手！<br>我會用鐵鎚制裁叛亂的使徒！」<br><br>「快點拍啦！！」"},
{index="30166",text="寫劇本這麼驚人的事情，<br>我根本做不到。<br>到了明天，肯定就會發現<br>比之前寫的故事更好的東西。<br><br>所以，與其面對稿紙，<br>我寧願縱身躍上用紙摺成的船。<br><br>航向遼闊的大海、什麼也沒有的水平線。<br>要做的只有一件事！高歌歡笑吧！<br><br>在某處與人相遇時就舉杯同慶！<br>那不就是人生的樂趣嗎？<br><br>我才不要走向結局。<br>Weave an endless story!<br>我要在我的故事中勇往直前！"},
{index="30167",text="「噯，克莉絲。<br>臉上的傷真的是化妝化出來的吧？<br>看起來非常逼真……」<br><br>「──這是貼紙。<br>妳看──輕輕鬆鬆……就能撕下來。」<br><br>「哇～好酷喔！我也想貼貼看♪<br>可以借我一下嗎？<br>把這個像這樣貼上去……」<br><br>「……嗚……嗚嗚……為什麼？<br>為什麼我是假的？<br>我也要跟大家一樣。<br>所以，拜託了……克莉絲──」<br><br>「唔……怎麼了――沒事吧？」<br><br>「把妳的命交出來──！！」<br><br>「美妙……！」<br><br>「啊哈哈哈哈！抱歉♪<br>不過，很有萬聖節的感覺吧？」<br><br>「……對了！<br>也對其他人試試吧♪」<br><br>5分鐘後，美妙姿勢被訓斥了一頓，<br>尤其空中神宮更是氣得怒不可遏。"},
{index="30168",text="（前奏）<br><br>哈～～～～嘿咻、喝啊<br>大船搖搖晃晃，啟航了<br>我的巨大寶船<br><br>滿載夢想和黃金，搖搖擺擺前進<br>航向目的地，聽著海浪聲<br>哈～嘿呦<br><br>狂暴的大章魚，聽聽這聲音<br>石狗公女士，好好看著吧<br>永不沉沒的大船此刻出航啦<br><br>（☆）出發吧，前進前進，黃金船<br>挺過大浪與漩渦<br>船頭所見的是無盡的夢想<br>哈～嘿咻、嘿咻<br><br>大船搖搖晃晃，繼續航行<br>承載大家夢想的巨大寶船<br><br>環遊世界，輕輕鬆鬆<br>登陸月球，易如反掌<br>讓大漁旗在宇宙飄揚吧<br><br>（饒舌）慶典放手一搏<br>終究是浪漫主義<br>敵不過我的索蘭船歌<br>奪下世界第一，燃放盛大煙火<br>咚咚、咚咚、咚咚、咚咚<br><br>（☆）重複<br><br>哈～嘿咻、嘿咻<br>哈～嘿咻、嘿咻……<br>（漸弱）"},
{index="30169",text="「唔……快要上台了～！<br>小帝，妳不緊張嗎？」<br><br>「當然會有點忐忑不安……<br>但我跟妳一定沒問題。<br>照著練習來的話，肯定會博得熱烈掌聲！」<br><br>「妳、妳心臟真大顆……<br>我覺得有種跟比賽不同的緊張感……<br>嗚嗚，冷靜不下來！！」<br>（動來動去！）<br><br>「啊啊！小鶴，不可以亂動！<br>人家都幫妳穿好衣服了！」<br><br>「啊，腦袋變得一片空白！<br>感覺臉頰也越來越僵硬……<br>放鬆一點、放鬆一點！」<br>（啪啪！）<br><br>「哇，這次是粉底掉了……！<br>小鶴，禁止妳再亂動了！<br>來，跟我一起深呼吸！」<br><br>「咦……深呼吸……？」<br><br>「想像妳要演的角色，配合我──<br>吸──吐──」<br><br>「吸──吐──<br>放輕鬆……表現出神祕感……<br>悠然地……露出神秘的微笑……」<br><br>「……嗯嗯！就是那個表情！」<br><br>「……呵呵。<br>『邁步尚見步伐惴惴橫生』──如何？」<br><br>「──『嗟乎，左掌舉措亦是多有瑕疵。』！<br>耶嘿嘿，跟我跳舞就要這樣才對！<br>來吧，該我們上場了！」"},
{index="30170",text="首先，輕輕收起下顎。<br>仰望天空，挺直脖子。<br><br>抬手時要保持平穩。<br>就像眺望遠方岩石上的小鳥。<br><br>身軀猶如風雨之中的竹子。<br>雖然柔軟，但根部屹立不搖。<br><br>而扇子要當作是自己的手。<br>從手指、扇骨到扇尖都不能疏忽。<br><br>「――到這邊聽得懂嗎？」<br><br>我的話語<br>扎根於妳，與妳共存。<br>當妳舞動時，<br>我也在心中一同起舞。<br>所以我──<br><br>「徒弟，我的徒弟啊。<br>練習的時候到了，過來這裡吧。」<br><br>將一切，都託付給了妳。"},
{index="30171",text="――今年又到了駿大祭的時候。<br>打從在狹窄舞台上翩然起舞的賽馬娘們吸引了<br>我以來，我已連續來看了好幾年，從不缺席。<br>那麼，今年能看見怎樣的「酬神劇」──<br><br>「──哇哈哈，真開心呀真開心！」<br><br>「啊──！？」<br><br>我大吃一驚。<br>這不是我所知道的演技。<br><br>台詞說得不熟練，<br>演出帶著稚氣。<br>跟我看過好幾次的「酬神劇」完全不一樣。<br><br>「真……真是太不像話了……！」<br><br>這是現代風的改編，還是即興演出？<br>不管怎樣，我實在難以接受。<br>我大失所望地走向出口──<br><br>「啊啊，真開心呀～真開心～♪」<br><br>但是。<br>她的劍舞不知道為什麼<br>在我的腦海揮散不去。<br>明明跟往年無法相提並論，這是為什麼？<br><br>我猶豫了一下慢慢轉身，<br>正好到了精彩的地方。<br>認真的眼神、額頭上的汗珠。<br><br>「縱使未能繼承吾師技藝，<br>吾師授予吾如此悅樂，<br>亦為甚善之人！」<br><br>手中緊握的劍俐落地劃過空中。<br>她的回眸一笑猶如盛放的櫻花──<br>那一瞬間，我的童年時光浮現腦海。<br><br>胡鬧卻拚命的兒時歲月。<br>那些片段如同地層般堆積起來。<br>過去的自己漸漸與眼前的女孩重疊──<br><br>「原來如此，所以才選了這女孩。」<br><br>我沉浸在舞蹈和樂聲之中。<br>我隱約有一種預感，<br>明天也會有人從她的表演得到力量。"},
{index="30172",text="「今天看棒球賽，辛苦了。」<br><br>＞辛苦了！真的非常開心！<br>＞（「感謝！」的貼圖）<br><br>「那真是太好了。」<br><br>「途中我可能有些失態，<br>因為今天的比賽<br>實在太激烈了。<br>畢竟從9局下半落後6分<br>急起直追的場面，<br>相當難得一見。」<br><br>「雖然我對這些不太了解，<br>但坐在附近的叔叔是這麼說的。」<br><br>「尤其是同分的跑者拚命盜壘，<br>以及後來的強迫取分<br>非常精彩。<br>在職棒比賽有勇氣採取這種攻勢，<br>還有成功執行戰略的技術，真令人佩服。」<br><br>＞原來如此，說得很對！<br>＞（「學到了」的貼圖）<br><br>5分鐘後……<br><br>「抱歉剛才打了很長一段話，<br>總之，我度過了非常有意義的時光。」<br><br>「有機會的話，一定要再去一次。<br>雖然不太懂棒球，<br>但不介意的話，我可以陪你去。」<br><br>「（Victories球團最棒！的貼圖）」"},
{index="30173",text="在名為賽道的五線譜上<br>一步步刻下蹄跡（旋律）。<br><br>「呵呵……這場比賽<br>正是esultazione！」<br><br>那便是她所注視的東西。<br>那便是她所愛的東西。<br><br>Obbligato?<br>Accompagnamento?<br>──扮演的角色並不重要。<br><br>「來吧！開始合奏了！」<br><br>一心享受重疊的蹄跡吧！"},
{index="30174",text="今晚是「目白聖誕夜」……<br>包含我在內的目白家的賽馬娘<br>為了支持目白的各位所準備的<br>特別之夜──<br><br>「歡、歡迎來到『目白聖誕夜』！<br>接待處在這邊！」<br><br>「咦……想跟我拍照嗎……！？<br>……好、好的，我知道了……<br>……笑、笑一個。」<br><br>所以，不擅長跟人來往的多伯<br>也鼓起了很大的勇氣<br>接待各位來賓。<br><br>「嗯，多伯，妳很棒……<br>雖然臉頰的肌肉還有點僵硬，<br>但妳的應對相當得體！」<br><br>一開始偷偷看著多伯時，<br>還很擔心她會不會很辛苦……<br>這樣看來，<br>也許我不必離開自己負責的崗位……<br><br>「好棒的夜晚……今年竟然能從目白家<br>收到這樣的禮物……」<br><br>「……我們大家都盡全力做準備，<br>希望能營造一個美好的聖誕節。<br>只要各位能留下一點點快樂的回憶，<br>我們就很開心了。」<br><br>多伯用自己的話訴說想法，<br>即使面對初次見面的貴婦也毫不怯場。<br>……不知不覺間，<br>我的顴大肌放鬆下來。<br><br>是啊，多伯就是這樣一個體貼的孩子。<br>在為了別人、<br>為了大家著想的時候──<br><br>能夠鼓起勇氣，<br>往前踏出一步。<br><br>「……加油喔，多伯！」"},
{index="30175",text="「拉茉奴大人，午餐已經準備好了。<br>……拉茉奴大人？」<br><br>……在敲了門卻仍舊得不到回應後，<br>我明知這樣不禮貌，還是打開了小屋的門。<br><br>只見拉茉奴大人正在畫畫。<br><br>那是一幅我無法理解──<br>也不打算讓旁人理解的抽象畫。<br><br>我曾聽同為女僕的其他人說過，<br>拉茉奴大人以前雙腳纖弱，<br>度過了一段無法參加訓練的冬季時光。<br>當時她所畫的就是抽象畫。<br><br>氣焰、<br>陶醉、<br>炙熱、<br>憂鬱──<br><br>將自己的感受隨心所欲地宣洩在畫布上，<br>拉茉奴大人的作品就像她本人一樣，<br>美得無法形容。<br><br>那麼，為什麼？為什麼時至今日，<br>她卻又再次提起了畫筆──<br><br>「……跟那時相比，遠遠不及。<br>不過，這倒也是──<br>因為，現在我能去見自己所愛。」<br><br>……我不知所以地屏住呼吸。<br>甚至不明白自己被什麼給震懾住，<br>只是著了迷地看著美麗的她。<br><br>「雪停了呢。<br>來談談愛吧。」<br><br>拉茉奴大人喃喃地說出那句話後，<br>便靜靜地走出了房間。<br>……然後，留下來的只有<br>未能完成工作的我，以及──<br><br>她在潔白畫布上<br>畫下的青翠新綠。"},
{index="30176",text="那是接近聖誕節的某一天的事──<br><br>「唔～東西這麼齊全，<br>讓人好猶豫該選哪一個呢～」<br><br>「就是說啊……雖然我想雷恩她不論收到什麼<br>禮物都會很高興……但既然要送，還是送一個<br>能讓她收到時會由衷感到開心的更好對吧。」<br><br>「這樣的話，蹄鐵怎麼樣～？<br>以前我挑蹄鐵的時候，<br>雷恩姊姊很有耐心地陪我逛喔～」<br><br>「所以，這次換我報答她。<br>我想用心地幫雷恩姊姊<br>仔細挑選蹄鐵。」<br><br>「這樣啊。雷恩等著妳挑好蹄鐵……<br>呵呵，真像她的個性。」<br><br>「……在我小的時候，<br>雷恩也曾在打雷的夜裡握著我的手。<br>明明她不喜歡熬夜，<br>卻為了我一整晚沒睡……<br>這一點我真是比不上她。」<br><br>「要送什麼才能報答她呢……<br>助眠用品之類嗎？<br>但我覺得雷恩睡得很好──」<br><br>「本店將在30分鐘後打烊。<br>由衷期待您再次光臨。」<br><br>「咦，已經這麼晚了！？<br>……呃，怎麼辦……<br>比想像得更難決定……」<br><br>「沒關係的，多伯。<br>要表達謝意，就得花時間。<br>不這樣的話，<br>是沒辦法充分傳達感激的～」<br><br>「……呵呵。也許妳說得對。<br>那麼，明天再到處逛逛吧。」"},
{index="30177",text="比布魯斯跑了起來。<br>雖然記者們還想多問幾句，<br>但他們立刻意識到她不可能<br>靜靜地待在這裡，只好苦笑。<br>她本該疲憊不堪的腳步卻很輕盈，<br>正是因為她視線前方看見的人。<br><br>「噯噯噯，姊姊～～～！<br>有看到人家衝過終點的那瞬間嗎！？<br>是第一名！是第一名哦！<br>人家真的贏了！」<br><br>極峰百感交集地迎接<br>徑直奔向自己的天真妹妹。<br><br>「比布魯斯……謝謝妳……！<br>最後的尾段加速真的、真的好厲害。<br>今天妳讓我看見了<br>在我所無法觸及的那7cm……<br>前方的景色。」<br><br>「耶嘿嘿～再多誇誇人家～～～♪」<br><br>「……直到最近都覺得<br>妳是愛撒嬌又可愛的妹妹，<br>但妳卻在不知不覺間變得這麼強了呢。」<br><br>「畢竟人家是好勝出名的姊姊的妹妹嘛！<br>既然決定要贏，就一定要獲勝！<br>啊，但就算變強了，<br>『可愛的妹妹』這一點還是不會變喔♡」<br><br>「呵呵呵，是啊。<br>我也想多看看強大又可愛的比布魯斯……<br>繼續大展身手呢。」<br><br>「嗯！<br>我今後還會拿下許多勝利哦！<br>不論是面對重大賽事，<br>或者是碰上許多強敵！<br>到時候姊姊妳可要<br>更加更～加地誇獎人家哦♪<br>好嘛好嘛，我們說好囉♡」"},
{index="30178",text="「大鳴大放，向外大幅偏移了！<br>這可是嚴重失誤！！」<br><br>劃過空氣的風聲，<br>混雜著觀眾的騷動聲。<br><br>感覺自己的身體<br>簡直不屬於自己。<br><br>（我失去冷靜了嗎……！？）<br><br>不，這又是不同的感覺。<br>不是被緊張吞噬，<br>而是從體內深處湧現的衝動──<br><br>「喝啊啊啊啊啊啊啊！！」<br><br>「大鳴大放從外圈衝上來！<br>大鳴大放竟然從外圈來了！！」<br><br>沒錯……這是流淌在我體內的血脈衝動。<br>身為一族結晶的自豪感。<br>我在激勵著自己，<br>展現出「最強」的樣子……！<br><br>「原來她有著如此強大的實力嗎！？<br>大鳴大放！！」"},
{index="30179",text="花手水。<br>水面上的繁花，將離春天的新芽<br>還很遙遠的新年點綴得色彩繽紛。<br>那美麗的景象，<br>令我們兩人一時看得入迷。<br><br>願望將會綻放──妳輕輕說著。<br>讓它綻放吧。<br><br>手水鉢盛滿無數花朵。<br>──每一朵花都代表一個願望。<br>在我所走的「里見」之名下。<br><br>滴答、滴答落下的水珠<br>讓水面蕩漾起漣漪。<br>我想起曾幾何時從臉頰滑落的淚水。<br>未能綻放的無數花朵。<br><br>就由我來讓這一切綻放吧。<br><br>在這一生只有一次、最為華麗絢爛的舞台上。<br>我必定會讓願望之花盛放。<br>如同這美麗的花手水。<br><br>「好。一定要讓它們綻放。」<br><br>妳堅定地點點頭。<br>臉上的笑容猶如灑在花蕾上的<br>溫暖陽光──"},
{index="30180",text="賽馬娘──<br>她們背負著來自另一個世界的名字，<br>有些名字富含意趣，有些代表著光輝歷史，<br>繼承那份靈魂──她們就是為了奔跑而生。<br><br>而在經過無數次比賽後，<br>她們自身也終將被刻劃為歷史。<br><br>「我要成為日本第一的賽馬娘……！」<br><br>與2位母親立下約定──<br>懷著成為「日本第一」的雄心壯志，<br>離鄉背井的少女與勁敵們<br>在賽場奔馳，經歷無數失敗與勝利，<br>最終實現了夢想。<br><br>「就算這樣，我也會拿下勝利。」<br><br>追趕「皇帝」背影的「帝王」<br>即使經歷好幾次失敗，<br>依然不屈不撓地振作起來，<br>向一同奔跑的朋友、<br>支持自己的勁敵<br>展現了奇蹟。<br><br>「因為大家說過……<br>想要看我奔跑的樣子。」<br><br>少女崇拜永不氣餒的「帝王」，<br>和立下約定的好友<br>一起奔赴比賽的世界。<br><br>儘管曾對自己的夢想感到迷惘，<br>但最終找到了自己的定位，<br>成為了大家所愛的<br>祭典少女。<br><br>然後──<br><br>「啊，這邊，特別週！」<br><br>「讓、讓妳們久等了～！<br>為了提起幹勁而先墊墊肚子，<br>結果意外地好吃……」<br><br>「真是的～比賽要開始了喔？<br>──對了！<br>既然這樣，要不要賽跑到圍場？<br>比比看我們之中誰跑得最快吧♪」<br><br>「啊，好像很有趣！<br>特別週，要不要參加呢？」<br><br>「當然是求之不得！<br>雖然我是最後到這裡的，<br>但這次我一定會第一個到終點～！」<br><br>「那麼──預備～開始！！」<br><br>她們的軌跡，現在仍在繼續。"},
{index="30181",text="「接下來是『於是成為了大家的』～！<br>大家跟著渦輪一起來吧──！！」<br><br>「點燃夢想的火焰～<br>敲響衝線的心跳～♪」<br><br>「陷入絕望也要向前邁進GO！<br>……呃……？呃呃，<br>碰上極限哼哼哼～～♪<br>啦啦啦啦～♪渦輪的奔逃！！」<br><br>「（哎呀……渦輪，<br>是不是忘詞了？<br>萊斯、素質，<br>輪到我們出手了！）」<br><br>「（嗯，幫她一下吧！<br>練習時，渦輪也常常忘記<br>A段和B段的歌詞……<br>這兩段就用樂器帶蓋過吧！）」<br><br>♪♪♪～～～♪～♪♪～<br>♪♪～～♪♪♪♪～♪♪<br>沙沙沙沙沙沙！<br><br>「唔唔唔，音樂變大聲了！<br>是要更加炒熱氣氛的意思吧！？<br>好──！」<br><br>「Go～Go～Let's go！哦～哦哦～哦！<br>Go～Go～Let's go！渦輪很強！<br>Go～Go～Let's go！唔哦～哦哦哦！<br>衝啊、衝啊，Go～Go～渦輪全開～～！！」<br><br>「不是，為什麼反而唱得更大聲了！？<br>而且歌詞還一樣都是錯的！」<br><br>「呵……加快節奏是吧。很好！<br>渦輪，我就跟上你的熱情！！」<br><br>「唔，好快……但我必須跟上！<br>撐住，萊斯！」<br><br>「妳們的手速好扯！話說太快了太快了！！<br>照這個節奏的話──」<br><br>「不不不管幾次，無論幾次！<br>火力全──────開！！<br>不不不管、幾次！<br>無論幾次……吁、吁……！<br>啊啊啊啊我……不會……投降的啦啊啊！！<br>噫～哈～吁……噫噫噫噫！」<br><br>「唔哦哦哦哦哦哦哦哦哦哦渦輪，<br>絕不會認輸啦──────！！」<br><br>「啊啊啊，我就知道～！<br>大家跟著渦輪一起失控，<br>場面就一發不可收拾了──！！」"},
{index="30182",text="映入眼簾的是耀眼的光芒。<br>在司空見慣的故鄉會場中，<br>有著熟悉的人們的面容。<br><br>「不管是唱歌還是舞蹈，<br>都變得非常厲害呢……！<br>不愧是我們的活招牌！」<br><br>「是啊，多虧了她，<br>也多了很多觀光客來我們這裡呢。<br>真是可靠又讓人驕傲不已啊！」<br><br>這番溫暖的話語和笑容，<br>不禁令她眼眶一熱。<br>只因那道曾經微弱的光芒，<br>如今變得如此閃耀，<br>充滿著燦爛的笑容。<br><br>「這是最後一首歌！<br>請聽──」<br><br>「『來苫小牧吧』！」<br><br>就算滿身泥濘，<br>就算被絆住腳步，<br>她今後也會不停地奔跑。<br><br>為了用這雙腳，來守護不願失去的地方。"},
{index="30183",text="小雪好像從房間裡<br>找到了製作故鄉點心的食譜。<br>「好久沒做，來做做看吧～」<br>她這麼說完後，<br>同意讓我在一旁觀看──<br><br>小雪的技術真是超驚人的！<br>不但手腳靈活動作快，還非常仔細！！<br><br>「好厲害好厲害！！<br>最後捏緊的那一下，<br>非常重要呢！！」<br><br>「小雪真的是技巧高超耶！！<br>連細節都能做得這麼漂亮，<br>太厲害了啊啊啊啊！！」<br><br>「券、券藏真是的，<br>太誇張了啦～」<br><br>「不過……謝謝妳哩，<br>我真的真的很高興♪<br>好──那我要再加把勁囉～！」<br><br>小雪做點心的時候，<br>看起來真的很開心的樣子！<br>看著她這副模樣，<br>讓我也忍不住想動手做點心了～<br>記得圍裙和頭巾就放在置物櫃裡──<br>好，我也來做吧！！<br><br>接下來就得想想做什麼了……<br><br>「啊，我想到了！！」<br><br>用腦海中浮現的畫面作為藍圖，<br>我也開始動手製作。<br>感覺好像做得還挺不錯的！？<br><br>「耳朵就這樣捏一下！！<br>然後拿一塊小紅豆餡……<br>輕～～～～輕放上去──」<br><br>「完成了──────！！！！」<br><br>「哇啊，好口愛喔～♪<br>表情笑嘻嘻的，<br>看起來是個很溫柔的點心呢。」<br><br>「耶嘿嘿～！<br>這個點心啊～就是小雪喔！！<br>看著小雪開心的樣子，<br>讓我也想一起做點心。<br>想說既然要做，那就做個小雪吧！」<br><br>「噯喲！？<br>這孩子原來是我嗎！？<br>……這樣啊，真的讓我好開心哩。」<br><br>「嗯嗯，就是這個表情！<br>果然一模一樣呢！！」<br><br>「耶嘿嘿……券藏，<br>我看著妳的表情，<br>也和妳一樣又想要做點心了。<br>我可以再做一個嗎？<br>這次要做成券藏的樣子！」<br><br>「小、小雪────！！<br>當然可以啦────！！」"},
{index="30184",text="　　　　　　　問候<br><br>身為大家的班長，<br>我將贈送給每個人飽含我平日感謝的點心！！<br>感謝──這是種美麗的心意！<br>而說到美麗，就會讓人想到櫻花！！<br>因此，我製做了<br>櫻花花瓣造型的點心！<br>而且成果的整體品質相當精美喔！<br>畢竟它可是在美麗×美麗下誕生的！！<br>　　　　　　　　　櫻花驀進王<br><br>我認為雖然只是一句簡單的「感謝」，<br>卻有著各種不同的形式。<br>「我想製作櫻花花瓣造型的點心──」<br>聽到小驀的創意，<br>讓我想到可以再稍做變化。<br>由五片花瓣組成的美麗櫻花，<br>由五種顏色組成的各種感謝。<br>請在開箱時感受美麗造型的饗宴，<br>也請期待吃進嘴裡時的滋味♪<br>　　　　　　　　　　　　北方飛翔<br><br>　　　　　　　菜單<br><br>一、感謝活力<br>　酥酥脆脆的餅乾！<br>　明亮的黃色帶來力量！<br><br>二、感謝溫柔<br>　甜蜜滋味的壽甘！<br>　可愛的粉紅色溫暖心靈！<br><br>三、感謝笑容<br>　軟嫩有嚼勁的糰子！<br>　純白友善的笑容帶來笑聲！<br><br>四、感謝嚴厲<br>　有點堅硬的米果！<br>　甜味會在之後逐漸蔓延！<br><br>五、感謝夢想<br>　加入閃亮金粉的羊羹！<br>　互相切磋，一起邁向光輝的未來！"},
{index="30185",text="「哦～復古風格的外套？<br>……哎呀，這個品牌！<br>喔，原來還有推出這樣的新款！<br>這個牌子能營造出很棒的高級感，<br>以前有跟母親聊過──沒什麼，咳咳。<br>謝謝妳，飛翔。<br>這件外套不只有著能夠襯托本帝王光芒的<br>高格調，同時又能發掘出我全新的一面。<br>……妳果然就是時尚達人呢！」<br><br>「呀～街頭風的打扮啊！<br>寬鬆的帽T搭上短褲，<br>再配上設計得有點俏皮的<br>厚底休閒鞋……唔呵呵，<br>光是討論就讓我想要快點穿出門了♪<br>真想早點讓大家看到<br>真機伶在網美景點充滿魅力的樣子～！<br>到時候，<br>飛翔要不要一起來開UG直播啊？」<br><br>「好扯……這是只有在選貨店<br>才有販售的飾品吧？<br>飛翔，妳真的對流行很敏感呢。<br>再一起交換資訊吧。<br>我也會帶一些最新商品情報<br>來給妳當作回禮的。<br>……不過說真的，妳那份深入鑽研的精神，<br>我真的是敬佩到不行耶，沒開玩笑。」<br><br>無論是妳，還是妳，<br>當然也包括我在內！<br>在我們彼此體內都沉睡著與生俱來的<br>重要原石──沉睡著那能發出光輝的源頭。<br><br>我想要將它磨亮，讓它閃閃發光！<br>若能幫上忙，<br>就會讓我無比高興。<br><br>那麼──妳好啊，新的原石！<br>要不要和我一起尋找能綻放光芒的方法呢？"},
{index="30186",text="那麼，這次會是哪些人與我交鋒呢──？<br><br>「就允許妳就近瞻仰吧──<br>瞻仰我金色的霸業之道。」<br><br>「我可是期待得很呢──<br>期待在超越所有人後，<br>一腳踹開邁向最強（頂點）之門的那一刻！」<br><br>「作為讓我證明自己的血統及強大的對手，<br>確實是能夠讓我滿意。」<br><br>「我會獲勝！在贏得比賽後……<br>就由我來開拓出后冠賽馬娘之路！」<br><br>哎呀，真是太棒了。<br>奔馳在這裡的所有賽馬娘，<br>都像鑽石一般有著璀璨光芒，<br>以及無懈可擊的強韌……<br><br>「──所以才更有粉碎的價值呢。」"},
{index="30187",text="──舉起玉杯一飲而盡吧。<br><br>激越昂揚的霸王君臨此地，<br>站上賽場的頂點踐踏一切。<br><br>她的霸業宛如藝術，<br>所經之路宛如暴風，<br>將世界染上金黃色。<br><br>敬畏、膜拜、跪下吧。<br>我等只能瞻仰她散發出的尊貴。"},
{index="30188",text="我有想要傳達的熱情，<br>有想要傳遞的感動。<br><br>所以我今天也在不斷尋找。<br><br>尋找那個夢想最能發光的舞台，<br>尋找那個靈魂最是耀眼的瞬間──<br><br>「──涼花小姐，覺得怎麼樣！？<br>我熊熊燃燒的幹勁有表現出來嗎！？」<br><br>「嗯，表情很棒喔。<br>隔著畫面都能感受到<br>愛爾菲的熱忱。」<br><br>「好，這次的影片<br>就採用這次的拍攝成果吧。<br>辛苦了，愛爾菲。」<br><br>「太好了！<br>謝謝妳！」<br><br>「耶嘿嘿～<br>希望大家也會喜歡這次的影片！」<br><br>「放心吧，<br>大家一定會很高興的。」<br><br>──畢竟妳是如此耀眼。<br><br>不斷散發出<br>能帶給許多人力量的璀璨光芒。<br><br>然後……<br>我的工作就是將道光芒毫無保留地帶給大家，<br>有時還則會再讓它變得更加耀眼。<br><br>「對了，涼花小姐！<br>我待會晚一點的時候，<br>想針對下個企畫和妳商量一件事──」<br><br>「哎呀，這樣啊？<br>那乾脆就這樣開個簡單的會議吧。<br>畢竟拍攝工作也順利結束了。」<br><br>「知道了！<br>要迅速俐落合情合理！對吧！」<br><br>「呵呵……是啊。」<br><br>好了，<br>今天也來打造能撼動人心的娛樂內容吧。<br><br>──攜手我最棒的搭檔。"},
{index="30189",text="牽起手，<br>夢想的起點令人心情雀躍。<br>我們一起穿過那扇門。<br><br>「我絕對會成為<br>像帝皇一樣的賽馬娘！」<br><br>「我也會跟麥昆一樣，<br>作為里見家的賽馬娘發光發熱！」<br><br>嚮往之處，讓我們明白了夢想的模樣。<br>無數的邂逅，點綴了我們的未來。<br><br>曾經只有兩人的世界變得無比廣闊──<br><br>「我先走一步了喔，小鑽！」<br><br>「嗯，我會追上的……一定會。」<br><br>分道揚鑣，朝著各自的目標邁開腳步。<br>然後，再次交會、碰撞。<br><br>「小鑽……<br>這一天我已經期待好久了！」<br><br>「我也是。不過……<br>我會超越妳，由我奪得勝利。」<br><br>「求之不得！」<br><br>──那麼，放開牽著的手吧。<br><br>為了抓住那獨一無二的光芒！"},
{index="30190",text="即使被迫面對九個月的空窗期，<br>她仍為了要讓其血脈被刻在歷史中，<br>而追求著「最強」。<br><br>「我要證明──<br>證明自己的強大能任誰都一目瞭然。」<br><br>為了以里見家的身分留下偉業，<br>並回應家族成員對她所抱持的期望，<br>而追求著「榮耀」。<br><br>「就算讓出支持度第一，<br>我也不會將勝利拱手讓人──<br>任何逆境我都會全數顛覆！」<br><br>若彼此都有追求的「理想」──<br>那勢必將爭奪競賽的榮光。<br><br>「我會讓妳輸得心服口服。」<br><br>「讓妳見識一下我完美的計畫！」<br><br>她們各自懷著激昂的心情，<br>奔馳而去。"},
{index="30191",text="「就這樣，那個成為大家心愛賽馬娘的<br>女孩化為最強的一員，<br>被人們永遠流傳下去。<br>真是可喜可賀、可喜可賀……<br><br>以上就是小萊的名作劇場♪」<br><br>「──要這麼說還言之過早！<br>要繼續下去囉，爭鳴！<br>第二章，心愛的最強賽馬娘篇開幕！」<br><br>【由小號吹奏開場小號】<br><br>「了解，『女士』！<br>登場場景的演奏就交給我！」<br><br>【節奏輕快的曲子】<br><br>「要開始囉，萊斯！<br><br>　♪用華爾滋點綴妳腳下的路。<br>　　『一、二、三』!」<br><br>「♪但是目標是第一名！<br>　　沒錯！要邁向最強的頂點！」<br><br>「♪演奏的舞曲！」<br><br>「「♪下、一、個、主角是～～」」<br><br>「來到我的主要橋段了！萊斯，<br>麻煩來段appassionato的伴奏！」<br><br>「等、等一下！<br>我沒聽說妳要搶先啊！？」<br><br>【狂亂的沙槌聲】<br><br>「唔！喝！」<br><br>【鋼琴聲】<br>【手風琴聲】<br><br>「還沒完喔！」<br><br>【玩具小提琴聲】<br>【萬籟爭鳴的哼唱】<br><br>「唔，找不到空隙……！？」<br><br>「呵呵，別害怕啊，『女士』。<br>我想跟妳來一場<br>讓人難以忘懷的ensemble！」<br><br>「過來吧！<br>依循靈魂盡情演奏妳的音樂！」<br><br>「……有趣……！<br>我就成全妳！<br>可不能讓妳一個人出盡鋒頭啊！」<br><br>【狂亂的沙槌與刮壺聲】"},
{index="30192",text="在聚集世界強者的大舞台上，<br>三姊妹的「驕傲」<br>戰勝了心愛的競爭對手。<br><br>「喂～逸逸！<br>不會讓妳到角落去的～♡」<br><br>「比布魯斯說得沒錯，駿逸。<br>主角就應該要在中間吧？」<br><br>「……沒、沒關係啦。<br>像之前那樣，妳們兩個其中一人──」<br><br>「不可以！今天的主角是逸逸的！」<br><br>──妹妹堅持不退讓。<br>因為她一直將姊姊的努力看在眼裡。<br><br>「就是啊，好好抬頭挺胸。<br>……妳不來就換我們去抓妳。」<br><br>──姊姊也不退讓。<br>因為她也將妹妹無數次挺身面對的模樣看在眼裡。<br><br>「咦……咦咦咦！？<br>等、等等……妳們……！？」<br><br>她就這樣被兩人包夾，<br>一臉看似困擾的表情染上紅暈……露出微笑。<br><br>三人用愛擁抱家人。"},
{index="30193",text="眾多充滿天分者<br>在賽場展現光輝的世代，<br>她的戰績可說是一片低迷。<br><br>在對勝利者讚賞的背後，<br>不知她經歷了多少辛酸。<br>從她滿是塵埃的背影，<br>無法一窺她的想法。<br><br>不過……<br>從拉低的帽沿中能略微瞧見她的雙眸，<br>眼裡那道充滿不甘心和憤怒的<br>火焰正靜靜閃爍著。<br><br>在面對世界的這個大舞台，<br>淡藍色的斗篷隨風飄揚。<br>像是要擺脫至今以來的鬱悶，<br>她那推翻了所有期待和預測的跑姿──<br>與曾幾何時稱霸了世界的那名賽馬娘的身影重疊在一起。<br><br>──啊啊，<br>她一定也會航向宏偉的大海吧。<br><br>像是展翅飛向遙遠的世界般，<br>鏡板點綴上了一抹蔚藍。"},
{index="30194",text="──終於一路來到這裡。<br><br>具備鋼鐵般的體格和精神，<br>毫髮無傷地克服了無數競賽的「鐵娘子」。<br><br>面對身為「華麗一族」的使命，<br>最後找到屬於自己道路的千金小姐。<br><br>無論面對怎樣的對手都不畏懼，<br>在主要競賽拿下6連勝，<br>甚至挺身挑戰「怪物」的「女傑」。<br><br>不只繼承「女王」的軌跡，在后冠路線<br>有著活躍表現，就連在「天皇賞（秋）」<br>也拿下了勝利的「女帝」。<br><br>和跑什麼路線無關。<br>表明「很強的賽馬娘就是很強」，<br>親自驗證這點的「魔法少女」。<br><br>美麗、漂亮加上無與倫比的速度──<br>追尋景仰的前輩們所留下的軌跡，<br>我才能夠一路來到這裡。<br><br>這次換我接續下去。<br>現在一定沒有問題。<br>我的意志會傳遞到后冠……！"},
{index="30195",text="白色的羽翼在夜晚的練習室飛舞。<br>這是為了某人而跳的舞。<br>充滿溫柔情感的舞。<br><br>每踏出一步，<br>就讓她更顯高雅。<br><br>每踏出一步，<br>就讓她更美得脫俗。<br><br>更邁向前方的一步，<br>超越極限的一步。<br><br>擺動那美麗通透、<br>宛如玻璃的翅膀，<br>像是飛向遠方的天空般──<br><br>──喀噹。<br><br>「──！」<br><br>「啊……很抱歉，時間到了呢。<br>我會立刻收拾。」<br><br>很快就是學園的門禁時間。<br>她露出像是帶著歉意的表情，<br>隨即綻放出微笑，<br>臉上有著符合她年紀的單純。<br>不知為何，讓人因此大大鬆了一口氣。"},
{index="30196",text="出生於同一片大地。<br>生活在同一片天空下。<br>想在同一片草地上奔跑。<br><br>妳和我之間<br>確實存在緊緊相繫的緣分，<br>儘管那段緣分很快就將消退。<br><br>希望宛如春風的妳<br>能長存暖意之中。<br>希望宛如微風的妳<br>能永遠輕輕飄盪。<br><br>重要的同期，<br>重要的時光，<br>妳的幸福，就是我最為珍視的事物。"},
{index="30197",text="用力握住「舞伴」的手，立於舞池中央。<br>熱情的音樂流淌。<br>熱烈的節奏躍動。<br>站在這個會場的所有搭檔都是競爭對手。<br><br>不過，這裡最大的競爭對手是──<br><br>「我要開始囉，小栗前輩！<br>踏步之後轉圈！！」<br><br>「──！真厲害呢……不過我也可以……！」<br><br>「唔喔──！<br>嘿嘿，不愧是小栗前輩。<br>我也不會輸的──！」<br><br>領舞與跟舞這種關係，<br>並不適合我們。<br>互相爭奪領導地位，<br>時時刻刻都不能鬆懈，<br>這種繃緊神經的感覺令人舒暢。<br><br>和比賽時競爭的熱血相同，<br>只有認真竭盡全力的同場較勁──<br>只有這個與妳正面對決的瞬間，<br>對我來說才是特別到無可取代。"},
{index="30198",text="連接「纖維狀結構」。<br>＜滋──滋──咚、滋──滋──＞<br><br>提升「增幅」。<br>　　　　　　　　　能「聽見」嗎？<br><br><br>　　　「FELT」祝福喔。<br>＜滋──滋──咚。＞<br><br>　　　　　　　　　　　　透明的Hz<br><br>　　　　因物化變動　──　認可。<br><br>將整個「RCOL」傳送。<br>＜咚、滋──咚、咚。＞<br><br>＜咚、咚。＞<br><br>　　　　　　　　　視點位置，錯誤。<br><br>　開始再次傳送。<br>　　　　　　　　　傳送，再次傳送。<br>＜咚、咚、滋──咚、咚。＞<br><br>　傳送。<br>　　　　　　　傳送。<br>　　　　　傳送。<br>　　　　　　　　　　　傳達過去。<br>＜咚、咚、滋──＞<br><br><br><br>　　新宇宙也很「高興」。"},
{index="30199",text="【4月○日　晴】<br><br>■記錄者<br>菱奇蹟<br><br>■課堂．內容<br>1～5堂：粉絲感謝祭！<br><br>■感想．反省<br>大家參加競賽都很努力。<br>小創、小希、<br>狂熱激昂的三人四腳比賽，<br>把氣氛炒得非常熱烈。<br>小竹的應援團好帥氣。<br>還有，我在陣地保衛戰也很努力。<br>覺得表現算是還不錯，<br>受到班上同學大力誇獎，<br>有種成為巨星的感覺。<br>雖然老師拿飲料來當慰勞品很讓人高興，<br>但希望下次會是冰淇淋呢～"},
{index="30200",text="一、意志堅定，必能水到渠成。<br><br>二、隨機應變，必能變換自如。<br><br>三、謹記策略也是戰鬥之一。<br><br>四、不分敵我，知己知彼。<br><br>五、萬事俱備，<br>　　必能顛覆局勢。<br><br>「──來吧，下剋上！」"},
{index="30201",text="「呵呵……<br>這時候的小進真的好帥喔～♪」<br><br>「啊？喔，是粉絲感謝祭的照片啊。<br>唔，這是什麼相簿！？<br>不用把這種照片仔細貼進相簿裡啦！」<br><br>「為什麼～？這可是小進<br>在陣地保衛戰大顯身手的照片，<br>當然會想好好珍藏啊～<br>啊，還有這張照片也是♪」<br><br>「別一直講了啦，有夠難為情……」<br><br>「妳真的變得很出色了呢。<br>不知不覺就長這麼大了……！」<br><br>「妳是我媽嗎！？」<br><br>「畢竟～<br>我一直都很擔心小進……<br>不過妳長得比我想的還要出色、<br>、還要勇敢、還要抬頭挺胸──」<br><br>「……不過就是……掩護妳讓妳方便行動，<br>這點小事根本不算什麼…………」<br><br>「小進……！<br>妳真的是好溫柔好出色～～！」<br><br>「就跟妳說不是那樣……<br>唔，妳在標籤上寫什麼──」<br><br>「啦啦♪『小進非常出色……<br>為了大家鼓起勇氣』──」<br><br>「喂，別附註這麼丟臉的內容！<br>不准貼在照片旁邊──！！」"},
{index="30202",text="喔喔，挺有模有樣的嘛！<br>果然和我想得一樣啊！<br><br>鮮紅色車身的仿賽車。<br>很適合你這個總是熱血指導我的人喔！<br><br>你終於也到了要騎機車的這天了啊。<br>嘿嘿，被你搶先一步了～<br><br>雙載？這個嘛，<br>這樣我的確是可以一起坐啦……唔──<br><br>啊，我不是不願意喔！<br>不是那樣……<br>是我比較想要和你一起奔馳。<br><br>你等著吧，<br>我就快長大成人了。<br><br>你在那之前先好好練習！<br>小心別被我超越了！"},
{index="30203",text="有個被稱為天才的傢伙。<br>有個總是看著與常人不同世界的傢伙。<br>還有個絕對不放棄勝利的傢伙。<br><br>足夠了。簡直太棒了不是嗎？<br>總算都到齊了。<br><br>──妳們很強。<br><br>嗯，沒錯，夠格當我的對手。<br><br>喂，來對決一場吧。<br>鐵欄打開就是信號。<br>破風踏地，認真較勁。<br>拚命活下去吧。靠本能嘶吼吧。<br><br>為了奪得那唯一的頂點，<br>竭盡所能。<br>喂，來比一場吧。<br><br>妳們幾個絕對夠格。<br>只要贏過妳們──<br><br>我就是「最強」的。"},
{index="30204",text="「呼哇～<br>…………哎呀？被發現了啊？」<br><br>我看到她在樹上和貓一起睡覺。<br>一臉睡眼惺忪，<br>露出淺笑的樣子真的是毫無防備。<br>無論穿著多麼漂亮的禮服，<br>還是我行我素地放鬆著自己的樣子，<br>實在讓人覺得有點奇怪。<br><br>「來吧，別只在下面看著，<br>這裡的貴賓席還空著喔。」<br><br>我爬上她輕拍的粗壯樹枝上，<br>在她身旁坐下。<br>樹葉發出沙沙的聲響。<br>陽光在林葉間灑落。<br>彷彿只有這裡的時光變得緩慢。<br><br>我輕輕地打了個哈欠。<br><br>「這種時光也挺不錯的吧。」<br><br>我隨著那道舒適的聲音微微點頭。<br><br>「我算是還挺會找出這樣的時刻喔。<br>絕佳的時間和地點，還有舒服的風。<br>只要我想找就能立刻找到。」<br><br>真棒的特技呢。<br>竟然能隨時度過這麼寧靜的時光。<br>不禁脫口而出有點羨慕。<br><br>「那這樣如何？<br>你可以像這隻貓一樣待在我身邊。」<br><br>吹來一陣強風。<br>掛在樹枝上的那條薄紗<br>就這樣隨風飛揚而去。<br><br>「糟糕……不過算啦，<br>就算弄丟也已經──對吧？」<br><br>她那在林葉間灑落的陽光中<br>看似調皮的笑容，<br>今天更加強烈地烙印在我的眼底。"},
{index="30205",text="我有不願面對的過去。<br>有不管挑戰幾次都贏不了的對手。<br>……嘗過無數次的辛酸無法遺忘。<br><br>不過，低頭放棄的話就結束了。<br>我也不會回首過往而止步不前。<br><br>頭上戴著小鳶尾花。<br>挺起胸膛，收起下巴。<br>不需要感到迷惘。<br>只要一心看著前方。<br><br>不畏懼、不懈怠，比任何人都崇高。<br>我會在這個世上大放異彩。<br>以女神（謬斯）之名發誓。<br><br>「我不會再輸給任何人。<br>不會輸給妳，也不會輸給自己……！」<br><br>我就是女王。"},
{index="30206",text="「欸欸，怎麼樣？好看嗎？<br>有像名流嗎？」<br><br>天真無邪、興奮地跳來跳去的妖精，<br>對我提出不知是第幾次的問題。<br>很好看喔。<br>我也不知是第幾次這麼回答了。<br><br>「耶嘿嘿～對吧對吧♪<br>我要穿這套決勝服（禮服）～<br>去杜拜～<br>包下一艘豪華郵輪！<br>在海上和大家唱歌跳舞，<br>還要品嚐美食～<br>然後然後，看著下沉的夕陽，<br>一起討論彼此的未來～<br>呀～～♡」<br><br>「比布魯斯，你們也夠了，<br>從剛才就一直在重複那段你問我答不是嗎？」<br><br>「姊姊別這麼說嘛！<br>畢竟不管聽幾次都很開心啊！」<br><br>她低身彎腰，水汪汪的雙眸閃閃發亮。<br><br>「我一～直很憧憬那一天的姊姊！<br>這是我好不容易才有的決勝服耶！<br>成為至高無上的名流，<br>穿上裝滿了美妙動人夢想的……<br>這套完美無瑕的決勝服（婚紗）！」<br><br>「……！」<br><br>「所以聽到我被稱讚穿起來很好看……<br>不就是最讓人高興的事情了嗎！」<br><br>下一秒，<br>純白的決勝服在藍天下輕柔飄動。<br>鑲嵌在禮服上的珍珠反射陽光，<br>照耀著可愛無比的笑容。<br>而她則帶著那抹笑容懇切地仰頭看著我。<br><br>「欸欸！<br>再說一次嘛！來，說吧♡」"},
{index="30207",text="「哇──哈哈哈！<br>大家快看！<br>這個光澤！顏色！大小！<br>不管怎麼看都是極品吧！」<br><br>「喔喔喔！<br>看起來是很好吃的胡蘿蔔唄～♪」<br><br>「就是啊！有這～麼多漂亮的胡蘿蔔！<br>要做什麼料理好呢？<br>已經開始傷腦筋了～♪」<br><br>「唔，喂喂，理事長！<br>妳就直接這樣一屁股坐在地上啊……！<br>弄得渾身是泥沒關係嗎！？」<br><br>「小事小事！我反而很驕傲！」<br><br>「這是妳們用心照料出來的成果。<br>裡面有滿滿的愛。<br>能認真面對這樣的胡蘿蔔，<br>是多麼幸福的一件事啊！」<br><br>「如果因此滿身是泥，<br>我反而非常高興！<br>身為理事長沒有比這更開心的事了！」<br><br>「來，繼續挖出來吧！<br>想必妳們的愛會塑造出自己，<br>然後帶著妳們實現夢想！」<br><br>「讚賞！來吧，年輕人，<br>把一切化為力量前進！」<br><br>「理事長……！<br>好的！我會帶著這些胡蘿蔔，<br>站上日本第一的舞台！」<br><br>「我一定會將它們料理得非常美味！<br>屆時也請理事長要來吃喔！」<br><br>「嗯、嗯！<br>我會很期待的！」<br><br>「……嗯？欸，<br>好像有人從遠處氣沖沖地跑來──」<br><br>「唔呵呵，理事長。<br>您忘了之後還有會議嗎？<br>弄得這樣全身是泥……」<br><br>「驚愕！！手、手綱……<br>各位年輕人啊，別在意我，不要回頭！<br>前進吧，繼續前進吧──！！」"},
{index="30208",text="氣息化成白霧的冬晨。<br>起床後便立刻奔往它們的所在之處。<br><br>昨天下了一整夜的大雨。<br>聽著持續嘩啦啦的雨聲，<br>她緊閉著眼睛祈求。<br><br>──嬌小的你們，<br>還請不要輸了。<br>都已經長得這麼大，<br>還請讓我看到你們結出閃亮的鮮紅果實。<br><br>比鬧鐘響起的時間更早醒來。<br>披上針織外套。<br>就算冷風吹襲臉頰，<br>她也完全不在意。<br><br>抵達的園地一片淡藍，<br>四周寂靜無聲。<br><br>她慢慢掀開積著雨水的塑膠套。<br>用像是在祈禱的心情屏住氣息──<br><br>「……啊啊，太好了！」<br><br>它們被雨水浸溼，<br>依然抬頭向上。<br><br>白色的花朵與花托<br>就好像在對她說：<br>歡迎回來。<br>我們沒有輸喔，很了不起吧。<br><br>「很冷吧，你們真的好努力。<br>已經不要緊了喔。」<br><br>朝陽逐漸增添柔和的色彩。<br>那模樣看上去就像是也為這一切鬆了<br>一口氣似的，甚是惹人憐愛……<br><br>「我們今天也一起加油吧。<br>直到成長茁壯的那一天……」"},
{index="30209",text="（這就是站在舞台中央的光景──）<br><br>手燈宛如星空般的光芒。<br>大家為我祝福的聲音。<br><br>……這就是主角。<br><br>我沒能贏得勝利。<br>明明這麼拚命努力了。<br>明明答應粉絲了。<br>沒能回應雙親的期待。<br>要是能再快一點。<br>要是能再更有持久力。<br>要是能更有意志力。<br><br>現在這些念頭都攀附在我的背上。<br><br>自己明明再清楚不過……<br><br>卻還是覺得很沉重。<br><br>氣息紊亂，腳在顫抖。<br><br>……不過，<br>這就是我一直憧憬不已的景色。<br><br>一直在他人身後翹首以盼的景色。<br><br>為了粉絲，<br>為了那些支援我的人。<br>最重要的是為了我自己！<br><br>我會背負這份意志閃閃發光！<br><br>展現主角風範──展現真正的自我！"},
{index="30210",text="「飛鷹，妳在這裡啊。<br>我找到好像很好喝的熱帶果汁，<br>請用吧。」<br><br>「我另外還借了吊床，<br>也請隨意使用。」<br><br>「謝、謝謝妳……閃耀，<br>感覺妳好像比平常還要溫柔？」<br><br>「算是我的慰勞。<br>夏季活動和賽馬娘偶像活動同時舉辦，<br>真是辛苦妳了。」<br><br>「別這麼說，不要緊的。<br>賽馬娘偶像基本上都很繁忙！」<br><br>「……就因為妳會這麼說，<br>我才要送點禮物給妳。」<br><br>「閃耀……嗯！謝謝妳！」<br><br>「那麼，<br>今天就好好享受一番吧！」<br><br>「畢竟還有時間，我可以幫忙<br>安排浮潛或是海灘的精油按摩喔。」<br><br>「哇，太棒了～～～！！<br>我全部都要～～！」<br><br>「啊，<br>但飛飛不想只有自己享受，<br>閃耀也要一起休假喔♪」<br><br>「呵呵……好的，<br>我會陪妳一起。」<br><br>「耶嘿嘿，太棒了♪」"},
{index="30211",text="「嗶噗嗶噗！？<br>啪嗶啪的啪啪啪啪嗶啪嗶～～」<br><br>「歷奇，什麼啊？<br>在海裡面，<br>根本聽不懂妳在講什麼～！」<br><br>「噗哈！那邊那邊！<br>有很多黃色的魚，<br>聚集在粉紅珊瑚礁附近！」<br><br>「哎呀，真的耶，好美喔。<br>簡直就像在龍宮城一樣～」<br><br>「對吧對吧！？<br>而且我這個月的幸運色是<br>『粉紅色』、『黃色』、『紫色』！<br>幸運都聚集在這裡了！」<br><br>「喔？那還少了紫色吧～？」<br><br>「銳駿，有紫色的喔～！<br>樽前的泳裝就是紫色！！」<br><br>「真是的……<br>可以別把我捲進妳的風水裡嗎？<br>幸福是要靠自己的雙手抓住──」<br><br>「啊，發現可愛的貝殼……！<br>外型好像有點像北寄貝耶♪」<br><br>「啊，妳要去哪裡！？<br>等等啊，我的幸運色～～！」<br><br>「啊哈哈，<br>有本事就來抓我啊～嘿嘿！」<br><br>「唔呵呵呵。<br>真的很開心呢～」"},
{index="30212",text="「看，拍得很好吧？」<br><br>奇銳駿在訓練員室<br>展示了她的夏季回憶。<br>一張她在玩沙灘奪旗的照片。<br><br>「大家的表情都很棒～<br>啊，記得她向我發起了好多次挑戰，<br>最後一場好像不分軒輊吧？」<br><br>「你想知道結果嗎？<br>呵呵呵，當然是『贏了』喔～」<br><br>「為了別陷入沙地，<br>要往後用力踢不是嗎？<br>你教我的事也有應用在沙灘上了。<br>真想讓你瞧瞧呢～」<br><br>「對了，說到想讓你瞧瞧，<br>也想讓你看看陽光、大海和沙灘。<br>全都閃閃發亮，很美喔～」<br><br>「不知道明年夏天能不能和訓練員<br>一起去海邊……希望可以～」<br><br>奇銳駿抬頭看向<br>遠方天空的同時打開窗戶。<br>窗外還帶有一點夏日的氣息。"},
{index="30213",text="賽馬娘用來傳達平日感謝之意的活動──<br>「春季粉絲大感謝祭」。<br>今年決定舉辦<br>名為『喧鬧GP！』 的混合競技大會。<br><br>有時在籃球場上，<br>以籃框為目標彼此競爭──<br><br>「好～！<br>看我趁現在射籃──呃，<br>往昔！？妳什麼時候跑到這裡的！？」<br><br>「呵呵……一直都在喔。<br>從一開始，我就緊盯著妳了。」<br><br>有時在躲避球場上，<br>展開驚心動魄的攻防──<br><br>「我要上了，小特。<br>妳接接看……我這一球！」<br><br>「好、好快！！？<br>唔～～～呼！！<br>好，這次輪到我囉，鈴鹿！！」<br><br>有時在大胃王比賽中，<br>挑戰自身胃袋的極限──<br><br>「（嚼嚼嚼……！）再來！<br>（嚼嚼嚼嚼嚼嚼！）再來！<br>麻煩繼續送上來不要停！」<br><br>「一次也未免吃太大口了吧！？<br>我也要我也要！快拿給我下一份～！！」<br><br>不只如此，有時還要<br>跨越障礙賽中的種種考驗──<br><br>「即使在障礙賽，<br>我也不會讓出領先的景色……！」<br><br>「啊、啊啊，鈴鹿……<br>多麼傑出的速度呀。<br>親眼見到如此跑法，會令我──」<br><br>「情不自禁地想要……扭曲它呢！」<br><br>「啊哈哈，就是要這樣才有趣嘛！<br>我也要認真起來囉！<br>喧鬧GP，獲勝的一定是──」<br><br>『我！！（四人異口同聲）』"},
{index="30214",text="「札幌的街道<br>真的就像棋盤一樣呢。<br>呵呵，好像積木模型！」<br><br>她從札幌電視塔的觀景台<br>俯瞰著街景，天真無邪地漾開了笑容。<br><br>我和美妙姿勢利用<br>公務與競賽的空檔來札幌觀光。<br>那些護衛為了不妨礙她的觀光行程，<br>似乎都躲在暗處從旁守望著。<br><br>「幸好剛才有在鐘樓了解札幌的歷史。<br>知道背景再實際看到這塊土地，<br>感覺有更深的理解！」<br><br>她深深凝視著新穎的風景，<br>不斷按下手機的快門。<br>我也用手機拍下她陶醉的側臉。<br>當場和她分享，<br>她帶著滿臉的笑容，說我拍得很好。<br><br>「那麼，接下來就要吃飯囉。<br>得盡情享用這片土地特有的美食才行！」<br><br>離開電視塔來到大通公園時，<br>她拿出手機和旅遊書。<br>不論是哪一邊，都做了很多標籤，<br>以及用色鉛筆寫上的筆記。<br><br>滿滿玉米和奶油的味噌拉麵、<br>濃郁海鮮湯頭的醬油拉麵、<br>豚骨拉麵、鹽味拉麵──<br>每個看起來都很好吃，但份量<br>也都多到光是看著就會讓人反胃……<br><br>「呵呵，我忍耐沒吃早餐，<br>現在肚子可是餓得很呢！<br>第一間就選這個蔥和叉燒增量的吧♪<br>還要加上溏心蛋！」<br><br>我不禁疑惑這樣是為了瞭解當地風情嗎？<br>不過她的眼神露出興奮的光輝。<br>想著不能讓她為了我產生多餘的顧慮，<br>我也稍微鬆開了皮帶──"},
{index="30215",text="「──啊啊，啊啊……我贏了……！<br>在強者雲集的這個大舞台──」<br><br>「愛、夢想還有信念……<br>『我』………………狩獵了所有的一切。」<br><br>「不小心解放了……」<br>『就這樣解放了。』<br><br>「我一直隱藏的……」<br>『根本不可能藏得住。』<br><br>「汙穢又可恥……」<br>『那就是「我」。』<br><br>『覺得很歡愉吧？』<br>「……沒這回事……」<br><br>『覺得熱血激昂吧？』<br>「別說了……！我──」<br><br>『接受自己吧，愛如往昔。<br>「我」就是妳，妳就是「我」。<br>依循本能沉溺於貪求、快樂，<br>沉浸在蹂躪的放蕩“魔性”──』<br><br>『好了……快點墮落吧。<br>解開無謂的枷鎖，<br>一起享受這炫目又至高無上的狩獵如何？』<br><br>『放心，沒什麼好悲嘆的。<br>妳心愛的那個人，<br>無論看到妳變成什麼模樣──』<br><br><br><br><br><br><br>『都會對妳說「我還愛妳」。』"},
{index="30216",text="「來，乾杯──！」<br><br>「──今天對特雷森學園來說，<br>是值得慶祝的日子。<br>身為設籍本校的騎士，<br>能迎來這天讓我非常驕傲。」<br><br>「每天能朝自己的騎士之路邁進，<br>都是多虧有學園的大家指導……<br>實在是感激不盡。」<br><br>「說起來，<br>是受到了不少關照啦。」<br><br>「能夠盡情奔跑、<br>和富士一起生活，<br>都是因為有特雷森學園的關係。」<br><br>「……這間學園真的很棒。」<br><br>「這裡的人都很溫柔……<br>會尊重學生的意願。」<br><br>「有適合鑽研的器材和賽道，<br>活用最新智慧的課程。」<br><br>「作為一個磨練實力的場所來說──<br>嗯，是還挺不錯的。」<br><br>「我覺得老師和訓練員都非常可靠，<br>很感謝有他們。<br>時而溫柔時而嚴厲的指導，<br>對於同樣想成為指導者的我來說，<br>有非常多值得學習的地方。」<br><br>「還有身邊的所有賽馬娘。<br>大家都在拚命追求夢想……<br>讓我覺得自己也要好好加油♪」<br><br>「……是個好地方呢。<br>即使對我這樣的人也十分溫柔，<br>讓我只有滿滿的感謝……」<br><br>（能夠接觸大家對競賽的熱情，<br>得以感受到本能的片鱗半爪……<br>……是個非常非常棒的地方♪）<br><br>「……我也和大家一樣。<br>因為有眾人的支持，<br>才能全力邁向『絕景』──<br>全力邁向夢想。」<br><br>「所以……不只是過往這段時光，<br>往後我也想<br>永遠永遠在特雷森學園跑下去！」"},
{index="30217",text="如同廣闊海洋的恩惠包覆整個世界。<br>如同流動的河水滋潤人們。<br>如同豐沛的水孕育微小而尊貴的生命，<br>終究仍會接納他們的歸來。<br><br>我們的歷史循環不息。<br>順應壯闊的洪流，被孕育、繁榮發展。<br><br>我是那其中的一部分。<br>受到后冠的指引，今日完成了遠大心願。<br><br>想必我這頂橡木冠會成為嶄新的路標吧。<br>微小的生命與尊貴的夢想，<br>將再次受到它的指引，邁步向前奔去。<br><br>耀眼的未來啊。<br>仍未謀面的憐愛之子啊。<br>立足於已然奠定的基礎上──<br><br>「──但願，你們能盡情展翅高飛。」"},
{index="30218",text="「No～～～～!!」<br><br>「不要No了。回趟老家，<br>就算帶上裝蹄道具，<br>也只是徒增行李重量吧？<br>……我很高興妳這麼愛惜它，<br>但我實在覺得很難為情啊。」<br><br>「可是，如果枕頭附近沒有多伯送的禮物，<br>我會睡不著的……」<br><br>「Oh! 既然如此多伯也一起<br>Let's go my home就好啦！<br>這樣所有問題就都解決了！」<br><br>「呃……那是不可能的……」<br><br>「No～～～～!!<br>既然這樣我還是要帶回家……！！<br>多伯不在，我會very寂寞啊！」<br><br>「唔……！<br>就算是這樣，妳也可以帶別的啊……！」<br><br>「No～～～～!!」"},
{index="30219",text="夢想的陰影之中有些什麼？<br><br>樓梯一隅、熄燈的交誼廳、<br>半夜的自動販賣機區。<br><br>見證那道陰影的人會前往那裡。<br>而知道她們心情的我，也會前往那裡。<br><br>「有什麼煩惱嗎？女孩。」<br><br>來吧，今晚也讓我們開始這場表演吧。<br>希望妳能盡情享受屬於妳的舞台。<br><br>為了讓我成為「富士奇石」！"},
{index="30220",text="【荒漠英雄　訓練計畫】<br><br>◆target<br>秋季資深三冠<br><br>◆first objective<br>天皇賞（秋）／東京．草地2000公尺<br><br>◆to-do<br>．提高尾段加速的衝勁、加速力（更新尾段時間）<br>．提升自信<br><br>◆training<br>．15-15<br>　∟重新調整生理時鐘<br>．間歇跑訓練<br>　∟提升心肺功能<br>．坡道訓練<br>　∟提升爆發力<br>．並行練跑<br>　∟讓身體記得資深級GⅠ的速度感<br>　∟安排與實力更強的跑者進行並行練跑<br>．腦中模擬訓練<br>　∟活用VR設備<br>　∟為了能對應各種情況進行訓練<br><br>◆follow-up<br>．保養<br>　∟冰敷、按摩、伸展運動<br>．飲食<br>　∟規定的熱量合格<br>　∟規定的營養素合格<br>　∟委託設計提升肌力的菜單<br>．精神面支援<br>　∟對話、休息……<br>　∟委託大樹快車協助<br><br><br><br><br>──All missions<br>must be completed."},
{index="30221",text="「──哇哇！<br>集合時間快到了耶！<br>得趕快出發才行。」<br><br>「可是到底要買什麼慰勞品？<br>說到大家能一起開心享用<br>還可以吃飽的東西，<br>實在太多了……嗯……<br>果然還是買披──」<br><br>「（假音）炸雞～～～！！<br>吃炸雞吧……煩惱的年輕人們啊。」<br><br>「咦？這個聲音是從哪裡傳來──」<br><br>「那邊的人像嗎……？<br>感覺……長得非常像黃金船耶。」<br><br>「該怎麼說呢……<br>就像是有時候～<br>被召喚到三女神像前那樣嗎？」<br><br>「（假音）裝滿夢想的炸雞桶……<br>熱燙的雞油<br>滲進麵包中的漢堡……<br>酥脆口感讓人上癮的<br>雞柳條……<br>分量剛剛好又有清爽生菜的<br>美味捲餅……」<br><br>「（假音）哇～～♪<br>讓人全部都想吃～～～～～♪」<br><br>「（吞口水……）我、我好像……<br>有點想要吃炸雞了！？」<br><br>「（假音）很好、很好……<br>不過，炸雞以外的美食也不能放過喔。」<br><br>「（假音）香甜酥脆的比司吉……<br>彷若名配角讓人輕鬆享用的薯條……<br>滑順的巧克力醬融合可可派皮<br>讓人欲罷不能的巧克力派……<br>乾脆全都帶回家吧。」<br><br>「可、可是……<br>吃太多會變胖的──」<br><br>「（假音）傻孩子──！！」<br><br>「（假音）我等雖渴求炸雞，<br>但內心可不能淪為弱雞……<br>要是此刻猶豫，<br>那麼競賽時一樣會躊躇不前……<br>汝等甘願如此嗎？」<br><br>「唔，小鑽……！」<br><br>「……嗯，說得也是呢，小北。<br>──全都買下來吧！」<br><br>結帳後──<br><br>「很～好很好！<br>看來妳們有聽阿船的話，<br>大買特買了一番呢！」<br><br>「咦！？人像動了！？」<br><br>「呵呵呵，我不是人像！<br>而是炸雞宣傳大使阿船喔☆<br>──不過時間到了，我要下班啦。」<br><br>「原來是這樣……<br>剛才謝謝妳了。」<br><br>「……啊！<br>我們等一下要開遊戲派對，<br>妳要不要也一起來？<br>大家都會很歡迎黃金船，<br>而且我想妳應該也還沒吃飯──」<br><br>「既然這樣，今天要不要來吃肯德基呢？」"},
{index="30222",text="說什麼對手是在地之星。<br>說什麼支持度最高的果然是那傢伙。<br><br>說什麼這次又會是我輸。<br><br>吵死了吵死了吵死了吵死了！！！！<br>你們這些傢伙才沒有資格決定這種事情！！<br><br>決定這些事情的……是我！！！！<br><br>「你們這群傢伙，給我看好了！！<br>……我會獲勝……打倒所有人……！」<br><br>「讓你們的嘴裡連半句話都說不出來！！」"},
{index="30223",text="「呼，結束了結束了……！」<br><br>看似漫長的演唱會，在轉眼間就結束了。<br>手心滲出的汗水，以及仍隱隱殘留的麻痺感。<br>我根本沒有力氣去體會這些餘韻。<br><br>可是，想不到白仁那傢伙！<br>剛才明明在舞台上那樣大鬧特鬧的，<br>現在卻一臉若無其事的樣子──<br><br>「……亞馬。」<br><br>我被她突如其來的舉動嚇了一跳。<br>白仁遞過來的，<br>是一罐裝著水的寶特瓶。<br><br>「哦，妳這傢伙<br>也變得滿貼心的嘛！」<br><br>「妳誤會了。我手沒力，幫我開。」<br><br>「咦……？<br>……啊哈哈哈！這樣啊這樣啊！<br>原來妳也把力氣都用光啦！」<br><br>「吵死了……快幫我開。」<br><br>「好好好……雖然我很想這麼說，<br>但我也到極限啦。」<br><br>「哼……真是虧大了。<br>我暫時要推掉演唱會了。」<br><br>「哈哈，我也是這麼想的。<br>……暫時啦。」<br><br>我無意間瞥見那把倚放在一旁的吉他。<br>怎麼啦？為什麼忿忿不平地低著頭啊。<br>真是的，希望我再盡情地彈奏你是嗎？<br><br>「放心，我們下次再一起鬧個夠吧。」"},
{index="30224",text="在靜謐的夜裡格外響亮。<br>響亮到甚至令人感到嘈雜。<br><br>「白仁！<br>剛才的敲弦超酷的！<br>人家好想再聽一次哦～♪」<br><br>不論是高亢的聲音，還是沉悶的貝斯聲，<br>都朝著幽暗角落延伸，完成各自的使命。<br><br>但這是怎麼回事？<br>持續在身體裡迴盪且無處可去的聲音，<br>讓人幾乎喘不過氣，只想把它宣洩出來──<br><br>（～～～～～～～♪）<br><br>「哇哇，是不是彈得有點粗魯！？<br>跟剛才那種酷酷的感覺完全不一樣喔！」<br><br>「……不過，呵呵呵。這樣好像也不錯！<br>那種彈法才像是白仁嘛。<br>畢竟妳給人一種『吼喔～』的感覺。」<br><br>「……哼。」<br><br>我不由自主地露出獠牙。<br>啊啊，原來如此。<br>得變得更貪婪、變得更猛烈去撕裂，<br>那種無盡想要「更多」的衝動，<br>和那個感覺在某個地方重疊。<br><br>敲擊琴弦的聲響。<br>重砲天真無邪的笑聲。<br>用力撞擊我內心的聲音。<br>靈魂的吶喊，催促著這些聚集的聲音。<br>那聲咆哮，在靜謐的夜裡格外響亮。"},
{index="30225",text="「安可！安可！」<br><br>當演唱會結束，我們走出舞台邊幕的瞬間，<br>那些歡呼聲響徹會場。<br><br>「真真真令人意外～！<br>有種我們真的成為搖滾明星的感覺呢！」<br><br>「呵呵，現在這個瞬間，<br>我們就是真正的搖滾明星哦！<br>來，我們走吧。<br>Audience還在等著我們呢！」<br><br>「聽我說！既然這樣，<br>我們就用超厲害，厲害到會成為<br>傳說的表演來回應大家吧！」<br><br>「You are right!<br>我們必須要超越自己才行！！」<br><br>「那我們只能表演那首曲子了呢！<br>練習了無數次，讓大家心意相通的──」<br><br>「SHAKEROCK！！」<br><br>「就是說啊！<br>我呢！想用慶祝力量滿滿的<br>和太鼓版本來演奏！」<br><br>「人家啊！人家啊！<br>想用破音效果器讓聲音『啾嗚～～』地扭曲，<br>邀請大家體驗這種不可思議的感覺♪」<br><br>「呵呵，服裝也很重要喔。讓我們先穿上<br>年底edition的天后級dress吧！」<br><br>「咿呀～～～！不管哪個都太棒了！<br>大家的幸福都要滿出來啦！<br>這個畫面，根本就是在說寶船嘛！」<br><br>「我們再次傳遞──<br>不，是再次直擊大家的心吧！<br>讓大家感受到光是回想起來，<br>就能笑容滿面的快樂！！」<br><br>「鮭魚鮭魚鬧～！！」"},
{index="30226",text="堆積如山的資料。<br>為了散熱而發出沉悶低鳴的筆記型電腦。<br>牆面上成群的箭頭交錯在備忘錄間。<br>空氣中飄著曼特寧G1咖啡的香氣。<br>從現代少見的CD播放器中，<br>持續傳來了簡約的音樂。<br><br>倚著被壓扁的抱枕<br>並佔據沙發的她，<br>在我們能清楚可見的位置<br>先一步貼上了便條紙。<br><br>「不要跟我搭話。」"},
{index="30227",text="──我明明沒有缺乏預習。<br><br>獲勝後的景色，還是粉絲服務，<br>我都在腦海中反覆想像了無數次。<br>身為模範生，這麼做是理所當然的吧？<br>在與「那傢伙」的比賽中我會完美贏得勝利，<br>讓她見識完美表現，讓大家成為我的俘虜！<br><br>……我之前明明是那麼想的。<br><br>更高、更高、更高。<br>觀眾席的每個角落都擠滿了人。<br><br>多到讓內心裝不下的祝福聲。<br><br>呼喊我名字的聲音從天而降。<br><br>聚集的掌聲似乎能做成花束。<br><br>而且，更重要的是──<br><br>「赤驥，恭喜妳。」<br><br>什麼嘛、什麼嘛、什麼嘛！<br>受不了……到底是怎麼一回事！<br><br>原本打算要做的表演，<br>要對哪台攝影機擺出怎樣的姿勢，<br>我全忘得一乾二淨。<br>重新戴好媽媽給我的后冠之後，<br>我往優勝者區域跑了過去。<br><br>唯有這件事我必須做到。<br>唯有這件事我必須傳達。<br><br>來，深呼吸。<br>大家都在看，大家都很期待。<br>以最燦爛的笑容，最可愛又帥氣地說出來！<br><br>「我才是第一名！」"},
{index="30228",text="「BATTLE START──GO!」<br><br>這是最近很受到歡迎的射擊遊戲。<br>遊戲的系統音效，響亮地充滿整個空間。<br>店裡的氣氛一下子就變得熱鬧起來。<br><br>朝圍觀群眾的方向一瞧，<br>發現似乎是有個賽馬娘二人組<br>正在挑戰最高難度關卡的樣子。<br><br>「哈哈，哈──哈哈哈哈！<br>臣服吧，侵略者們（入侵者）！<br>吾等的岡格尼爾穿刺攻擊（雷射）<br>就要開始肆虐了！」<br><br>「──Enemy sighted.<br>Neutralizing target.」<br><br>兩人的操作風格完全不同。<br>本以為性格迥異的她們會因為缺乏默契，<br>導致成績也慘不忍睹……<br><br>「EX STAGE 1:CLEAR!<br>ADVANCE!」<br><br>「──柏修斯的魔劍（隱藏指令）！<br>呵哈哈，是下一群敵人！來吧！<br>封印解除──名古屋閃光！」<br><br>那是場壓倒性的殲滅行動。<br>操作方式較為激烈的賽馬娘<br>以驚人的氣勢<br>擊落了太空船（目標）──<br>不，是徹底蹂躪了對方。<br><br>「──目標──殲滅，完成。」<br><br>而另一位則待在後方，以沉著冷靜的操作方式<br>將躲過攻擊的敵人一隻不剩地全數擊倒。<br><br>完全相反，但卻是堪稱完美的──<br><br>「GAME CLEAR! HIGH SCORE!!」<br><br>「呵──妳的表現真是出色，<br>我獨一無二的朋友（恩奇都）啊。」<br><br>「──是啊。<br>妳也是──skilled ally。」"},
{index="30229",text=">RU<br>【社團參展的商品清單！】<br><br>「12月〇×日舉辦的活動上<br>販售的商品，第一彈。<br><br>我畫了同世代四人組的漫畫！<br>裡面塞了真的超～～級無敵多<br>群星的光輝！<br>（※有經過本人同意）<br><br>下方也一併附上詳情與封面圖。<br>請大家參考看看。<br><br>＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝<br>■新刊內容：《齊聚高歌吧，群星們！》<br>．B5大小（56頁/4色印刷10p+1色印刷46p）<br>．附贈光碟（正篇60min+花絮10min）<br><br>※一人最多可購買三組。<br>＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝<br><br>我也有另外設立了網購頁面！<br>沒辦法來到現場的朋友們，請點擊這裡→（URL）<br><br>寒冷的日子還會持續一段時間的樣子，<br>還請多保重，好好照顧自己喔。」"},
{index="30230",text="「嗯？<br>那孩子究竟發生什麼事情了？」<br><br>──嗚、嗚。媽媽……<br><br>「該、該怎麼辦才好？<br>那孩子，似乎跟父母走散了……」<br><br>「哈──哈哈哈！<br>既然如此！就儘管交給我吧！」<br><br>『各位！！這個孩子就由我──<br>惡魔王來接管了！』<br><br>什麼什麼？是新的活動嗎？<br>哦，她們好像在做什麼有趣的事情耶～！<br>欸欸，我們過去看看！！<br><br>「啊哇哇哇！？<br>有、有好多好多人都往這裡看過來了……！<br>好、好歌劇，妳究竟要做什麼……！？」<br><br>「我們兩人來演齣即興戲劇吧！<br>我會綁架這個孩子！由怒濤來救她！<br>如此一來，這個孩子就會很引人注目對吧？」<br><br>「來！讓我們開始表演吧！」<br><br>「咦、咦咦～！<br>嗯……那個！」<br><br>『各位！！這個孩子就由我──<br>惡魔王來接管了！』<br><br>『──造反的守門犬，怒濤貝洛斯啊！<br>有本事就從本王手裡救出這個孩子看看吧！』<br><br>『……惡、惡魔王！<br>把那個孩子還來！不然的話！』<br><br>『不、不然的話……<br>那個，我就把惡魔王……該怎麼說呢……』<br><br>──姐姐！<br><br>加油！<br><br>「──！」<br><br>『不、不管妳是惡魔王還是什麼，我、我都──<br>我都……！』<br><br>『我都會──打倒妳的……！」<br><br>『──！<br>哼……很好，態度可嘉！<br>那就看招吧！造反的守門犬！』<br><br>那群人是──哎呀，原來在演戲啊……！<br>說不定那孩子也在哪裡看表演……<br><br>──啊，媽媽！<br>是我，是我！我在這裡哦！<br><br>「哎呀，看樣子該謝幕了！<br>我們的任務就到此為止了！<br>各位！感謝你們願意聚集在這裡！」<br><br>已經結束了？<br>故事不是才正要開始嗎？<br><br>「後續就請各位在心中編織吧！<br>這是我們的戲劇──<br>由各位與我們共同撰寫，唯一的故事！」"},
{index="30231",text="『永遠的朋友啊！』<br><br>『──太陽王啊。<br>從今以後，也請永遠當我的朋友！』<br><br>在熱烈歡呼聲的包圍下，舞台落幕。<br><br>看完戲劇後，<br>我暫時無法從座位上起身。<br><br>無論是人、是王、是賽馬娘──<br>任誰也無法獨自活下去。<br><br>互相切磋、互相肯定，<br>擁有一起度過相同時間的夥伴。<br><br>「世紀末的霸王……<br>也需要那樣的人陪在身邊吧。」<br><br>儘管是劇中的角色，<br>我覺得她說的那番話，蘊含著真心。<br><br>我為此感到震驚不已。<br><br>她很「強大」。<br>所以我擅自以為她不需要任何牽絆──<br>也以為她正因為這樣才成為「霸王」。<br><br>可是，我其實誤會了。<br><br>就算是不同於平民的王──<br>就算是不同於王的霸王──<br>所有人渴望的事物都是一樣的。<br><br>我們所有人，<br>如果沒有牽絆就無法活下去。<br>如果沒有牽絆就無法邁步奔跑。<br><br>正因為如此，才會變得更堅強。"},
{index="30232",text="怎麼樣，我贏了喔！快稱讚我稱讚我！<br>……不對，不是這個。<br><br>是我們的勝利喔！我們做到了！<br>……嗯～～也不是這個！<br><br>畢竟我和訓練員<br>從相遇到今天的這段時光，<br>才不是什麼普通的同心協力。<br><br>人類與賽馬娘，步幅和能看到的景色都不同。<br>儘管如此，我們還是試著互相理解、<br>試著分享心情，讓呼吸調整到一樣的頻率。<br><br>那是比貼近彼此的心還要困難，<br>非常珍貴的事物。<br>是會讓人感到快樂、想要知道更多、<br>忍不住就加快腳步去追尋的事物。<br><br>所以我要謝謝你──<br>抓住我的手不讓彼此分開。<br>謝謝你拉著我前進。<br>謝謝你把我們緊緊連繫在一起。<br><br>此刻，就只剩下那個方法了。<br>我要把全部的心意，通通告訴你。<br><br>「聽我說──訓練員！」<br><br>「謝謝你啊！！！！」"},
{index="30233",text="「我看了喔，魯道夫！<br>妳和阿爾丹的表演！<br>哎呀～怎麼說……<br>總之我覺得很厲害！<br>我和千明也不會輸給妳們的！」<br><br>「……可是啊。<br>原來妳會像那樣寫書法啊！<br>該說是豪放？還是怎樣的感覺呢……」<br><br>「……有句成語<br>叫做『龍蛇飛動』。<br>是用來讚美墨水書寫的文字<br>栩栩如生的詞。」<br><br>「……自古以來，書法的評價標準<br>大概都以那個當作標準吧。」<br><br>「但我剛才很猶豫。<br>猶豫到底該怎麼表現出<br>栩栩如生的樣子……」<br><br>「就在那時候，我腦中自然而然浮現的──<br>是那些個性開朗爽快、<br>連生活方式都能感受到生命躍動力的<br>我的好朋友們。」<br><br>「於是──我明確地在內心揣摩，<br>如果是『她們』，會怎麼寫這幅字呢？」<br><br>「也就是說，倘若我剛才寫字時的表現<br>看起來很豪放的話──」<br><br>「那或許，<br>可以說是我直接表現出了<br>對『她們』的情感吧。」<br><br>「…………」<br><br>「唔哇～～～！真的假的！！<br>竟然有會讓妳這麼覺得的<br>傢伙們啊！？」<br><br>「欸，下次也介紹讓我認識吧！<br>妳那些超厲害的死黨！」<br><br>「…………」<br><br>「呵呵，不過我想……<br>這件事可能有點困難呢。」"},
{index="30234",text="望著窗外的景色，<br>內心有時會泛起陣陣苦澀……<br><br>小時候留下的痕跡……<br>無論我做了多少次<br>在湛藍天空下奔跑的夢……<br>我的面前，<br>總會有一道看不見的牆阻擋我。<br><br>在伸出手感受冰冷觸感的同時，<br>眼淚滑落臉頰帶來的溫度，令我顫抖不已。<br><br>我心中那個幼小的自己，<br>是那麼地無力、脆弱、愛哭。<br><br>所以……我現在要奔跑。<br><br>為了證明──<br><br>我在那片曾被阻攔去路的景色中，<br>曾幾何時流下的淚水，並非徒然……！"},
{index="30235",text="元旦的天空漸漸透露曙光。<br>彷彿會劃傷臉頰的冷冽空氣。<br>莊嚴的音樂。<br>白雪與黑墨。<br>──以及奔跑的賽馬娘。<br><br>就在我看得出神而有些恍惚的時候，<br>花朵與聲音從天而降。<br><br>「為了世上所有的存在，我們來祈禱吧。<br>只願眾人皆可隨心所欲地──<br>奔馳到天涯海角！」<br><br>如女神般神聖，充滿慈愛。<br>溫柔婉約，潔淨無瑕。<br>那個聲音給我這樣的感覺。<br>只是，與此同時……<br><br>『過來這裡，用跑的過來，<br>我會替妳照亮道路的。<br>所以說──別讓我等太久哦。』<br><br>我總覺得，那聲音聽起來也帶點<br>淘氣與誘惑的感覺。<br>是錯覺嗎？<br>應該是錯覺吧。<br>不過──<br><br>既然妳都這麼說了，<br>我要不要來試跑看看呢？<br><br>這樣的心情不可思議地染上了我的心頭。"},
{index="30236",text="「Airport.<br>那是展翅飛向世界的<br>dramatic的舞台。<br><br>在黃金會員專屬的lounge裡，<br>我坐上沙發，乾杯。<br>目送即將起飛的飛機們。<br><br>──dream.<br>沒錯，就是dream。<br><br>那架飛機<br>不只乘載著人們與行李，<br>同時還乘載著多到數不清的<br>dream以及hope，<br>一起飛向空中。<br><br>下個起飛的？<br>……沒錯，是我們。<br>跨越海洋，飛向空中，<br>用這純白的光輝照耀世界！<br><br>來，我們走吧！<br>無論去哪都行。<br>全世界正在呼喚我呀！」<br><br>＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝<br>如此說完的她敞開雙臂，<br>走出了候機室。<br><br>來往的人群回過頭來，<br>看見她威風凜凜走來，便明白一切。<br><br>「採珠！採珠！採珠！」<br><br>她舉起一隻手來回應這些喝采。<br><br>「謝謝，我也會帶上你們的passion<br>一起fly away哦！」<br><br>──應該沒有人注意到。<br><br>她手裡沒有行李箱，<br>也沒有前往世界的機票。<br><br>然後，應該任誰都想不到吧。<br><br>她今天展現出了這樣的自信、風貌、風範，<br>卻只是來候機室聊聊天而已。"},
{index="30237",text="真機伶<br>@Curren<br><br><br>▷　播放影片<br><br>＝＝＝＝＝＝＝＝＝＝＝＝<br><br>嘿咻，好了……<br>耶嘿嘿，開始拍攝了嗎？<br>咳！那麼，就開始囉？<br><br>謝謝你今天也來看真機伶♡<br>我是比平常還～要可愛的<br>情人節版本真機伶！<br><br>來，趕快稱讚我很多次「可愛」。<br>要很～多次哦！<br>這個姿勢怎麼樣？還要拋媚眼！<br>呵呵，真是的。多一點再多一點！<br><br>如此一來，<br>就沒有什麼低頭的理由了，<br>對吧？<br><br>討厭的事情，想哭的事情。<br>如果你的腦袋裡都是真機伶，<br>就不會想起它們了對吧？<br><br>真機伶永遠都會在你的心裡。<br>那就是，我給你的禮物。<br><br>所以，來──<br>看著真機伶吧？<br><br>讓你被可愛填滿，<br>絕不會留下半點空隙給你哦。<br><br>就讓可愛的真機伶，<br>讓你融化在幸福裡吧♡"},
{index="30238",text="【邀請函】<br><br>春風吹拂的這些日子，<br>不知道您是否<br>一切安好？<br><br>此次，雖為小小茶敘，<br>但仍希望能誠摯邀請您<br>蒞臨參與。<br><br>隨從會在下方的時日<br>前去迎接您。<br><br>希望您能與我一面眺望<br>玫瑰花園，一面享受紅茶，<br>共度一段美好時光。<br><br>我雖不才，<br>但為了提供適合您的地方，<br>必將誠心誠意地盡全力準備。<br><br>由衷期待<br>與您見面的那天到來。<br><br>RSVP<br><br>　　　　　　──生野狄杜斯<br><br>＝＝＝＝＝＝＝＝＝＝＝＝<br>蓋上深紅色火漆印章封口，<br>質感講究的信封。<br>有著淡淡玫瑰香氣的信紙。<br>以及，回信用的卡片──<br><br>我打直腰桿重新坐正姿勢，<br>拿起了最高級的鋼筆。<br><br>答覆當然早已不言而喻。"},
{index="30239",text="哎呀～說這種話……<br>我自己也知道滿失禮的啦。<br><br>該怎麼說……啊哈，你還真奇怪呢～<br>不，我說真的……一定是這樣沒錯！<br>而且奇怪的程度不只一點，是非常奇怪！<br><br>哪來的需求啊？<br>是說，我真不懂為什麼你會感到高興。<br>雖然是有句俗話說<br>「青菜蘿蔔各有所好」沒錯啦。<br>但我還是覺得<br>明明有很多更出色的人啊～<br><br>……覺得歸覺得啦……<br>…………<br><br>……我知道啦。<br>我知道你不是在說謊……<br><br>我也明白……<br>不該跟選擇了我的人說這種話。<br><br>我都知道……<br>只是知道歸知道……<br><br>…………<br>啊──真是的──！<br>啊啊──我受不了了！<br><br>唉，算了算了！<br>素質小姐我也做好心理準備了！<br>所以你可別事到如今<br>才來後悔選擇了我喔！<br><br>好啦，張開嘴巴！<br>我就大發慈悲如你所願<br>放進你的嘴裡吧！！<br>真是的，我可要塞到<br>你說不出話為止！<br><br>……說「啊──」。"},
{index="30240",text="超越憧憬，<br>超越失去，<br>超越糾葛，<br>超越餘光與纏繞在雙腳上的一切，<br>在最後的最後殘存下來的念頭──<br><br>「我想奔跑。」<br><br>正是那如同本能的渴望，<br>才能成為開拓未來的強烈光芒。<br><br>在前方等待著我的正是──「新時代之門」"},
{index="30241",text="裝飾在特別展覽上的某張照片。<br><br>某個人在那張照片前停下了腳步……<br>不由自主地露出了微笑。<br><br>「第一次電視上看見小俳的時候，<br>我真的超級感動的～<br><br>充滿活力又可愛……看得我好陶醉。<br>那時候的我，實在是太想親眼見她一面，<br>甚至還存了錢，搭了夜間巴士呢。<br>……經過這番努力，最後我只看到了<br>那場她即將引退的有馬紀念而已。<br>可是──那就是我的青春啊！」<br><br>某個路人向身旁的友人如此說道。<br><br>「我啊，那時候真心相信如果是速度象徵，<br>就一定可以拿下全世界。<br><br>我甚至還去機場送行了。<br>在她即將前往世界的那天，<br>我高舉雙手揮舞著前一天製作的旗子。<br>不斷喊著「加油，加油啊」。<br>對我們這個世代來說，<br>她是我們的驕傲……也是希望。」<br><br>某個老人雙手合十祈禱著。<br><br>「在聖烈特大人出現之前，<br>我都覺得獲得三冠之類的是在痴人說夢。<br><br>雖說效仿國外，通往三冠的道路誕生了<br>但是那樣的榮耀，有誰能達成呢？<br>無論當時的我擺出多麼不屑的態度，<br>那天的她，仍締造了一場壯舉。<br>是啊，她很輕易地就改變了一切。<br>託她的福，我也改變了。<br>我忘不了夢想變成現實的那份感動……<br>所以也變成每週收看競賽的一分子了。」<br><br>某個人邊看邊落下一滴淚水，<br>某個人邊看邊握緊拳頭，<br>某個人邊看邊回顧當時的自己。<br><br>可是──<br><br>──照片裡的她們一定不曉得。<br>那些停下腳步的人們會看著她們，<br>輕聲說起過往的回憶。<br><br>即使如此，那張照片依然守護著眾人。<br>漾著滿溢慈愛的微笑。<br>……就彷彿看著所愛之人。"},
{index="30242",text="「杏目，上演了一場世紀的完全勝利！」<br>「創下紀錄！獲得壓倒性勝利！」<br><br>我把幾本寫著聳動標題的雜誌遞給她，<br>她在隨意翻閱了幾頁後，露出滿意的表情。<br><br>「呵呵……啊哈哈哈哈哈！！<br>太好了，太棒啦！！<br>用超高速度飛奔過終點鏡板的感覺<br>簡直棒透了！！」<br><br>「──不過，現在才正要開始。<br>因為在更高的舞台上！！<br>還有能與更加更加強大的選手們<br>一較高下的競賽在等著我呢！」<br><br>「我必須變得更強！<br>強到自己過去的紀錄都不值得一提！」<br><br>喜悅的漣漪頓時靜止，<br>那雙眼眸注視著其他層級的目標。<br>嘴角沒有任何放鬆的笑容，<br>只有渴望添上了色彩。<br><br>「好，讀書時間結束了。<br>我們走吧，訓練員！」<br><br>「就算是自己，我也會贏給你看！」<br><br>攀登至巔峰之後，映入那雙眼睛裡的<br>究竟是什麼樣的世界呢？<br>即使是她自己，也無從而知。"},
{index="30243",text="遼闊的天空，前方的道路已然敞開。<br>走吧！向前邁進！超越傳說（妳）！<br><br>「好，從這裡開始會備受矚目！<br>我要來好好回應大～家的愛唷♪」<br><br>「我要獻上，與你相襯的花束──！<br>我想將榮耀，送給你──！」<br><br>「──唔。今天，歷史恐怕會發生改變……<br>不……是我會改變歷史！」<br><br>「就透過這場比賽！」<br><br>「──不。我不會退讓，也不會交給任何人。<br><br><br>就算妳們會追上來……<br>──贏的人還是我！！」<br><br>熱度與氣勢正在加劇。<br>那雙追求「最強」的腳──<br><br>「想得美，杏目前輩！！<br>最前頭還有女王寶座！都是我的東西！」<br><br>再次加速！<br>跨出步伐！別停下來！<br>讓雀躍的心意如願以償！<br><br>因為會最先飛奔到<br>那個能聽見熱烈歡聲的地點的人──是我！"},
{index="30244",text="那是那孩子還小時，<br>在漫長冬季的某天發生的事。<br>明明天色早已全黑，<br>她卻遲遲沒回家。<br>正當這件事準備要在宅邸引發軒然大波時──<br><br>「奶奶～～奶奶～～<br>妳快看～～」<br><br>「啊啊，光明……！<br>都這麼晚了，妳到底去哪了？<br>大家都很擔心妳啊……！」<br><br>「我去找這個，然後把它帶回來了～<br>因為奶奶妳說<br>想快一點看到嘛～」<br><br>「我說的……？究竟是什麼……<br>哎呀，看看妳的手變得這麼冰──」<br><br>「是春天。」<br><br>我永遠無法忘記。<br>那孩子這麼說完並打開掌心，<br>裡頭有著惹人憐愛的淡粉紅色花瓣──<br><br>「在找到之前，真的好累啊。<br>但我慢慢地跑了好多地方，<br>總算把它帶回來了哦～」<br><br>還有那抹笑容。<br>看到之後我一不小心就忘記要勸戒她，<br>直接緊緊將她擁入懷中。<br><br>──是啊，正好和今天的<br>那張臉龐一樣，<br>掛著有如花信風般的笑容。"},
{index="30245",text="距離「直道舞會」還有數天──<br><br>「胸針……？啊啊！<br>就是要每組舞伴配戴同款的那個嗎！」<br><br>「嗯，我想先詢問伏特加的喜好，<br>然後再由我這邊準備──<br>妳覺得這本型錄裡的款式如何？」<br><br>「唔喔……好猛……<br>感覺每一款都很成熟……超帥……！！」<br><br>「呵呵，我保證這間工坊的品味絕對沒問題。<br>畢竟是我很常光顧的店。」<br><br>「嗯～～嗯……<br>這個很帥，那個也很帥……！<br>──啊，這個……<br>我想選這個！」<br><br>「這是……嗯，的確很漂亮呢。」<br><br>「既像星星，也像一道閃光，<br>綻放著耀眼的光芒──<br>很適合像妳這樣的賽馬娘。」<br><br>「咦？是嗎？<br>真要我說的話──<br>我覺得更適合小旅前輩耶。」<br><br>「我總覺得它很像<br>前輩這雙亮晶晶的眼睛呢！」<br><br>「…………」<br><br>「耶嘿嘿，不過既然前輩<br>說也很適合我了……！<br>讓我開始有種這就是最強的感覺！<br>一起戴上胸針，來場閃耀全場的舞蹈！！<br>然後拿下『最佳舞伴』吧！！」<br><br>「……嗯，當然。我們全力以赴吧。」"},
{index="30246",text="距離「直道舞會」只剩幾天。<br>今年又到了這個季節，<br>學園各個角落都能看見<br>賽馬娘們努力練習著雙人舞。<br>約好和小旅見面的我前往了舞蹈室────<br><br>「──願意和我跳支舞嗎？」<br><br>我一時無法理解她伸出手的用意。<br>她見此情景露出了微笑。<br><br>「我今天不管怎麼調整行程，<br>都無法配合舞伴的時間……<br>可是舞會就快到了，<br>我還是想盡量以有舞伴的狀態<br>來練習────」<br><br>看來她大概是希望，<br>我能當她直道舞會的練習舞伴。<br>我猶豫了一下，握住了她的手。<br><br>「……你其實不必小心翼翼地<br>像是在處理一件易碎品──」<br><br>看樣子，我反映在生澀動作上的不安<br>似乎被她察覺到了。<br>而在我還來不及<br>將「我無法勝任」說出口前──<br>她便一把牽過我的手。<br><br>「雙人舞需要互相信賴……<br>來，更加相信我，<br>委身於我吧──」<br><br>她說完便將我拉近自己，<br>我也聽話地任由她主導……<br><br>「──呵呵，跳得很棒呢。」<br><br>我的眼中映照著天花板，<br>以及那雙俯視著我的深邃眼眸。<br>她支撐著我，軀幹居然紋絲不動，<br>這點讓我暗自讚嘆不已。<br>──忽然，我察覺到一件事。<br><br>剛才的舞步，<br>我和小旅負責的部分<br>應該反過來了吧？<br><br>「──哎呀，被發現了啊。」<br><br>她露出淘氣的笑容，<br>再次向我伸出手──<br><br>「那麼這次就『反過來』。<br>……願意和我再跳支舞嗎？」"},
{index="30247",text="「直道舞會」。<br>自由舞蹈時間。<br>在中庭──<br><br>「原來妳在這裡啊──西薩里奧。」<br><br>「啊，克莉斯耶絲……<br>嗯，我想出來稍微吹吹夜風。」<br><br>「………………」<br><br>「克莉斯耶絲……<br>妳不繼續跳舞嗎？<br>那個，好像有很多人想<br>跟妳一起跳舞，所以──」<br><br>「──結束了。」<br><br>「咦？」<br><br>「我剛才──跟邀請我的──<br>所有人跳過舞了──<br>所以──Mission Accomplished.」<br><br>「……呵呵，不愧是妳。<br>真摯、誠懇──<br>很符合克莉斯耶絲的作風。」<br><br>「……那麼，接下來就只剩下<br>等待公布最佳舞伴了。<br>直舞和這個夜晚──都要結束了呢。」<br><br>「………………」<br><br>「……西薩里奧。<br>要不要再跳一次？」<br><br>「咦……」<br><br>「前提是──妳願意的話──」<br><br>「當然……我非常樂意────！」<br><br>「再一下就好……<br>讓這個夜晚，再延續一下吧──」"},
{index="30248",text="「（我一直在等這一刻──）」<br><br>狩獵最重要的是耐心及持久力。<br>為了將獵物逼入絕境並拿下，<br>我絕對不能心急。<br>必須繃緊神經觀察狀況，<br>一味地等候著最佳時機到來。<br>無論天候再惡劣，也絕不動搖。<br>因為故鄉的大自然已經賦予我<br>足以面對這些困境的肉體與精神。<br><br>「（目標最外側，要進攻──就是現在！）」<br><br>接下來只要全力以赴──<br>像狼一般柔韌，<br>像大熊一般強悍，<br>即使泥濘濺上純白的決勝服也毫不在乎，<br>我要奔跑。無論是大雨中的深山野營，<br>還是滿身泥濘的賽跑，我最喜歡這些<br>從小做到大的事了。<br>──所以我，不可能會輸。<br><br>「呀啊啊啊啊啊……！」<br><br>即使觀眾席空蕩蕩，<br>我仍能感受到大家的存在、心意與聲援。<br>許多人正引頸期盼著<br>那足以留在歷史中的瞬間。<br>所以──<br>不管是那個笑容燦爛、死守領頭的人，<br>還是支持度最高的女王陛下……<br>我會超越她們所有人──<br>撲向那名為終點的獵物！<br><br>「呼、呼、呼……」<br><br>「各位，我做到了──<br>我拿下……這場競賽了……！」<br><br>彷彿獻上祝福一般，<br>數道光芒穿過烏雲柔和地灑落了下來。<br>那景象，竟與飄落的羽毛有幾分相似。"},
{index="30249",text="「喲～阿訓，打擾囉。<br>我帶了新上市的能量飲料過來……」<br><br>「嗯，你在看什麼啊？<br>……唔哦，是前陣子那次的照片啊。」<br><br>「哇～連影片存檔都看喔？<br>你當天不就在現場嗎～」<br><br>「我當天也是一邊參加遊行，<br>一邊反過來看著觀眾們喔。<br>然後就發現：『哦，阿訓來了～』」<br><br>「那種小小的瞬間，<br>其實也還滿～打動人的呢。」<br><br>「……哎呀，反正簡單說，<br>就是在閃耀的夜裡看見熟人～<br>會有種連內心也突然被點亮的感覺？」<br><br>「我當時也很緊張喔。<br>畢竟都沒預演過嘛。所以……」<br><br>「找到你的身影，<br>就能讓我想著『好，一定沒問題了』。」"},
{index="30250",text="光芒滿溢。<br>點亮黑暗的無數光輝，宛如群星。<br><br>「呵呵……完全看不到盡頭。<br>放眼望去所見之處，都閃耀著光芒……」<br><br>群星閃爍。<br>這幅絕景，宛如人們心中所描繪的夢想。<br><br>「太好了呢。<br>每個人的願望都獲得了回報。<br>大家都很努力準備喔。<br>帶著如同這些光芒般閃耀的眼神，<br>懷抱絕對要讓活動成功的信念……」<br><br>「真的……真的……好美。」<br><br>「嗚嗚……」<br><br>「唔……！啊啊，真是的。<br>這樣會看不清這片<br>難得的景色啦。<br>呵呵呵……！」<br><br>夢想盈滿。<br>如同連結一切的奇蹟──"},
{index="30251",text="【家人LANE（4）】　　　<br>＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝<br><br>○媽媽<br>［你們快看，是希望的英姿！］<br><br><br>　　　　　　　　　已讀3［別擅自上傳啦］<br><br><br>○媽媽<br>［不行嗎？ <br>　可是這也會放進家庭相簿吧？］<br><br><br>○老弟<br>［拍得很好喔，表現超亮眼耶］<br>［後面的人是姊姊的朋友嗎？］<br><br><br>○老爸<br>［很帥氣］<br>［妳很努力嘛］<br><br><br>　　　　　　　　　　　　已讀3［吵死了］<br>　　　　　　已讀3［這點程度輕輕鬆鬆啦］<br><br><br>○媽媽<br>［如果妳真的很討厭，媽媽跟妳道歉。<br>因為妳的表現實在太亮眼，<br>媽媽一不小心就開心過頭了。］<br><br><br>　　　　　　　　　已讀2［我又沒說討厭］<br>　　　　　　　　　　　　　已讀2［喂？］<br>　　　　　　　　　　　　　已讀2［媽媽］<br>　　　　　　　　　已讀2［我不在意啦！］"},
{index="30252",text="我喜歡奔跑。<br>喜歡隨心所欲、自由自在地奔跑。<br>喜歡一路奔跑後，在盡頭看到的景色。<br><br>我喜歡在山路上奔跑。<br>喜歡跑上山頂後，從山頂俯瞰的街景。<br><br>我喜歡在坡道上奔跑。<br>喜歡爬上坡頂時，映入眼簾的海平線。<br><br>我喜歡在城鎮裡奔跑。<br>喜歡穿過幢幢大廈後，一望無際的廣闊天空。<br><br>我喜歡持續地奔跑。<br>喜歡發現在不知不覺間<br>展露光芒的明亮星星。<br><br>我喜歡奔跑。<br>喜歡在賽場、在競賽中奔跑。<br>徹底逃離所有的雜音，<br>只聽得見風聲與自己的心跳聲。<br>我喜歡領先的景色──勝過任何一切。<br><br>我喜歡的景色──<br>隨著每次的奔跑、疾驅而漸漸增加。<br><br>最近……<br>在奔向盡頭後，<br>回頭看見的你的表情，<br>也成了我喜歡的──"},
{index="30253",text="我們從來沒有做過約定。<br>雖然好像在夢裡見過妳，<br>但我想那大概是某人的回憶吧。<br><br>所以每次醒來，胸口就會隱隱作痛。<br>我希望妳的眼裡只有我。<br>我希望妳能認可我。<br>回過神來，發現自己只是在一味地祈求。<br><br>可是……不該是這樣對吧。<br>我的聲音，能呼喚妳。<br>我的雙腿，能帶我奔向妳身邊。<br>我的內心，時時刻刻在想著妳。<br><br>奇蹟也好，偶然也罷，甚或是命運我都不需要。<br>我認為，即使依託他物而順利達成心願，<br>夢，終究還是夢。<br><br>我已準備好禮服，以襯托妳的美。<br>心中也懷抱著滿滿對妳的愛意。<br><br>再一下子就好，請妳在未來等著我。<br>只屬於我的──后冠。"},
{index="30254",text="「Eek……!? 啊～真是的。<br>造型都亂掉了。」<br><br>一陣風由敞開的大門吹進了教堂。<br>明明接下來才正要穿著禮服款決勝服進行拍攝，<br>以及接受採訪。<br>女王陛下的努力差點就要化作泡影了。<br><br>「It's no use……<br>只靠窗戶的倒影看不太清楚呢。」<br><br>勇敢之心一邊用手指梳理頭髮，<br>一邊環顧四周尋找鏡子。<br>看來她對用髮夾固定的<br>后冠位置不太滿意。<br><br>我伸出手，輕輕觸碰銀色冠冕，<br>將其調整至距離頭頂45°角的位置。<br>我很清楚最能彰顯其光彩的角度。<br><br>「謝謝……嗯，很完美呢！」<br><br>「──等等，haha！<br>Your hair's a mess!」<br><br>「過來，讓我整理吧。<br>我可不允許身邊的人頂著那種髮型。」<br><br>「居然讓未來的女王做這種事。<br>這樣簡直就像──」<br><br>「……呵呵，沒什麼。<br>大家都在等我們。<br>C'mon, let's go!」<br><br>透過窗扉灑落的光輝，照耀著整座教堂。<br>彷彿有著無上喜悅，彷彿獻上了祝福。"},
{index="30255",text="「是這樣嗎……不對，還是這樣？<br>都不是……總覺得自己好像在硬裝成熟。」<br><br>空中彌賽亞站在全身鏡前，<br>反覆掀動著淡綠色的禮服裙襬。<br>在拍攝要給父母看的盛裝身姿前，<br>她已經為決定姿勢花了一小時。<br><br>「……」<br><br>空中彌賽亞微微低下了頭。<br>那略帶幾分憂鬱的側臉，<br>已足以展現與她相遇至今的成長。<br><br>我情不自禁地舉起相機，按下快門。<br><br>「！<br>……對、對不起！因為太突然了，<br>所以來不及擺出適合的姿勢。」<br><br>空中彌賽亞小心翼翼地<br>靠近查看自己被拍下的樣子。<br>然後，她瞪大了眼睛。<br><br>「……這是我嗎？<br>是、是不是顯得太成熟了？<br>這樣會不會像是在欺騙<br>父親和母親啊──」<br><br>為了替她打氣，<br>我努力露出溫柔的微笑。<br>我覺得，憑我們一起走過的歲月，<br>這樣就足夠了。<br><br>「……這樣啊。<br>畢竟我的確沒有刻意修飾，<br>只是靜靜站在那裡而已。<br>呵呵……看來能向父母這麼報告了──」<br><br>「告訴他們，我真的成長了很多。」<br><br>空中彌賽亞的臉頰泛紅，<br>嘴角微微上揚。<br>吹拂的春風，帶著幾分暖意。"},
{index="30256",text="「──欸，你知道嗎？<br>閃電落地所花的時間<br>據說連一秒都不到喔。<br>由於實在太快了，<br>所以聲音、震動都追不上它。<br>等回過神，它早就已經到了<br>無法觸及的地方啦。」<br><br>「哈哈！這只是我小時候<br>從電視上看來的小知識啦！<br>我當時覺得超帥的，<br>這件事就一～直在腦海裡揮之不去。<br>當老爸說我跑步就像『白色閃電』時，<br>腦子就靈光一現，<br>覺得『就是這個啦！』。<br>我想展現出如閃電般的跑法。<br>用無人能比的速度，瞬間改變世界的色彩，<br>讓所有的人大受震撼。」<br><br>「……哎呀～不行不行！<br>我又不是多愁善感的人。<br>突然拋出這種話題，<br>訓練員你也會感到困擾吧？<br>回憶就到此為止，不提啦！<br>……不過，該怎麼說呢。<br>我就是覺得應該在和『那傢伙』<br>對決前把這些講出來。」<br><br>──呼……<br><br>　　　　呼……<br><br>　　　　　　呼……<br><br>「在最後的直線衝出來的<br>是前列第二位的玉藻十字！<br>哎呀，小栗帽！<br>小栗帽也從外側一口氣突圍！<br>玉藻十字領跑！<br>小栗帽步步進逼！<br>是閃電！！還是怪物！！ <br>贏得這場秋季決戰的人是──」<br><br>……世界的色彩改變了……<br>等回過神，早就──！<br><br><br><br><br><br><br>「欸──<br>怪物，妳也被震撼到了吧。」"},
{index="30257",text="喔喔喔喔！<br>你怎麼啦！！<br><br>已經想認輸了嗎！？<br><br>不過那也沒關係！！<br>畢竟自己的身體，<br>只有自己最清楚啊──！！<br><br>可是啊──！<br>在放棄前！<br>先聽我說一句──！！<br><br>你的！雙眼是！<br><br>「活、火、山！！」<br><br>噴湧而出的岩漿！<br>會讓陸地不斷擴張！！<br><br>是不是很困惑！？<br>對吧，我想也是！？<br>很想問我到底什麼意思吧！？<br><br>人若想獲得成長，就得跨越極限！<br>不過說到底，把自己逼到極限<br>也不是一件簡單的事！<br><br>不過看看現在的你……！<br>已經把自己逼到極限了！<br>而且！動力也健在！<br><br>也就是說──！你的可能性是──<br><br>無、限、大！！！！！<br><br>現在就成為休火山──<br>還太早啦！！<br><br>喂～～你難道沒聽見嗎？<br>自己的心跳聲！<br><br>渴望獲得解放的！<br>野性本能！！<br>還有震撼大地的咆哮！！！！<br><br>沒錯，就是這個眼神！！<br>上吧！怒吼吧────！！<br><br>（受到激勵的你放聲大吼）<br><br>太────棒啦────！！<br>我就是在等這個答案啊────！！<br>好──！熱血訓練員，快跟上我的步調！！<br><br>再做三組！<br>用你的汗水！！<br>在新生的陸地上開闢出大瀑布吧──！！！！"},
{index="30258",text="好奇怪啊。感覺好輕盈。<br><br>不只是身體，<br>心情也感到很輕鬆……<br><br>連曾經覺得遙不可及的頂點，<br>都感覺近在眼前。<br><br>我所背負的東西<br>應該更加沉重才對──<br><br>啊，是這樣啊……<br><br>──因為我已經習慣了。<br><br>焦躁與不安化為訓練負荷，<br>將內心的肌肉鍛鍊得更強壯！<br><br>所以即使面對如此巨大的壓力，<br>我也能泰然自若！<br>也就是說──<br><br>我的身心，<br>現在處於最佳狀態！！<br><br>啊哈哈，我能贏！我能贏過任何人！！<br>今天站上頂點的人──<br><br>是我！"},
{index="30259",text="爸爸、媽媽……大家，對不起。<br>我……我──<br><br>我實在太天才了，對～～不～～起～～♡<br>畢竟看我比賽一點都不刺激對吧☆<br>就連GⅠ也是輕鬆到手不是嗎？<br>因為我認真起來就是秒殺嘛～<br><br>話說，我要是全力以赴，<br>可能還不只是這樣而已耶～<br>天啊，我果然強過頭了？<br>這件事應該多讓全世界知道吧！<br><br>蓋個小潘博物館之類的～<br>然後再掛上我的肖像畫～♡<br>標題就叫「天才．房一潘朵拉」！<br>根本是世界遺產嘛。<br>我當然也會變成學園裡最偉大的人不是嗎？<br>到時候我要把餐廳菜單全改成甜點！<br><br>真好啊～訓練員。<br>你能擔任這種天才的專任訓練員，<br>未免太幸運了吧？<br><br>可別讓大魚跑掉囉！<br>要好～好地溫柔對待我唷♪"},
{index="30260",text="各式各樣的灰髮。<br><br>灰髮灰姑娘、吐槽灰髮、<br>方程式灰髮、太公望灰髮、<br>算了吧灰髮、可愛灰髮、<br>喜歡競賽史的灰髮、喧鬧灰髮。<br><br>正要吃聖代的賽馬娘是……<br>就卡路里而言，算是灰色地帶。"},
{index="30261",text="里見度假村舉辦水上表演。<br>凱旋芭蕾被選為舞蹈舞台的壓軸，<br>正獨自等待上場──<br><br>「1、2、3、4、5、6……不行。<br>身體局部的控制必須更徹底，<br>沒入水中時要俐落，不能輸給水的阻力──」<br><br>我是主角。<br>必須比任何人都更堂堂正正地掌控舞台。<br><br>被選上的那一刻，我相當開心。<br>但是一開始練習，又開始感到不安。<br>我在水裡做得出原本的動作嗎？<br>我真的有辦法擔任主角嗎？<br><br>我在這個夏天問了自己無數次。<br><br>即便如此──我還是不想退讓。<br>我絕對不想放過這個<br>已經到手的機會！<br><br>「啊……芭蕾。<br>時間差不多了。」<br><br>「嗯，駿逸。<br>那我上場了喔。」<br><br>「那個……絕、絕對會很順利的！<br>練習時的動作就已經很俐落……<br>幾乎讓人感覺不到泳池裡的水。<br>感覺，真的超帥氣……！」<br><br>「哈哈，謝謝妳。」<br><br>「那就讓我再去多耍帥一下吧！」<br><br>能完成這個夏天最棒演出的人，<br>不是別人，正是我這個主角。"},
{index="30262",text="～競賽型泳裝．UMA Swim～<br>採用新型材料，實現驚人的輕量化！<br>在不斷改良下，保溫能力也更勝以往！<br>若要進行泳池訓練，選這件準沒錯！<br><br>「……妳看這件如何？」<br><br>「嗯～可能有點太樸素了！<br>我覺得選這邊有再多些輕飄飄裝飾的款式，<br>看上去會更『可愛』呢♪」<br><br>「這樣啊。看來機能美和『可愛』<br>差得挺遠的……<br>比布魯斯，讓妳費心了。」<br><br>「只要我把『可愛』鍛鍊到極致，<br>一定能讓她大吃一驚。<br>既然如此……我得再多學習<br>何謂『可愛』才行。」<br><br>「嗯～不過不過，<br>光是學習好像有點可惜耶。<br>如果大鳴大放也能享受這個過程，<br>我想應該能拍出更棒的照片喔～<br>畢竟這種時候，樂在其中的人才是贏家嘛！」<br><br>「……樂在其中的人才是贏家……」<br><br>「原來如此。那我就遵循本心……<br>展現『最強』的可愛給她看吧。」<br><br>「嗯嗯，就這麼辦吧～！！<br>啊哈，一起讓她大吃一驚吧♪」"},
{index="30263",text="「欸欸，今天是夏季集訓最後一天耶～！<br>大家都會趁最後機會再去一次海灘吧♪」<br><br>「我……我就不去了。<br>反正去了……也是自己一個人游泳。」<br><br>「咦～～為什麼啦～～？<br>來……妳看這張照片！<br>聽說海岸旁有在賣這種<br>用整顆水果做的雪酪耶～♪」<br><br>「哇，真的用了整顆……！」<br><br>「我好想多點幾份來拍照～<br>然後和大家分享各種口味喔～<br>嗚～～一起去嘛，逸逸～～～」<br><br>「唔……我、我知道了啦。<br>只去一下下的話……我就陪妳吧。」<br><br>「哈哈，為了不打擾妳們姊妹相處，<br>我就跟皇冠一起行動好了。」<br><br>「咦～？不要不要──！我也想和芭蕾<br>還有皇冠一起留下回憶啦！」<br><br>「像是打西瓜，然後堆沙堡～<br>再去浮潛跟……啊，還有煙火！<br>怎麼樣？聽起來很有趣吧，逸逸♡」<br><br>「呃，嗯。那個……如果不會造成困擾，<br>我也想……和妳們一起玩。」<br><br>「啊，不介意我也參加的話……我很樂意！」<br><br>「耶耶～～！<br>姊姊和大鳴大放<br>也絕～對會很開心的♪」<br><br>「咦，姊姊來我還能理解……<br>大鳴大放竟然也願意來啊……」<br><br>「嗯！她說畢竟是最後一天，<br>想要好好體驗一下沙灘的厚重沙地♡<br>還說要盡全力奔跑呢～♪」<br><br>「嗯呵呵，真叫人期待呢～<br>在夏天的海邊……和最喜歡的大家一起♪」<br><br>「我們要盡情玩到天黑喔♡」"},
{index="30264",text="「我回來了──」<br><br>不知為何，我總覺得<br>這樣說才是正確的。<br><br>我一直在追尋這份光輝，<br>為了抵達此處。<br><br>「然後──我要啟程了。」<br><br>每一次的抵達都會讓我察覺到，<br>這裡只是中繼站。<br><br>因為我從不為旅程設定終點，<br>只要雙腳仍渴望前行，旅途就會持續下去。<br><br>「好了，明天要去哪裡呢？」"},
{index="30265",text="每次想到「不足的東西」，<br>我都會持續堅決地予以否定。<br><br>那並不是一種缺失，<br>只是從一開始就不需要而已。<br><br>摻有雜質的冰，很脆弱。<br>所以我不斷磨練自己，只為成為<br>阻絕任何熱氣滲入的透徹堅冰。<br><br>我不需要那些惱人的羈絆。<br>（──別把我融化）<br><br>只存在於當下的聯繫毫無價值可言。<br>（別碰我。別靠近我──）<br><br>所以……看吧。<br>這下明白了吧？<br>造就強大的絕不是「愛」。<br><br>因為唯有以孤獨律己之人<br>才能到達的領域，確實存在。"},
{index="30266",text="某天，我做了一個奇妙的夢──<br><br>「這裡是……賽場？<br>可是我對這個賽道沒印象……」<br><br>雖然不是什麼值得炫耀的事，<br>但我自認對國內所有的賽道<br>瞭如指掌。<br>然而就在我仍對自己身處何方感到困惑時，<br>出賽前的開場小號響了起來。<br><br>「不、不行……得專心觀看比賽了！<br>今天說不定又會在歷史<br>寫下全新的一頁！」<br><br>我慌忙地將目光投向閘門。<br>眼前的參賽者陣容，豪華到令人目眩。<br><br>「不會吧……<br>往昔和律動的正面對決！？<br>而、而且……連備受矚目的同路線賽馬娘，<br>潘朵拉也參賽了！」<br><br>我興奮地四處張望，<br>然後發現了更大的驚喜。<br><br>「小栗也參賽了！還有城市！<br>這、這簡直就是夢幻對決……<br>要是沒能親眼觀戰，<br>我肯定會後悔到不行……！」<br><br>就在我感動到渾身顫抖時，<br>耳邊忽然傳來一道感覺深藏不露，<br>沉穩而沙啞的聲音。<br><br>「妳繼續待在那裡真的好嗎？<br>妳也得快點準備才行──」<br><br>「咦…………？」<br><br>回過神來，我也站在了閘門前。<br>決勝服隨風飄動，<br>彷彿在說，<br>我已不再只是個觀測者。<br><br>「沒錯……我也……我也要──！」<br><br><br>輕輕上浮的意識，<br>融化了夢的餘韻。<br>眼前是寫到一半的專欄頁面，<br>看來我是寫到途中<br>就這樣睡著了。<br><br>「我以後……也要奔向那樣的『未來』……」<br><br>在那個深夜，我懷抱對未來的期盼，<br>夢想著在歷史刻下自己的蹄跡。"},
{index="30267",text="我是一隻貓，<br>名字叫浮岩光王。<br><br>今天也一如往常，<br>以最快速度巡回曬太陽的好地方，<br>把毛髮打理得蓬蓬鬆鬆柔柔軟軟。<br><br>好忙啊。我要睡了。<br>呼嚕～～～～～～～～<br><br>啊！！！小狗尾巴。<br>別搖來搖去的，站住！<br><br>啊！！！！河裡的魚，好快！<br>難道是黃鰭鮪！我要吃！<br><br>哇啊！！！！！飛機太快了吧！<br>噴射─────！！！<br><br>對了，奔跑時身體要呈直線！<br>鬍鬚朝後方，尾巴要打直！<br><br>垂下耳朵減少風阻！把力量集中於肉球！<br>追上眼前的一切！！<br><br>這就是「最快」！<br>把世界拋在身後的我是最快的！！<br><br>我是浮岩光王！<br>我是一隻貓，而且是最快的貓！！！<br><br>喔喔喔喔喔！<br>喵喵錦標賽，起跑──！！<br><br>喵啊啊啊啊啊啊啊啊！！！！！"},
{index="30268",text="一道道聚光燈劃破黑暗，<br>將劇場照得璀璨奪目。<br><br>踏上舞台，沐浴在光芒中，<br>感覺臉頰略微發熱。<br>蒼藍的禮服依舊像寧靜的海面，<br>我的內心也逐漸變得冷靜而澄澈。<br><br>凝望著舞台正面的貴賓席，<br>從貴賓席守望著我的人──<br>是主君。<br><br>我緩緩吸了一口氣後，開始歌唱。<br>旋律在舞台上迴盪，<br>我感受到觀眾席那股因寂靜而緊繃的氣氛，<br>正漸漸地緩和了下來。<br><br>開場很順利……太好了。<br>安心下來後，歌聲也慢慢響亮了起來。<br>總覺得今天的狀態或許特別好。<br><br>我迅速地將目光投向貴賓席。<br>……主君啊。<br>我要以這首歌，向你宣誓「忠誠」。<br><br>所以請看著我吧。<br>請將為你歌唱的我，以及這段旋律……<br>牢牢地記在心裡。<br><br>主君……我現在是如此地閃耀。<br>在這大舞台上，在聽眾環繞下……<br>為你獻上這一曲！<br><br>……你明白的吧，主君。<br>來！用掌聲與聲援！來回應歌姬吧！<br><br>當然了，若不只想給掌聲也無妨！<br>我也等著你為我<br>起立鼓掌與呼喊安可！<br><br>終曲即將到來！<br>主君！今宵的我，是堂堂歌姬！<br>我已盡情地──唔哇！？<br><br><br>「杜蘭達爾，太慢了。<br>別趴在地板上，快起來。」"},
{index="30269",text="「那麼，慶祝『奇蹟小隊』獲勝，<br>乾杯──」<br><br>「妳在說什麼啊，光王！<br>我們根本連人都還不在店裡耶！！」<br><br>「啊哈哈──所以慶功宴要去哪辦？<br>有什麼想法都可以說喔？我來調查。」<br><br>「欸～我想想，該吃什麼好呢～？<br>……什錦燒？啊，不過偶爾也想<br>對文字燒移情別戀呢～！」<br><br>大家歡談的聲音在河岸迴盪。<br>在耀眼的夕陽下，秋風輕撫過臉頰。<br><br>「哇！文字燒不錯耶！<br>既然這樣，那裡有間不錯的店喔！<br><br>不過那間店的吃到飽限制一小時──<br>嗯～如果要去那邊的話，<br>乾脆再去第二間接著吃吧！？」<br><br>「第二間店啊！不錯耶～！<br>就是所謂的續攤吧～感覺好像大人喔！」<br><br>「……嗯，門禁時間應該沒問題。<br>這主意或許不錯呢。」<br><br>「那第二間絕對要去貓咪咖啡廳。<br>甚至第三間也乾脆去貓咪咖啡廳。<br>我想續攤貓咪咖啡廳。」<br><br>「喂，太狡猾了，怎麼都是妳在選！<br>那我想去中世紀主題的咖啡廳──」<br><br>──我知道。<br>像今天這樣的日子很快就會過去，<br>變成往日回憶的一部分。<br><br>我從小就頻繁地轉學，<br>所以早就明白了。<br><br>就算想永遠待在一起。<br>──這世上也不存在永遠。<br><br>要好的朋友、<br>最喜歡的前輩……<br><br>能和重要的大家在一起的時光，<br>其實只有短短一瞬間──<br><br>正因如此，才需要盡全力！<br>好好享受當下這段時間。<br><br>「我們乾脆在時間允許範圍內！<br>把每間店都逛一遍吧！」<br><br>「喔喔～！」「嗯。」「貓咪、貓咪。」<br>「呵呵……嗯。」<br><br>秋天所剩無幾。<br>冬天即將到來。<br><br>不過不要緊。<br><br>因為和大家一起度過的「今天」，<br>肯定會在未來持續溫暖著我。"},
{index="30270",text="「莎菲，<br>恭喜首次參加狗展！」<br><br>「謝謝妳。<br>不過現在只是剛完成報名而已。」<br><br>「呵呵，妳們肯定會成為颱風眼，<br>掀起一陣旋風吧。」<br><br>「我會去聲援的！還要舉著<br>『大小姐＆莎菲菲Love』的旗子！」<br><br>「目標是天風。<br>若是莎菲的話，肯定辦得到。」<br><br>「不，優勝的話……」<br><br>「不不不，完全有機會吧！？<br>我大小姐和莎菲菲天下無敵！！」<br><br>「對呀。妳要更有自信點──」<br><br>「嗯，所以優勝只是一個過程。<br>我的目標在更遠的前方。<br>我要取得世界大賽參賽資格，<br>讓莎菲之名響徹世界。」<br><br>「世界出道喔，真假！？」<br><br>「原以為只是微風，沒想到是烈風……！」<br><br>「身為一族的成員之一，這是理所當然。<br>……對吧，莎菲。」<br><br>莎菲抬頭短促地哼一聲，<br>回應了第一紅寶。<br>這份緊密的情誼，<br>讓在場的人都不禁露出了微笑。"}
}
p.text_data_163={
{index="1001",text="我叫做特別週！<br>夢想是成為日本第一賽馬娘！<br>為了讓兩個媽媽開心……我會加油唄！"},
{index="1002",text="我是無聲鈴鹿。喜歡跑步。<br>領先位置絕不會讓給任何人。<br>那個……我說完了。"},
{index="1003",text="呀吼～我是東海帝皇喔！<br>我會成為全勝的三冠賽馬娘，<br>絕～對不要錯過我的表現喔！"},
{index="1004",text="嗨～我是丸善斯基唷！<br>你也是來看異次元的奔馳對吧？<br>呵呵♪到時看得無法自拔……我可不管喔♪"},
{index="1005",text="我是逗大家開心的漆黑表演者，<br>富士奇石！我一定會用<br>最棒的「奇蹟」讓你露出笑容！"},
{index="1006",text="我是小栗帽。<br>為了讓故鄉的大家開心，<br>我會盡全力加油。請多指教。"},
{index="1007",text="嘿，我是黃金船大人啦！<br>不管是要上刀山還是要下草皮，甚至要到宇宙盡頭也無所謂！<br>好玩的事情在哪裡，我就往哪裡走☆"},
{index="1008",text="嗨，我是伏特加！我的原則是<br>當個比誰都帥的賽馬娘！<br>看起來很遜的事我絕對不做。給我記住了！"},
{index="1009",text="你好，我是大和赤驥！<br>我會盡全力好好……喔，是你啊。哼！<br>我的目標只有第一。其他結果我都不接受！"},
{index="1010",text="Howdy！我是大樹快車！<br>我會用我充滿力量的奔跑，<br>讓大家都Happy喔～！"},
{index="1011",text="我叫做草上飛。<br>既然生為賽馬娘，我就會努力<br>在這條「道路」上達到極致。呵呵♪"},
{index="1012",text="有很多表情很不錯的傢伙嘛……<br>嘿嘿，就由我菱亞大姐<br>當妳們所有人的對手！來單挑吧！"},
{index="1013",text="我叫做目白麥昆。<br>目白家稱霸「天皇賞」的宿願──<br>我一定會靠自己的雙腳達成。"},
{index="1014",text="在賽道上奔馳的鮮紅怪鳥！<br>神鷹，登、場！<br>放眼世界狂飆起飛吧～！"},
{index="1015",text="哈～哈哈哈！我就是<br>最強、最美的「霸王」好歌劇！<br>來吧，讓我們開拓新的傳說！"},
{index="1016",text="……我是成田白仁。<br>沒有什麼特別需要說的。<br>反正跑下去，遙遙領先然後獲勝就對了。"},
{index="1017",text="我是魯道夫象徵。立志成為站在<br>所有賽馬娘的頂點，領導大家的「皇帝」。<br>懷抱相同志向的同志，與我一同勇往直前吧。"},
{index="1018",text="我是氣槽。只要信念沒有動搖，<br>理想一定會萌芽。為了展現這點，<br>我作為「女帝」會指引眾人前進的。"},
{index="1019",text="辛苦了！我是小數！<br>我支持著許多閃閃發亮的賽馬娘喔！<br>每天都很幸福！生為阿宅真是太好了～♪"},
{index="1020",text="呀呼～我是青雲天空喔～<br>適度又隨便地悠閒過生活吧～<br>……要釣大魚的話，耐心等待也很重要對吧？"},
{index="1021",text="我是玉藻十字！我要在競賽中<br>一贏再贏、百戰百勝、名滿天下！<br>別因為個子小就小看我喔！"},
{index="1022",text="您好，我是美妙姿勢！<br>我希望能在這裡創造很多很棒的回憶。<br>首先我想知道好吃的拉麵店♪"},
{index="1023",text="我是琵琶晨光。我的目標是<br>建立一套完美的勝利方程式……<br>還有，我的頭大小很正常！"},
{index="1024",text="嘿嘿嘿，我是重重喔～☆<br>我最喜歡讓人雀躍的事～<br>還有刺激的事了♪請多指教～！"},
{index="1025",text="……我是曼哈頓咖啡。<br>我有個……想要追上的朋友……<br>是那個一直跑在我前面的女生……看，就在那邊……"},
{index="1026",text="我的名字是美浦波旁。<br>目標設定為三冠賽馬娘。<br>關於我的腳質等資訊，請參閱相關資料。"},
{index="1027",text="我叫目白雷恩！<br>鍛鍊身體充滿活力！培養肌肉，<br>身體健康！拿出幹勁加油吧！"},
{index="1028",text="Buono～♪我是菱曙～☆<br>不論是料理還是跑步，都會注入滿～滿的<br>愛意獻給大家！請多指教囉～♪"},
{index="1029",text="我、我叫做雪之美人！<br>我的夢想是成為在散耀系列賽<br>大為活躍的都市女孩！<br>呼……好好說出來了……"},
{index="1030",text="我……我叫米浴。聽、聽米浴說喔……？<br>米浴會害大家不幸……是個壞孩子。<br>可是……我、我會努力……做出改變的！"},
{index="1031",text="哈囉哈囉～！我是艾尼風神！<br>為了讓所～有家人都開心，<br>不管競賽還是打工，我都會盡全力加油喔～！"},
{index="1032",text="你有沒有興趣知道，賽馬娘究竟能<br>快到什麼地步？要是有的話……<br>就來當我愛麗速子的白老鼠吧。"},
{index="1033",text="我是愛慕織姬。可以走了嗎……？<br>我要進行更多訓練，在更多競賽中拿下勝利，<br>因為我必須成為最明亮的一顆星。"},
{index="1034",text="少囉嗦！我是稻荷一！<br>如你所見，我可是道地的江戶之子！<br>會成為比任何人都厲害的賽馬娘！"},
{index="1035",text="我我我！我的夢想是成為<br>打比賽馬娘！還有……啊──！！名字！！！<br>我是勝利獎券！請多指教喔──！"},
{index="1036",text="我是空中神宮。不管是怎樣的比賽，<br>數據都能說明一切。模擬數值沒有任何問題。<br>所有人都會屈服在我的邏輯之下。"},
{index="1037",text="我叫榮進閃耀。<br>為了守護賽馬娘的傳統，我會持續奔跑下去。<br>無論是什麼競賽，一切都照預定進行。"},
{index="1038",text="Curren就是我，我叫真機伶！<br>想用「可愛」把全世界包起來☆<br>不可以看其他地方，只能看著我喔♪"},
{index="1039",text="哦──呵呵呵！我叫川上公主……<br>氣質高雅，是公主中的翹楚！<br>即使在競賽中，也會用動人的模樣奔馳！！"},
{index="1040",text="我是黃金城市……話說在前頭，<br>可不許把我當成洋娃娃。<br>別從外表，而是從實力來評斷我。"},
{index="1041",text="你好！我是櫻花驀進王！<br>如你所見，我還是個優秀的班長！<br>我要成為大家的典範，衝啊！驀進～！"},
{index="1042",text="呵呵呵呵！我叫採珠！<br>你知道嗎？這世界充滿了可能性。<br>我會證明這點給你看！"},
{index="1043",text="嘎吼～！我是新光風！<br>嚇到了嗎？趕快老實承認你害怕了～！<br>……欸！別不理人！我咬──！"},
{index="1044",text="東商變革是變身前的名字！<br>我是魔法少女Sweepy！<br>這就是魔法！看我的！！（碰）"},
{index="1045",text="呵呵呵，我是超級小溪唷～<br>為了讓大家都能充滿笑容，<br>我會盡全～力好好加油。包在我身上♪"},
{index="1046",text="我是醒目飛鷹～！叫我飛飛吧！<br>我的夢想是成為賽馬娘偶像！<br>隨時都歡迎大家來找我簽名喔☆"},
{index="1047",text="我的名字叫荒漠英雄。那個……<br>別看我這樣，我很嚮往英雄傳說……<br>希望有一天，能在競賽中寫下屬於我的故事……"},
{index="1048",text="我叫島川喬登。夢想是……<br>這種嚴肅的話題對我來說NG，多指教啦～☆<br>總之先看一下我的指甲吧？很炫吧？"},
{index="1049",text="我是中山慶典。<br>對於溫和的競賽感覺不到刺激。<br>欸……再讓我感受更多熱血激情吧……！"},
{index="1050",text="成田大進。就這樣。我只是想<br>一直贏下去，讓曾經瞧不起我的人<br>看到我的實力……不要管我。"},
{index="1051",text="你好，我是西野花。<br>我希望能成為受大家依賴<br>又完美的大姐姐賽馬娘……！"},
{index="1052",text="我叫春烏菈菈！我最～喜歡胡蘿蔔<br>跟跑步了，因為跑起來很開心喔♪<br>目標是第一名，我會超級努力的喔～！"},
{index="1053",text="大家好！我是青竹回憶！<br>我會賭上魔鬼糾察隊長的名號<br>拚命跑下去──！！"},
{index="1054",text="正義英雄，微光飛駒登場！<br>不管怎麼樣的強敵，我的奔馳都能<br>在一瞬間咻咻咻～地擊敗他們，讓大家露出笑容！厲害吧！"},
{index="1055",text="嗨嗨～我是美麗週日～！<br>要把美麗的心情送給全世界喔！<br>來吧，大家也一起美麗～！"},
{index="1056",text="你好，我叫待兼福來！<br>我相信白興大人的神諭，<br>一直期待著哪天能掌握幸福……<br>同時每天也都很努力在占卜！"},
{index="1057",text="有種只在競賽當下才會吹起的風。那是既柔和<br>又清新……自由自在的順風喔。<br>──我是千明代表，請多指教。"},
{index="1058",text="我、我是名將怒濤……！那、那個，<br>我想對自己更有自信，<br>所以盡我所能努綠……吃、吃螺絲了！"},
{index="1059",text="你好……那個，我是目白多伯。<br>我也是目白家的賽馬娘，而且<br>也打算……展現不會使家族蒙羞的奔馳。"},
{index="1060",text="啊……我是優秀素質～啊哈哈。<br>不過感覺還是沒辦法名符其實吧……<br>唉～總之就一點一點努力吧？"},
{index="1061",text="喔～呵呵！我的名字叫帝王光輝。<br>身為一流賽馬娘，一定會創下最棒的成果！<br>……畢竟要向世界展示我的才能嘛！"},
{index="1062",text="哈囉──我是待兼唐懷瑟。<br>為了別輸給大家，今天也要努力練習……<br>什麼，今天休息！？"},
{index="1063",text="我名叫生野狄杜斯。<br>管理方面還請交給我，<br>我會用鋼鐵意志進行徹底管理。"},
{index="1064",text="我是目白善信！今天過得好嗎～？<br>什麼事情都可以跟我說，<br>隨時都能找我聊聊喔♪"},
{index="1065",text="喔耶──！我是大德太陽──！<br>我會在嗨翻天的競賽上猛衝，<br>麻煩給我最高亢的歡呼聲☆"},
{index="1066",text="我是雙渦輪──！<br>渦輪會拿到第一名，一定會拿到！<br>要上囉──渦輪全開────！！"},
{index="1067",text="我叫里見光鑽。<br>沒有命運是一開始就決定好的，<br>未來會被我奔馳的光輝所照亮！"},
{index="1068",text="我是北部玄駒！<br>我的目標是跟大家在如同祭典般<br>熱鬧、最棒的競賽中，盡全力奔馳！"},
{index="1069",text="我、我是櫻花千代王！<br>想要跟崇拜的人一起站上夢想的舞台。<br>這個心願──我會讓它開花結果的！"},
{index="1070",text="我是天狼星象徵！對於競賽<br>沒有什麼想說的。你就默默看著吧。<br>我會征服世界證明自己是最強的。"},
{index="1071",text="我叫目白阿爾丹。雖然這雙腳<br>很脆弱，但我還是想帶著自信奔馳……<br>哪怕只有瞬間也好，我想在競賽中閃耀。"},
{index="1072",text="我是八重無敵。身為<br>金剛八重垣流的門徒，我期望能跟強者競賽。<br>讓我們堂堂正正地一決勝負吧！！"},
{index="1073",text="鶴丸強志！目標是成為自己憧憬的<br>「三冠賽馬娘」！總之盡全力──咳咳！<br>……只、只是嗆到而已！我很好別擔心！"},
{index="1074",text="……哎呀？現在要自我介紹嗎？<br>呵呵，我叫目白光明。<br>身為目白家的一份子，我盡全力加油的～"},
{index="1075",text="我是謀勇兼備。為了嚴厲卻不失溫暖地孕育<br>我的故鄉……我要懷著遠大的夢想，<br>那就是「成為名留青史的賽馬娘」！"},
{index="1076",text="我是櫻花桂冠。我的目標是世界，<br>也就是凱旋門賞！──呵呵，雖然現在還只是<br>「夢想」……但總有一天我一定會實現。"},
{index="1077",text="大家好，我是成田路！<br>我會盡全力表現，來回應大家<br>對我的期待！"},
{index="1078",text="……我是山人西風。<br>我追求的是成為風……比任何事物都要快、<br>都要自由的──風，正是我的目標。"},
{index="1079",text="我是狂熱激昂，不隸屬中央。<br>我是來自船橋的特別留學生。<br>一定會讓大家見識……船橋的強大"},
{index="1080",text="那麼就請多多指教囉～阿訓♪<br>一起去尋找那些無比刺激<br>又令人期待的事物吧！"},
{index="1081",text="我是希望城市！競賽正合我意！<br>我會讓所有人輸到叫苦連天……<br>喂住手！摸什麼摸啊！"},
{index="1082",text="嗨，我是北方飛翔！我喜歡服裝搭配、彩妝、<br>飾品，以及堅持不懈的努力。<br>還請看著我藉由這一切所琢磨出來的光芒！"},
{index="1083",text="──我是克莉斯耶絲象徵。象徵家對我有恩。<br>身為其一員，無論是樹立的目標<br>還是被賦予的mission──都必得達成。"},
{index="1084",text="我是谷水琴蕾！追求目標是理想中的「吾」。<br>我無意以一時的軀殼偽裝自已。<br>破壞、踹破吧──然後朝向終結，前進吧！"},
{index="1085",text="我叫第一紅寶。<br>展現極致的表現，正是我一族的職責所在。<br>我會貫徹己身應盡的責任，向前邁進。"},
{index="1086",text="你想瞭解我嗎？那就到賽場上來吧。<br>目白拉茉奴的……我的一切就在那裡。"},
{index="1087",text="我是小真──奧斯頓真弓。<br>有一天將變成世界的吉祥物。<br>請你一定要親眼見證喔。"},
{index="1088",text="我是里見皇冠哦。我勢必會將榮耀帶給里見。<br>為此我已徹底做好了萬全準備，<br>就連逆境也能成為我的力量！好好期待吧！"},
{index="1089",text="……我是高尚駿逸。那個……雖然我明白<br>說這種話很不自量力，但……總有一天──<br>我、我會成為偉大的……沒事，我會加油的。"},
{index="1090",text="我是極峰。<br>直到突破所有難關成為女王的那一天，<br>我絕不會被挫折打敗！"},
{index="1091",text="我是比布魯斯哦！總有一天我一定要在<br>閃閃發光的杜拜參加名流般的競賽♪<br>我們一起去吧！這件事已經說定了嘛♪"},
{index="1092",text="我是緞通烈焰喔。<br>好了好了，別吵架嘛。<br>吃點甜食，好好加油～如何啊？"},
{index="1093",text="……我是喜嘉奇蹟。<br>為了回報各位給我的生命……<br>我一定會，創造奇蹟。"},
{index="1094",text="我是叢林口袋啦。<br>想賽跑的話，我可以奉陪哦。<br>不過我不會將「最強」寶座拱手讓人就是了。"},
{index="1096",text="呀～哈哈，我正是無需理由！<br>為了統一天下，我將不擇手段。<br>來吧下剋上～！"},
{index="1097",text="我是愛如往昔……我……沒什麼。<br>沒有什麼特別要說的事……<br>真要說的話，就只有……得保密的事……"},
{index="1098",text="Rickey☆Lucky☆大吉利☆<br>我是小林歷奇喔！<br>讓我用風水的力量帶給你happy吧♪"},
{index="1099",text="儂是從北方港灣飛來的紙翼候鳥♪<br>苫小牧的地方偶像──北幸樽前！<br>……嗯～是不是應該再想特別一點的呀？"},
{index="1100",text="我是奇銳駿。雖然看起來悠悠哉哉的，<br>但我其實很擅長一點一滴地努力喔。<br>請多指教囉～"},
{index="1102",text="哦哦，我所深愛的musicista們啊！<br>今天也與我萬籟爭鳴，<br>一起演奏出彼此的melodìa吧！"},
{index="1103",text="唯一的渴望──就是「最強」的稱號！<br>我想成為留在人們記憶中的賽馬娘！<br>為此我需要的……沒錯，就是表現自我！"},
{index="1104",text="我是葛城榮主，多多指教啦！<br>有夢想的話就別畏畏縮縮的喔？<br>讓人喘不過氣的高牆就由我來打破！"},
{index="1105",text="新宇宙提議<br>進行友好的「接觸」。<br>我的意思是──「請多指教囉」。"},
{index="1106",text="嗯，我是菱奇蹟。<br>我會拿出還算過得去？的幹勁盡量努力一下～<br>請多多指教～"},
{index="1107",text="來吧，踏上令人雀躍的旅途！<br>享受與夥伴起舞的每一天！Everyone!<br>想追夢的所有人──快搭上踢踏城市的船吧！"},
{index="1108",text="……我是大鳴大放。<br>我的目標不是勝利，而是更遠大的「最強」。<br>……就這樣。"},
{index="1109",text="我是萊茵實力！繼承意志，<br>開拓出與未來聯繫的道路。<br>我想成為那樣的后冠賽馬娘！"},
{index="1110",text="我的宿願，是戴上后冠，<br>成為光輝未來的基礎。<br>──還請多多指教囉♪"},
{index="1111",text="目標是像母親那樣……強大又華麗的賽馬娘。<br>我是空中彌賽亞──我將親自證明<br>那份傳承的偉大與延續未來的可貴"},
{index="1112",text="Follow my lead! 請拭目以待吧。<br>后冠的光輝必將沐浴在我身上──<br>沐浴在未來的女王，勇敢之心身上！"},
{index="1113",text="我是房一潘朵拉～♡<br>我真的超～天才，不需要別人操心♡<br>所～以～囉～麻煩別用毅力鍛鍊那一套喔♡"},
{index="1114",text="我是迷人景致。我的夢想是<br>實現約定──抵達絕景。<br>還請多多指教，訓練員……呵呵！"},
{index="1115",text="太失敬了，快給我跪下。<br>──伏首跪拜在我黃金巨匠的霸道前吧。"},
{index="1116",text="過程和道理這種東西一點意義也沒有。<br>贏家就是正義，不是嗎？<br>貴婦人會讓一切臣服。"},
{index="1117",text="我是凱旋芭蕾。要成為主角……<br>要成為首席就只能努力不懈！<br>雖然周圍都是強者，但我不會氣餒的！"},
{index="1118",text="我是愛慕律動。<br>我不需要別人對我寬容或溫柔。<br>我只想不斷提升自己……僅此而已。"},
{index="1119",text="若想商量遠征還請找我夢之旅……<br>來場恍若身處夢境般的旅途吧。<br>因為你有著那樣的價值。"},
{index="1120",text="我是浮岩光王。<br>夢想是刷新最高速度，喜歡直線。<br>就這樣。自我介紹也是最快的。"},
{index="1121",text="我的聖劍將釋放疾馳的光輝，<br>斬除加諸於你的黑暗！<br>我是杜蘭達爾，誓言與忠義之騎士！"},
{index="1124",text="我宣告。「身為先鋒隊長，<br>將會掀起四大天王旋風！」<br>我們一起讓夢想膨脹得更大吧！"},
{index="1127",text="是！本官是超常駿驥，隸屬中央特雷森學園！<br>為了成為孩子們的楷模，<br>本官會抱著粉身碎骨的覺悟！"},
{index="1128",text="我是疾風裝束喔！<br>人們很溫柔，所以我最最最喜歡人們了！<br>我想多和人們接觸，感情變得更好喔──！！"},
{index="1129",text="我是杏目。即使對手是傳奇，<br>我也會獲勝。並非別人，<br>而是我自己堅信著這一點！"},
{index="1130",text="我是幸運歐丁香。<br>為了成為賽場焦點，我會忍過各種的試煉。<br>還請多多指教。"},
{index="1131",text="嗨，我是放聲歡呼！<br>不論是0.75哩或是1.25哩，<br>未來的一哩女王是不會輸的！"},
{index="1132",text="我是唯獨愛你♪<br>我的愛不是一廂情願，而是心意相通！<br>一起用直播把愛散播至全世界吧♡"},
{index="1133",text="我是時代創世。<br>最喜歡做的事就是鑽研競賽的歷史。<br>而我自己……也想在歷史刻下自己的蹄跡。"},
{index="1134",text="我是機伶金花。我的興趣是<br>把花擺飾得美美的。還有，我想想……<br>我不太喜歡──和人起紛爭。"},
{index="1135",text="我是黃金旅程，請多指教。<br>來，與我隨興踏上黃金般的旅途，<br>展開一場愉快的旅行吧！"},
{index="9001",text="你好，我是特雷森學園的理事長祕書<br>駿川手綱。為了讓大家過上更好的<br>學園生活，我會支援大家♪"},
{index="9002",text="我是理事長秋川彌生！為了本校學生<br>以及支持她們的訓練員我會竭盡全力！！<br>希望各位可以儘管依賴我！！"},
{index="9004",text="你好，我是桐生院葵，是特雷森學園的<br>新人訓練員。雖然還有許多不成熟之處，<br>但我會為了賽馬娘全力加油！"},
{index="9005",text="我是高超竹針師（的徒弟）安心澤刺刺美。<br>只要被我扎過就會提升威力！<br>Wow，安心～☆"},
{index="9006",text="我是樫本理子。<br>照顧賽馬娘的健康是訓練員的職責。<br>工作時抱持緊張感是理所當然的。"},
{index="9008",text="我是明亮光暈，主要業務是負責活動企畫。<br>請讓我為在舞台上發光發熱的各位……<br>盡一點微薄之力。"},
{index="9040",text="我是達利阿拉伯。每位賽馬娘<br>都有各自的個性，大家都是主角──<br>你可要用心栽培他們哦，小羊！"},
{index="9041",text="我叫高多芬柏布哦。<br>正因為存在著──各種情誼，賽馬娘才得以<br>奔馳下去。我也會助你們一臂之力哦。"},
{index="9042",text="我的名字是拜耶爾土耳其。賽馬娘<br>最重要的就是強悍。讓我鍛鍊她們<br>獲得足以在大地刻下其名的強悍吧。"},
{index="9043",text="我是佐岳鳴！關於歐洲競賽的分析工作<br>就交給我。和我一起達成稱霸「凱旋門賞」<br>這個仍無人達成的夢想吧！"},
{index="9044",text="我是都留岐涼花，<br>每天的工作是企劃製作各種豐富的內容，<br>將最棒的感動獻給各位。"},
{index="9046",text="我是聖烈特。<br>身為日本首位獲得「三冠」的賽馬娘，<br>我將賜予諸位智慧與祝福"},
{index="9047",text="我是速度象徵。<br>我相信你們身上擁有無限的可能性。<br>來吧，讓我們顛覆世界吧"},
{index="9048",text="你好，我是俳成功！<br>身為元祖「小怪物」～……<br>連你的心也要收下了。啊嗚♪"},
{index="9049",text="我的名字是塔可拜茵！我期許能讓各位<br>賽馬娘更上一層樓，因此成立了<br>無人島計畫！來吧，解放本能啦──！"}
}
p.text_data_144={
{index="1001",text="好好加油唄～！<br>朝夢想一路猛衝的單純北海道女孩"},
{index="1002",text="寂靜的疾馳者。<br>追求超越音速的境界"},
{index="1003",text="無敵又可愛！<br>天真爛漫的蹦跳少女"},
{index="1004",text="昭和復古風，<br>超跑大姐姐"},
{index="1005",text="護送工作非我莫屬！<br>華麗的紳士女孩"},
{index="1006",text="地方出身，<br>純樸的酷酷夢想家"},
{index="1007",text="粗暴、奔放！<br>情緒萬變的黃金電波女孩"},
{index="1008",text="狂奔青春！<br>純情不良的公路明星"},
{index="1009",text="唯我獨尊！<br>充滿不服輸精神的傲氣女孩"},
{index="1010",text="出生於美國的<br>友善少女"},
{index="1011",text="清秀可人。<br>自美國歸來的大和撫子"},
{index="1012",text="歡迎單挑！<br>大家的可靠大姐頭宿舍長"},
{index="1013",text="名門目白家的至寶。<br>優雅又專注的大小姐"},
{index="1014",text="北美的怪鳥！<br>活潑奇葩的摔角手"},
{index="1015",text="驕傲自大的歌劇王。<br>大笑聲響徹雲霄！"},
{index="1016",text="用背影傳達一切！<br>硬派的頑固獨行俠"},
{index="1017",text="君臨天下的「皇帝」<br>絕不動搖的權威！"},
{index="1018",text="冷靜理性的「女帝」<br>才貌兼備的女強人"},
{index="1019",text="最愛賽馬娘！<br>超萬能宅女"},
{index="1020",text="我的人生就是要我行我素。<br>漂泊如浮雲……"},
{index="1021",text="閃電般的吐槽<br>展現毅力吧，大阪女孩"},
{index="1022",text="熱愛創造美好回憶<br>深閨長大的美麗淑女"},
{index="1023",text="充滿熱情的知性派。<br>將理論化為武器，起身對抗吧！"},
{index="1024",text="愛撒嬌的老么女孩。<br>好想趕快長大！"},
{index="1025",text="追逐著看不見的身影而奔跑的<br>神秘少女"},
{index="1026",text="絕對遵守指示！<br>改造人賽馬娘"},
{index="1027",text="爽快動感的心情！<br>純粹揮灑閃亮汗水"},
{index="1028",text="大尺碼！大方！大……盤子？<br>請享用美食♪"},
{index="1029",text="目標是成為都市女孩！<br>來自地方的拚命賽馬娘"},
{index="1030",text="不幸體質？<br>堅強活下去的不幸少女"},
{index="1031",text="充滿活力！<br>愛家的勤勞女孩"},
{index="1032",text="禁忌的瘋狂科學家。<br>肉體研究才是一切！"},
{index="1033",text="背負著決心。<br>始終孤傲的明亮之星"},
{index="1034",text="少囉嗦！<br>快如電光石火的自稱江戶之子"},
{index="1035",text="盡情大笑，盡情痛哭！<br>毫不掩飾情感的坦率女孩"},
{index="1036",text="照邏輯來吧！<br>脫離常識的天才女孩"},
{index="1037",text="一切照計畫進行。<br>嚴謹耿直的少女"},
